    runtimeSource: string;
    teammateName: string;
    roleTitle: string;
    workCandidateLabel: string;
    connectionGateLabel: string;
    approvalGateLabel: string;
    payloadContract: "createAITextGenerationPayload.roleContext";
    receiptContract: "aiRuntimeReceipt.runtimeContext";
    handoffContract: "ai_runtime_receipt_to_work_automation_engine_handoff_v1";
