function messageActionsWithReceiptLog(message: ChatMessage): ChatMessageAction[] {
  const actions = message.actions ?? [];
  if (!message.executionReceipt || actions.some((action) => action.label === "실행 로그 확인")) return actions;
  const logAction: ChatMessageAction = { label: "실행 로그 확인", action: "open_office" };
  if (!actions.length) return [logAction];
  return [actions[0], logAction, ...actions.slice(1)];
}

function messageActionsWithReviewLog(message: ChatMessage): ChatMessageAction[] {
  const actions = messageActionsWithReceiptLog(message);
  if (message.executionReceipt || message.workflow?.kind !== "approval_queue" || actions.some((action) => action.label === "실행 로그 확인")) {
    return actions;
  }
  const logAction: ChatMessageAction = { label: "실행 로그 확인", action: "open_office" };
  if (!actions.length) return [logAction];
  return [actions[0], logAction, ...actions.slice(1)];
}

const userVisibleInternalWorkflowLeakPattern =
  /^보관 증거:|^복구 계약:|^후보 생성 차단|^외부 실행 없음|^다음 행동:|^이유: |^해결 버튼:|^다시 이어가기:|^승인 계약:|^사용자 선택:|^최종 실행 게이트:|^필수 조건:|^잠금: |^허용: |^연결 전 원문 읽기|^필요 연결 전 멈춤:|^막힌 이유:|^실행 로그와 승인 기록에 남김|대화\s*라우팅\s*계약|자동화\s*파이프라인|최종\s*실행\s*계약|dry_run_receipt|connector_readiness|mail_or_inquiry_check|reply_draft|라우터\s*증거|승인\s*게이트\s*증거/imu;

function hasUserVisibleInternalWorkflowLeak(text: string) {
  return userVisibleInternalWorkflowLeakPattern.test(text);
}

function stripInternalWorkflowLeakLines(text: string) {
  // 판정만 trim 한 줄로 하고 원본 줄은 유지한다. 예전엔 빈 줄까지 지워
  // 렌더러의 문단 구분(\n{2,})이 사라져 안내가 한 덩어리로 붙어 보였다.
  const visibleLines = text
    .split(/\r?\n/u)
    .filter((line) => !userVisibleInternalWorkflowLeakPattern.test(line.trim()));
  return visibleLines.join("\n").replace(/\n{3,}/gu, "\n\n").trim();
}

function isAIConnectionFirstMessage(message: ChatMessage) {
  return message.role === "assistant" && isAIRuntimeRecoveryWorkflow(message.workflow);
}

                                        
                                                             
function renderChatRichText(text: string) {
  // 같은 글이면 지난번에 만든 요소를 그대로 돌려준다. 요소 객체가 같으면 React 는 그 아래를
  // 비교하지 않고 건너뛰므로, 긴 대화에서도 화면을 다시 그릴 때 옛 답변은 거의 공짜가 된다.
  const cached = chatRichTextCache.get(text);
  if (cached) return cached;
  const rendered = renderChatRichTextUncached(text);
  chatRichTextCache.set(text, rendered);
  if (chatRichTextCache.size > CHAT_RICH_TEXT_CACHE_LIMIT) {
    const oldest = chatRichTextCache.keys().next();
    if (!oldest.done) chatRichTextCache.delete(oldest.value);
  }
  return rendered;
}

const CHAT_RICH_TEXT_CACHE_LIMIT = 600;
const chatRichTextCache = new Map<string, ReturnType<typeof renderChatRichTextUncached>>();

function renderChatRichTextUncached(text: string) {
  const blocks = text.split(/\n{2,}/u);
  return blocks.map((block, blockIndex) => (
    <span key={`chat-block-${blockIndex}`} data-chat-block="true">
      {renderChatBlockContent(block, blockIndex)}
    </span>
  ));
}

// AI 답변의 마크다운 표("| 항목 | 내용 |" + "|---|---|")를 기호 그대로 두지 않고 표로 보여준다.
// 말풍선은 <p> 안이라 <table> 대신 span 격자 + ARIA 표 역할을 쓴다. 칸이 좁아져 글자가 세로로 쪼개지지
// 않도록 열마다 최소 폭을 두고, 넘치면 표만 가로로 스크롤한다.
const CHAT_TABLE_ROW = /^\s*\|.*\|\s*$/u;
const CHAT_TABLE_SEPARATOR = /^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)*\|?\s*$/u;
// 답변이 흘러나오는 동안의 표: 제목 줄만 왔거나 구분선(|---|)이 덜 온 상태, 마지막 행의 닫는 '|'가 아직 안 온 상태.
const CHAT_TABLE_PARTIAL_SEPARATOR = /^\s*\|[\s|:-]*$/u;
const CHAT_TABLE_LINE_START = /^\s*\|/u;

function chatTableCells(line: string) {
  let value = line.trim();
  if (value.startsWith("|")) value = value.slice(1);
  if (value.endsWith("|")) value = value.slice(0, -1);
  return value.split("|").map((cell) => cell.trim());
}

function renderChatInline(line: string, keyPrefix: string) {
  const italicLine = line.match(/^(\s*)\*([^*\n]+)\*\s*$/u);
  if (italicLine) {
    return [italicLine[1], <em key={`${keyPrefix}-em`}>{italicLine[2]}</em>];
  }
  return line.split(/(\*\*[^*\n]+\*\*|`[^`\n]+`)/u).map((piece, pieceIndex) => {
    const key = `${keyPrefix}-${pieceIndex}`;
    if (/^\*\*[^*\n]+\*\*$/u.test(piece)) {
      return <strong key={key}>{piece.slice(2, -2)}</strong>;
    }
    if (/^`[^`\n]+`$/u.test(piece)) {
      return <code key={key}>{piece.slice(1, -1)}</code>;
    }
    return piece;
  });
}

function renderChatBlockContent(block: string, blockIndex: number) {
  const lines = block.split("\n");
  const nodes: ReactNode[] = [];
  let previousWasText = false;
  for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    const line = lines[lineIndex];
    const next = lines[lineIndex + 1];
    // 블록 끝에서 제목 줄(과 덜 온 구분선)만 있는 표는 기호 대신 제목 행만 먼저 보여 준다.
    const headerOnly =
      CHAT_TABLE_LINE_START.test(line) &&
      !CHAT_TABLE_PARTIAL_SEPARATOR.test(line) &&
      (lineIndex === lines.length - 1 || (lineIndex === lines.length - 2 && CHAT_TABLE_PARTIAL_SEPARATOR.test(next ?? "") && !CHAT_TABLE_SEPARATOR.test(next ?? "")));
    if ((CHAT_TABLE_ROW.test(line) && CHAT_TABLE_SEPARATOR.test(next ?? "")) || headerOnly) {
      const columns = chatTableCells(line);
      const rows: string[][] = [];
      let end = headerOnly ? lines.length : lineIndex + 2;
      while (end < lines.length && CHAT_TABLE_ROW.test(lines[end])) {
        const cells = chatTableCells(lines[end]);
        rows.push(columns.map((_, index) => (index === columns.length - 1 ? cells.slice(index).join(" | ") : cells[index] ?? "")));
        end += 1;
      }
      // 마지막 행이 아직 쓰이는 중이면(닫는 '|' 전) 표 밑에 기호로 새지 않게 같은 표의 행으로 붙인다.
      if (end === lines.length - 1 && CHAT_TABLE_LINE_START.test(lines[end])) {
        const cells = chatTableCells(lines[end]);
        rows.push(columns.map((_, index) => cells[index] ?? ""));
        end += 1;
      }
      const tableKey = `chat-table-${blockIndex}-${lineIndex}`;
      nodes.push(
        <span
          key={tableKey}
          className={styles.chatTable}
          role="table"
          data-chat-table-columns={columns.length}
          style={{ "--chat-table-columns": columns.length } as CSSProperties}
        >
          <span role="row">
            {columns.map((cell, cellIndex) => (
              <span key={`${tableKey}-h-${cellIndex}`} role="columnheader">
                {renderChatInline(cell, `${tableKey}-h-${cellIndex}`)}
              </span>
            ))}
          </span>
          {rows.map((row, rowIndex) => (
            <span key={`${tableKey}-r-${rowIndex}`} role="row">
              {row.map((cell, cellIndex) => (
                <span key={`${tableKey}-c-${rowIndex}-${cellIndex}`} role="cell">
                  {renderChatInline(cell, `${tableKey}-c-${rowIndex}-${cellIndex}`)}
                </span>
              ))}
            </span>
          ))}
        </span>,
      );
      previousWasText = false;
      lineIndex = end - 1;
      continue;
    }
    nodes.push(
      <span key={`chat-line-${blockIndex}-${lineIndex}`}>
        {previousWasText ? <br /> : null}
        {renderChatInline(line, `chat-piece-${blockIndex}-${lineIndex}`)}
      </span>,
    );
    previousWasText = true;
  }
  return nodes;
}

// 메시지 객체는 바뀔 때 통째로 새 객체로 바뀐다(제자리 수정 없음). 그래서 객체를 열쇠로
// 표시용 결과를 기억해 두면, 화면을 다시 그릴 때 옛 메시지의 정규식 처리를 되풀이하지 않는다.
const visibleChatMessageTextCache = new WeakMap<ChatMessage, string>();
const visibleMessageActionsCache = new WeakMap<ChatMessage, ChatMessageAction[]>();
const workPatternSaveEligibilityCache = new WeakMap<ChatMessage, boolean>();

function visibleChatMessageText(message: ChatMessage) {
  const cached = visibleChatMessageTextCache.get(message);
  if (cached !== undefined) return cached;
  const text = computeVisibleChatMessageText(message);
  visibleChatMessageTextCache.set(message, text);
  return text;
}

function computeVisibleChatMessageText(message: ChatMessage) {
  if (isAIConnectionFirstMessage(message)) {
    // 연결 여부를 단정하지 않는다 — 이 카드는 "아직 연결 전"만이 아니라 연결 후
    // 호출 실패(만료·타임아웃)에도 뜬다. "연결 안 됐어요"라고 말하면 레일의
    // "연결됨" 배지와 한 화면에서 모순되는 거짓말이 된다.
    return "방금 요청은 잘 보관해뒀어요. 지금은 AI 답변 연결이 확인되지 않아서요 — 연결이 확인되면 바로 이어서 처리할게요.";
  }
  // 앱이 합성한 내부 워크플로 덤프만 정제합니다. 판별은 두 조건을 함께 봅니다.
  //  - aiRuntimeProof 없음: 진짜 모델 답변은 절대 손대지 않는다.
  //  - workflow/actions 있음: 앱 합성 카드의 표식. 일반 대화 답변은 둘 다 없이 저장되므로
  //    이 조건이 없으면 '자동화 파이프라인' 같은 흔한 말이 섞인 정상 답변이 통째로
  //    "필요한 준비가 먼저 있어요…"(버튼도 없는 문구)로 바뀌어 사용자에겐 답을 먹은 것처럼 보였다.
  const appComposedCard = Boolean(message.workflow) || (message.actions?.length ?? 0) > 0;
  if (
    message.role === "assistant" &&
    !message.aiRuntimeProof &&
    appComposedCard &&
    hasUserVisibleInternalWorkflowLeak(message.text)
  ) {
    return stripInternalWorkflowLeakLines(message.text) || "필요한 준비가 먼저 있어요. 아래 버튼에서 다음 행동만 선택하면 됩니다.";
  }
  // 말풍선은 마크다운을 렌더하지 않으므로 표시 직전에 강조 기호를 걷어냅니다.
  // 커밋 시점에만 걷어내면 스트리밍 중간 델타·위임 답변·저장된 옛 대화에서 **가 그대로 보입니다.
  return stripChatMarkdownEmphasis(message.text);
}

function visibleMessageActions(message: ChatMessage): ChatMessageAction[] {
  const cached = visibleMessageActionsCache.get(message);
  if (cached) return cached;
  const actions = messageActionsWithReviewLog(message);
  const visible = isAIConnectionFirstMessage(message) ? [] : withSaveAsDocumentAction(message, actions);
  visibleMessageActionsCache.set(message, visible);
  return visible;
}

/** 메모·보고서·표처럼 정리된 AI 답변은 복사 없이 바로 문서 파일로 이어 갈 수 있게 [문서로 저장]을 앞에 둔다. */
function withSaveAsDocumentAction(message: ChatMessage, actions: ChatMessageAction[]): ChatMessageAction[] {
  if (message.role !== "assistant" || !message.aiRuntimeProof || actions.some((action) => action.saveAsDocumentTitle)) return actions;
  const text = String(message.text ?? "");
  const structured = /(^|\n)\s*(\|.*\||#{1,6}\s|[-•]\s|\d+\.\s)/u.test(text);
  if (text.length < 280 || !structured) return actions;
  return [{ label: "문서로 저장", saveAsDocumentTitle: answerDocumentTitle(text), saveAsDocumentSource: "AI 직원 답변" }, ...actions];
}

function answerDocumentTitle(text: string) {
  const lines = text
    .split(/\r?\n/u)
    .map((line) => line.replace(/^#{1,6}\s+/u, "").replace(/\*\*/gu, "").trim())
    .filter(Boolean);
  const candidate = lines.find((line, index) => index < 8 && line.length >= 4 && line.length <= 40 && !/[.。!?:]$|님,|^\||^[-•*]\s|^\d+\.\s/u.test(line));
  return `${(candidate ?? "AI 정리 문서").slice(0, 60)} ${new Date().toLocaleDateString("sv-SE")}`;
}

/**
 * 대화에 저장된 버튼이 실제로 할 일.
 *
 * AI 복구 카드의 '대체 답변 연결'은 예전부터 external_accounts(외부 사이트 비밀번호
 * 보관함)로 저장돼 있다. 이미 저장된 대화에도 남아 있으므로, 누를 때 AI 를 고르는
 * 목록으로 바꿔 연다. 다른 버튼은 저장된 그대로 실행한다.
 */
function resolveChatMessageHomeAction(action: ChatMessageAction): HomeAction {
  if (action.action === "external_accounts" && action.label === "대체 답변 연결") return "ai_alternatives";
  return action.action!;
}

