type MemorySearchResult = {
  id: string;
  kind: "저장한 방식" | "학습 출처" | "자료 인덱스" | "메일 근거" | "승인 후보" | "본문 근거" | "복원 기억" | "연결 복구";
  title: string;
  detail: string;
  meta: string;
  relevanceLabel?: string;
  relevanceReason?: string;
  matchedTerms?: string[];
  safetyLabel: string;
  nextUserChoice: string;
  suggestedPrompt: string;
  sourcePath?: string;
};

type MemorySearchDraftApproval = {
  id: string;
  title: string;
  resultKind: MemorySearchResult["kind"];
  outputText: string;
  safetyLabel: string;
  nextUserChoice: string;
  queueItem: LocalMemoryDelegationActionQueueRecord;
  createdAt: string;
  stagedWorkItem?: WorkItem;
};

function buildMemorySearchResults(
  memory: LocalMemoryStatusResult | null,
  query: string,
  promptContext = "",
  documentIndexResults: DocumentLearningSearchResult[] = [],
  mailEvidenceItems: WorkItem[] = [],
  approvalItems: WorkItem[] = [],
): MemorySearchResult[] {
  if (!memory) return [];
  const terms = normalizeMemorySearchTerms(query);
  const rows: Array<MemorySearchResult & { score: number; text: string }> = [];
  for (const pattern of memory.workPatterns ?? []) {
    const title = pattern.sourceLabel || "저장한 방식";
    const detail = pattern.summary || "저장한 업무 처리 방식";
    const text = [title, detail, pattern.teammateName, ...(pattern.signals ?? [])].join(" ");
    rows.push({
      id: `pattern-${pattern.id}`,
      kind: "저장한 방식",
      title,
      detail,
      meta: [pattern.teammateName, pattern.learnedAt ? formatShortDate(pattern.learnedAt) : "", "승인 전 실행 잠금"].filter(Boolean).join(" · "),
      safetyLabel: "저장한 방식은 참고 기준이며 실행은 승인 전 잠금",
      nextUserChoice: "질문에 넣기 후 보내기 전에 수정",
      suggestedPrompt: `${detail} 방식으로 처리해줘. 외부 발송이나 파일 변경은 실행 전 다시 확인해줘.`,
      sourcePath: pattern.artifactPaths?.[0] ?? "memory/work-patterns/WorkPatternMemory.md",
      score: scoreMemorySearchText(text, terms),
      text,
    });
  }
  for (const source of memory.learningSources ?? []) {
    const title = source.label || source.path || "학습 출처";
    const detail = source.lastSummary || `${source.fileCount ?? 0}개 파일을 원본 변경 없이 참고하는 자료 출처`;
    const text = [title, detail, source.path, source.sourceKind].join(" ");
    rows.push({
      id: `source-${source.id}`,
      kind: "학습 출처",
      title,
      detail,
      meta: [source.sourceKind, `${source.fileCount ?? 0}개`, "원본 유지"].filter(Boolean).join(" · "),
      safetyLabel: "원본 파일은 읽기 전용으로 참고",
      nextUserChoice: "자료를 기준으로 질문 작성",
      suggestedPrompt: `${title} 자료를 먼저 참고해서 답해줘. 원본 파일은 수정하지 말고 필요한 확인만 알려줘.`,
      sourcePath: "memory/documents/LearningSources.md",
      score: scoreMemorySearchText(text, terms),
      text,
    });
  }
  for (const document of documentIndexResults) {
    const title = document.title || "학습 문서";
    const detail = document.summary || "자료 학습 인덱스에서 찾은 문서 근거";
    const text = [title, detail, document.path, document.kind, ...(document.matchedTerms ?? [])].join(" ");
    rows.push({
      id: `document-index-${document.id}`,
      kind: "자료 인덱스",
      title,
      detail,
      meta: [document.kind || "문서", document.matchedTerms?.length ? `일치 ${document.matchedTerms.length}개` : "", "원본 읽기 전용"].filter(Boolean).join(" · "),
      safetyLabel: "자료 인덱스 근거만 사용하고 원본 변경 금지",
      nextUserChoice: "문서 근거를 질문에 넣기",
      suggestedPrompt: `${title} 문서의 "${detail}" 근거를 참고해서 답해줘. 원본 파일은 수정하지 말고 필요한 승인 작업만 알려줘.`,
      sourcePath: document.path || "ModyCrew_Local_Index/modycrew-document-index.json",
      score: scoreMemorySearchText(text, terms) + (document.score ?? 0),
      text,
    });
  }
  for (const item of mailEvidenceItems) {
    const evidence = item.sourceEvidence;
    if (!evidence) continue;
    const title = evidence.messageSubject || item.title || "메일 원문 근거";
    const detail = createMailEvidenceSearchDetail(item);
    const intentLabels = evidence.detectedIntentLabels ?? [];
    const approvalLabels = evidence.approvalCandidateLabels ?? [];
    const text = [
      title,
      detail,
      item.summary,
      item.body,
      item.sourceLabel,
      item.senderLabel,
      evidence.senderPreview,
      evidence.messageSnippet,
      evidence.mailThreadLabel,
      evidence.draftPreview,
      evidence.calendarCandidateText,
      ...intentLabels,
      ...approvalLabels,
    ].join(" ");
    rows.push({
      id: `mail-evidence-${item.id}`,
      kind: "메일 근거",
      title,
      detail,
      meta: [
        evidence.mailboxLabel || item.sourceLabel || "메일함",
        evidence.senderPreview || item.senderLabel,
        intentLabels.length ? `의도 ${intentLabels.length}개` : "",
        approvalLabels.length ? `승인 후보 ${approvalLabels.length}개` : "",
        "읽기 전용",
      ].filter(Boolean).join(" · "),
      safetyLabel: "메일 원문은 읽기 전용, 발송/일정 등록은 승인 후보로만 생성",
      nextUserChoice: "메일 근거를 질문에 넣고 승인함에서 확인",
      suggestedPrompt: `${title} 메일 근거를 기준으로 답장/일정/확인 항목을 정리해줘. 원문 삭제, 이동, 발송, 일정 등록은 승인 후보로만 만들어줘.`,
      sourcePath: evidence.mailThreadLabel || evidence.connectorId || "메일 원문 근거",
      score: scoreMemorySearchText(text, terms) + 0.5,
      text,
    });
  }
  for (const item of approvalItems) {
    const title = item.title || "승인 후보";
    const detail = item.summary || item.draft?.body || "오피스 승인함에서 확인할 업무 후보";
    const text = [title, detail, item.sourceLabel, item.status, item.finalAction?.label, item.browserTask?.host].join(" ");
    rows.push({
      id: `approval-${item.id}`,
      kind: "승인 후보",
      title,
      detail,
      meta: [item.sourceLabel || "오피스", item.status === "approval_pending" ? "승인 대기" : item.status, item.finalAction?.label].filter(Boolean).join(" · "),
      safetyLabel: "오피스 승인함에서 실행하기, 고쳐달라고 하기, 보류하기를 직접 선택",
      nextUserChoice: "승인함에서 미리보기 확인",
      suggestedPrompt: `${title} 승인 후보를 기준으로 다음 행동을 정리해줘. 실행은 오피스 승인함에서 최종 확인 후 진행해줘.`,
      sourcePath: "오피스 승인함",
      score: scoreMemorySearchText(text, terms) + (item.status === "approval_pending" ? 0.6 : 0.1),
      text,
    });
  }
  for (const section of extractPromptContextMemoryResults(promptContext, terms)) {
    rows.push(section);
  }
  for (const recovery of memory.connectorRecoveryMemories ?? []) {
    const title = recovery.actionLabel || recovery.connectorId || "연결 복구";
    const detail = recovery.summary || "이전에 막혔던 연결 복구 방식";
    const text = [title, detail, recovery.connectorId, recovery.recoveryKind, ...(recovery.signals ?? [])].join(" ");
    rows.push({
      id: `recovery-${recovery.id}`,
      kind: "연결 복구",
      title,
      detail,
      meta: [recovery.connectorId, recovery.status, "보관함/승인 재확인"].filter(Boolean).join(" · "),
      safetyLabel: "계정 보관함과 권한은 사용자 확인 후 재연결",
      nextUserChoice: "연결 상태를 먼저 확인",
      suggestedPrompt: `${title} 연결 상태를 먼저 확인하고, 막히면 보관함과 승인함으로 우회해줘.`,
      sourcePath: "memory/growth/SkillGrowth.md",
      score: scoreMemorySearchText(text, terms),
      text,
    });
  }
  for (const suggestion of memory.growthSuggestions ?? []) {
    const title = suggestion.title || suggestion.skillLabel || "복원 기억";
    const detail = suggestion.reason || suggestion.nextAction || "이전 업무에서 추천된 다음 준비";
    const text = [title, detail, suggestion.skillLabel, suggestion.nextAction, ...(suggestion.connectorIds ?? [])].join(" ");
    rows.push({
      id: `growth-${suggestion.id}`,
      kind: "복원 기억",
      title,
      detail,
      meta: [suggestion.skillLabel, suggestion.priority, "사용자 확인 후 활성"].filter(Boolean).join(" · "),
      safetyLabel: "추천 도구는 사용자가 켠 뒤에만 활성",
      nextUserChoice: "적용 전 미리보기",
      suggestedPrompt: `${title}을 이번 업무에 적용할지 먼저 미리보기로 확인해줘.`,
      sourcePath: "memory/growth/SkillGrowth.md",
      score: scoreMemorySearchText(text, terms),
      text,
    });
  }
  return rows
    .map((row) => {
      const relevance = evaluateMemorySearchResultRelevance(row, query, terms);
      return {
        ...row,
        score: row.score + relevance.bonus,
        relevanceLabel: relevance.label,
        relevanceReason: relevance.reason,
        matchedTerms: relevance.matchedTerms,
        isSpecific: relevance.isSpecific,
      };
    })
    .filter((row) => row.isSpecific)
    .sort((a, b) => b.score - a.score || a.title.localeCompare(b.title, "ko"))
    .map(({ score: _score, text: _text, isSpecific: _isSpecific, ...row }) => row);
}

function buildMemorySearchDraftPrompt(result: MemorySearchResult): string {
  return [
    "아래 지난 업무 검색 결과를 참고해서 사용자가 바로 검토할 수 있는 업무 초안을 작성하세요.",
    "기술 용어, 내부 도구 이름, 복잡한 실행 방식은 말하지 마세요.",
    "외부 발송, 일정 등록, 파일 변경, 파일 삭제, 결제, 계약, 세무, 공공기관 제출은 실행했다고 말하지 말고 오피스 승인 후보로만 표현하세요.",
    `검색 종류: ${result.kind}`,
    `제목: ${result.title}`,
    `요약: ${result.detail}`,
    `근거: ${result.meta}`,
    result.relevanceReason ? `추천 이유: ${result.relevanceReason}` : "",
    `안전 경계: ${result.safetyLabel}`,
    `다음 선택: ${result.nextUserChoice}`,
    result.sourcePath ? `출처: ${result.sourcePath}` : "",
    `사용자 요청 후보: ${result.suggestedPrompt}`,
    "출력 형식: 1) 바로 쓸 초안 2) 확인할 점 3) 승인함에서 확인할 일.",
  ].filter(Boolean).join("\n");
}

function memorySearchFollowupAction(result: MemorySearchResult): HomeAction {
  if (result.kind === "메일 근거") return "mailops_check";
  if (result.kind === "승인 후보") return "open_office";
  if (result.kind === "학습 출처" || result.kind === "자료 인덱스" || result.kind === "본문 근거") return "learn_files";
  if (result.kind === "연결 복구") return "external_accounts";
  return "memory_inspect";
}

function createMemorySearchDraftQueueItem(input: {
  result: MemorySearchResult;
  outputText: string;
  teammate?: AITeammate;
  threadId: string;
}): LocalMemoryDelegationActionQueueRecord {
  const createdAt = new Date().toISOString();
  const safeTitle = input.result.title.trim() || "지난 업무 초안";
  return {
    id: `memory-search-draft-${Date.now()}`,
    artifactId: `memory-search-draft-${input.result.id}`,
    artifactKind: "memory_search_draft",
    artifactTitle: `${safeTitle} 승인 요청`,
    actionKind: "execution_candidate",
    status: "approval_pending",
    label: "지난 업무 초안 실행 후보",
    createdAt,
    note: [
      `검색 종류: ${input.result.kind}`,
      `안전 경계: ${input.result.safetyLabel}`,
      `다음 선택: ${input.result.nextUserChoice}`,
      input.result.sourcePath ? `출처: ${input.result.sourcePath}` : "",
      `초안: ${compactInlineText(input.outputText, 420)}`,
      "외부 발송, 일정 등록, 파일 변경, 삭제는 앱의 마지막 확인 전까지 실행하지 않습니다.",
    ].filter(Boolean).join("\n"),
    relativePath: input.result.sourcePath || "memory/work-patterns/WorkPatternMemory.md",
    sourceTeammateId: input.teammate?.id,
    teammateName: input.teammate?.name ?? "업무 비서",
    sourceThreadId: input.threadId,
    externalMutation: false,
    rawSecretMaterialStored: false,
    rawSecretMaterialReturned: false,
  };
}

function createDocumentReportDraftQueueItem(input: {
  candidate: DocumentReportCandidateState;
  teammate?: AITeammate;
  threadId: string;
  outputText: string;
}): LocalMemoryDelegationActionQueueRecord {
  const createdAt = new Date().toISOString();
  const title = `${input.candidate.output || "보고서 초안"} 저장 확인`;
  return {
    id: `document-report-draft-${Date.now()}`,
    artifactId: `document-report-draft-${createdAt.replace(/[:.]/gu, "-")}`,
    artifactKind: "report_draft_file",
    artifactTitle: title,
    actionKind: "execution_candidate",
    status: "approval_pending",
    label: "보고서 초안 저장 후보",
    createdAt,
    note: [
      `자료 범위: ${input.candidate.sourceScope}`,
      `만들 결과: ${input.candidate.output}`,
      `문서 형식: ${input.candidate.format}`,
      `승인 기준: ${input.candidate.approval}`,
      `초안: ${compactInlineText(input.outputText, 420)}`,
      "파일 저장, 외부 공유, 제출은 앱의 마지막 확인 전까지 실행하지 않습니다.",
    ].join("\n"),
    relativePath: "memory/delegations/DocumentReportDrafts.md",
    sourceTeammateId: input.teammate?.id,
    teammateName: input.teammate?.name ?? "업무 비서",
    sourceThreadId: input.threadId,
    externalMutation: false,
    rawSecretMaterialStored: false,
    rawSecretMaterialReturned: false,
  };
}

function isMailEvidenceWorkItem(item: WorkItem): boolean {
  return Boolean(item.sourceEvidence) && /mail|email|gmail|outlook|imap|메일/iu.test(
    [item.source, item.sourceLabel, item.sourceEvidence?.mailboxLabel, item.sourceEvidence?.messageSubject].join(" "),
  );
}

function createMailEvidenceSearchDetail(item: WorkItem): string {
  const evidence = item.sourceEvidence;
  const parts = [
    evidence?.messageSnippet,
    evidence?.draftPreview ? `초안: ${evidence.draftPreview}` : "",
    evidence?.calendarCandidateText ? `일정 후보: ${evidence.calendarCandidateText}` : "",
    item.summary,
    item.body,
  ]
    .map((part) => part?.trim())
    .filter(Boolean);
  return parts[0]?.slice(0, 180) || "메일 원문에서 찾은 제목, 발신자, 의도, 승인 후보 근거";
}

function extractPromptContextMemoryResults(
  promptContext: string,
  terms: string[],
): Array<MemorySearchResult & { score: number; text: string }> {
  if (!promptContext.trim()) return [];
  const sections = [...promptContext.matchAll(/^##\s+(.+)\n([\s\S]*?)(?=\n##\s+|\s*$)/gmu)];
  const interestingLabels = new Set([
    "MailOpsPromptMemory",
    "WriterPromptMemory",
    "WorkPatternMemory",
    "DecisionMemory",
    "CrewContext",
    "ConversationDigest",
    "LongMemoryIndex",
  ]);
  return sections
    .filter((match) => interestingLabels.has(match[1].trim()))
    .flatMap((match) => {
      const label = match[1].trim();
      const lines = match[2]
        .split("\n")
        .map((line) => line.replace(/^[-*]\s*/u, "").trim())
        .filter((line) => line.length >= 8 && !/^#|updated:|patterns:/iu.test(line))
        .slice(0, 12);
      return lines.map((line, index) => {
        const kind: MemorySearchResult["kind"] =
          label === "MailOpsPromptMemory" || label === "WriterPromptMemory" ? "본문 근거" : "복원 기억";
        const text = `${label} ${line}`;
        return {
          id: `context-${label}-${index}`,
          kind,
          title: memorySectionUserLabel(label),
          detail: line,
          meta: `${memorySectionUserLabel(label)} · 보안 입력값 원문 없음`,
          safetyLabel: "본문 기억은 요약 근거이며 외부 실행은 승인 전 잠금",
          nextUserChoice: "기억 근거를 질문에 넣기",
          suggestedPrompt: `${line} 근거를 참고해서 답해줘. 외부 발송, 일정 등록, 파일 변경은 승인 전 다시 확인해줘.`,
          sourcePath: memorySectionSourcePath(label),
          score: scoreMemorySearchText(text, terms),
          text,
        } satisfies MemorySearchResult & { score: number; text: string };
      });
    });
}

function memorySectionSourcePath(label: string): string {
  if (label === "MailOpsPromptMemory") return "memory/prompt/crewkit/MailOpsPromptMemory.md";
  if (label === "WriterPromptMemory") return "memory/prompt/crewkit/WriterPromptMemory.md";
  if (label === "DecisionMemory") return "memory/decisions/DecisionMemory.md";
  if (label === "WorkPatternMemory") return "memory/work-patterns/WorkPatternMemory.md";
  if (label === "ConversationDigest") return "memory/chat/ConversationDigest.md";
  return "memory/prompt/PromptMemory.md";
}

function memorySectionUserLabel(label: string): string {
  if (label === "MailOpsPromptMemory") return "메일 업무 기억";
  if (label === "WriterPromptMemory") return "문서 업무 기억";
  if (label === "WorkPatternMemory") return "지난 업무 방식";
  if (label === "DecisionMemory") return "결정 기록";
  if (label === "CrewContext") return "현재 팀원 맥락";
  if (label === "ConversationDigest") return "대화 요약 기억";
  if (label === "LongMemoryIndex") return "오래된 기억 색인";
  return "답변 기준 기억";
}

function normalizeMemorySearchTerms(query: string): string[] {
  return query
    .toLowerCase()
    .split(/[\s,./|]+/u)
    .map((term) => term.trim())
    .filter((term) => term.length >= 2)
    .slice(0, 8);
}

function scoreMemorySearchText(text: string, terms: string[]): number {
  if (!terms.length) return 1;
  const normalized = text.toLowerCase();
  return terms.reduce((score, term) => score + (normalized.includes(term) ? 1 : 0), 0);
}

function evaluateMemorySearchResultRelevance(
  row: MemorySearchResult & { score: number; text: string },
  query: string,
  terms: string[],
) {
  if (terms.length === 0) {
    return {
      isSpecific: true,
      bonus: 0,
      label: "최근 기억",
      reason: "검색어 없이 전체 후보를 보는 중",
      matchedTerms: [],
    };
  }
  const normalized = row.text.toLowerCase();
  const matchedTerms = terms.filter((term) => normalized.includes(term));
  const requestFileHints = inferWorkPatternFileHints(query);
  const resultFileHints = inferWorkPatternFileHints([row.title, row.detail, row.text, row.sourcePath ?? ""].join(" "));
  const matchedFileHints = requestFileHints.filter((hint) => resultFileHints.includes(hint));
  const sourceKindMatched = isSpecificMemorySearchKindMatch(row, query);
  const hasSpecificEvidence =
    matchedTerms.length >= 2 ||
    matchedFileHints.length > 0 ||
    (sourceKindMatched && matchedTerms.length >= 1);
  const reasonParts = [
    matchedFileHints.length ? `파일 힌트: ${matchedFileHints.join(", ")}` : "",
    matchedTerms.length ? `겹친 단어: ${matchedTerms.slice(0, 4).join(", ")}` : "",
    sourceKindMatched ? "업무 종류 일치" : "",
  ].filter(Boolean);
  return {
    isSpecific: hasSpecificEvidence && row.score > 0,
    bonus: matchedFileHints.length * 2 + (sourceKindMatched ? 0.5 : 0),
    label: matchedFileHints.length
      ? "파일 단서 일치"
      : matchedTerms.length >= 2
        ? `핵심 단어 ${matchedTerms.length}개 일치`
        : sourceKindMatched
          ? "업무 종류와 단어 일치"
          : "넓은 후보",
    reason: reasonParts.length ? reasonParts.join(" · ") : "업무 종류만 비슷해 숨김",
    matchedTerms: matchedTerms.slice(0, 5),
  };
}

function isSpecificMemorySearchKindMatch(
  row: {
    kind: MemorySearchResult["kind"];
    title: string;
    detail: string;
    text: string;
  },
  query: string,
) {
  const lowerQuery = query.toLowerCase();
  const lowerText = [row.kind, row.title, row.detail, row.text].join(" ").toLowerCase();
  if (/(메일|이메일|email|답장|문의|캘린더|일정|예약)/u.test(lowerQuery)) {
    return /(메일|mail|email|답장|문의|캘린더|일정|예약)/u.test(lowerText);
  }
  if (/(xlsx|xls|엑셀|excel|스프레드시트|시트|정산표|매출표|견적서|계산서)/u.test(lowerQuery)) {
    return /(xlsx|xls|엑셀|excel|스프레드시트|시트|정산표|매출표|견적서|계산서)/u.test(lowerText);
  }
  if (/(pdf|docx|doc|워드|word|보고서|제안서|계약서|신청서|공문|스캔)/u.test(lowerQuery)) {
    return /(pdf|docx|doc|워드|word|보고서|제안서|계약서|신청서|공문|스캔|문서 업무)/u.test(lowerText);
  }
  if (/(승인|발송|등록|최종 확인|실행 후보)/u.test(lowerQuery)) {
    return /(승인|발송|등록|최종 확인|실행 후보|오피스 승인함)/u.test(lowerText);
  }
  if (/(연결|로그인|계정|oauth|권한|복구)/u.test(lowerQuery)) {
    return /(연결|로그인|계정|oauth|권한|복구)/u.test(lowerText);
  }
  return false;
}

function formatShortDate(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return date.toLocaleDateString("ko-KR", { month: "numeric", day: "numeric" });
}

function formatLocalAutomationNextCheckLabel(rule: LocalAutomationRule): string {
  if (!rule.enabled) return "꺼짐";
  if (!rule.lastRunAt) return `${rule.cadenceMinutes}분 주기 · 첫 점검 전`;
  const lastRun = new Date(rule.lastRunAt);
  if (Number.isNaN(lastRun.getTime())) return `${rule.cadenceMinutes}분 주기`;
  const nextRun = new Date(lastRun.getTime() + Math.max(1, Number(rule.cadenceMinutes ?? 5)) * 60_000);
  return nextRun.toLocaleString("ko-KR");
}

function formatLocalAutomationNotificationDraftLabel(rule: LocalAutomationRule): string {
  const stats = rule.latestRunStats;
  if (!rule.enabled) return "규칙을 켜면 앱 승인함 초안을 준비합니다.";
  if (!stats) return "최근 점검 후 앱 승인함 초안 표시";
  const approval = Number(stats.approvalQueue ?? 0);
  const ignored = Number(stats.ignoredMail ?? 0);
  const attachment = Number(stats.attachmentCandidates ?? 0);
  if (approval > 0 || ignored > 0 || attachment > 0) {
    return `앱 승인함 초안 · 승인 ${approval}건 · 광고 제외 ${ignored}건 · 첨부 ${attachment}건`;
  }
  return "승인 후보 없음 · 외부 알림 없음";
}

function inferNextAutomationCheckAt(rule: LocalAutomationRule, fallbackLastRunAt = ""): string {
  if (!rule.enabled) return "";
  const basis = rule.lastRunAt || fallbackLastRunAt;
  if (!basis) return "";
  const lastRun = new Date(basis);
  if (Number.isNaN(lastRun.getTime())) return "";
  const minutes = Math.max(1, Number(rule.cadenceMinutes ?? 5));
  return new Date(lastRun.getTime() + minutes * 60_000).toISOString();
}

function koreanObjectParticle(value: string): "을" | "를" {
  const last = value.trim().charCodeAt(value.trim().length - 1);
  if (last < 0xac00 || last > 0xd7a3) return "를";
  return (last - 0xac00) % 28 === 0 ? "를" : "을";
}

