function findMailRecipientListFileCandidate(files: DocumentLearningFileRecord[]): MailRecipientListFileCandidate | null {
  for (const file of files) {
    const filePath = (file.absolutePath || file.path || "").trim();
    const fileName = (file.fileName || file.name || filePath.split(/[\\/]/u).pop() || "메일 발송 명단").trim();
    const extension = fileName.split(".").pop()?.toLowerCase() ?? "";
    const sourceType =
      extension === "csv"
        ? "csv"
        : extension === "tsv"
          ? "tsv"
          : extension === "xlsx" || extension === "xlsm" || extension === "xls"
            ? "xlsx"
            : "";
    if (filePath && sourceType) return { filePath, fileName, sourceType };
  }
  return null;
}

