function compactInlineText(text: string, maxLength: number) {
  const normalized = text.replace(/\s+/gu, " ").trim();
  if (normalized.length <= maxLength) return normalized;
  return `${normalized.slice(0, Math.max(0, maxLength - 1)).trim()}…`;
}

type ChatRunOutcome = { status: "failed" | "needs_input" | "in_progress"; detail: string; jobId?: string };

// 도구 관찰 문장 첫 줄의 상태 낱말(영문)을 사용자에게 보이는 기록에서는 한국어로 바꾼다.
const toolUsageStatusLabels: Readonly<Record<string, string>> = {
  completed: "완료", failed: "실패", declined: "취소", cancelled: "멈춤", busy: "다른 실행이 끝나기를 기다림",
  needs_input: "확인 필요", needs_connection: "연결 필요", queued: "진행 중", connecting: "연결 중",
  generating: "진행 중", saving: "저장 중", running: "진행 중", read: "읽음", not_installed: "확장 없음",
};

function describeToolUsageSummary(summary: string) {
  const first = (summary.trim().split("\n", 1)[0] ?? "").trim();
  const [head, ...rest] = first.split(" · ");
  const label = toolUsageStatusLabels[(head ?? "").trim()];
  return compactInlineText(label ? [label, ...rest].join(" · ") : first, 48);
}

   
                                                                       
                                                                              
   
function reconcileSavedFileClaims(text: string) {
  return text.replace(/[^.!?\n]*저장[^.!?\n]*아직[^.!?\n]*(?:않았|못했)[^.!?\n]*[.!?]?/gu, (sentence) => {
    const lead = sentence.match(/^\s*/u)?.[0] ?? "";
    return lead + (/실행|동작|테스트/u.test(sentence)
      ? "파일은 프로젝트 결과 폴더에 저장했어요. 실행해서 동작을 확인하는 일은 아직 하지 않았어요."
      : "파일은 프로젝트 결과 폴더에 저장했어요.");
  });
}

   
                                                                  
                                                                 
                                                                                             
   
function summarizeProductionToolOutcome(usedTools: ReadonlyArray<{ id: string; label: string; summary: string }>): ChatRunOutcome | null {
  const attempts = usedTools.filter((tool) => productionAgentToolIds.has(tool.id));
  if (!attempts.length) return null;
  const statusOf = (summary: string) => (summary.trim().split("\n", 1)[0] ?? "").split(" · ", 1)[0]?.trim() ?? "";
  if (attempts.some((tool) => statusOf(tool.summary) === "completed")) return null;
  const connecting = attempts.find((tool) => tool.id === "studio.image.generate" && statusOf(tool.summary) === "connecting");
  const drawing = connecting ?? attempts.find((tool) => tool.id === "studio.image.generate" && creativeStudioActiveStatuses.has(statusOf(tool.summary)));
  if (drawing) {
    return {
      status: "in_progress",
      detail: connecting ? "이미지 엔진 연결을 기다리는 중입니다 · 연결되면 이어서 만듭니다" : "이미지를 그리는 중입니다 · 완성되면 아래 카드에 바로 보입니다",
      jobId: drawing.summary.match(/^작업 ID: (.+)$/mu)?.[1]?.trim() || undefined,
    };
  }
  const review = attempts.find((tool) => statusOf(tool.summary) === "needs_input");
  if (review) return { status: "needs_input", detail: "설계 확인이 필요합니다 · 계획을 확인하고 '이대로 구현'이라고 답해 주세요" };
  const connection = attempts.find((tool) => statusOf(tool.summary) === "needs_connection");
  if (connection) return { status: "needs_input", detail: "이미지 엔진 연결이 필요합니다 · 안내대로 연결하면 이어서 만듭니다" };
  const last = attempts[attempts.length - 1];
  const firstLine = last.summary.trim().split("\n", 1)[0] ?? "";
  const reason = compactInlineText(firstLine.replace(/^[a-z_]+ · /u, "").replace(/^실패:\s*/u, ""), 90);
  return { status: "failed", detail: `결과물을 만들지 못했습니다 · ${reason || last.label}` };
}

type RoleCapabilityStripItem = {
  id: string;
  label: string;
  value: string;
  state: "ready" | "blocked" | "approval";
  detail: string;
};

type RoleCommandWorkDescriptor = {
  contract: "role_assignment_to_work_automation_engine_v1";
  oneLineLabel: string;
  candidateLabel: string;
  pipelineLabel: string;
  approvalGateLabel: string;
  evidencePath: string;
  connectionGateLabel: string;
  connectionRequiredIds: string;
  candidateBlockedUntilConnections: boolean;
};

function createRoleCapabilityStrip(
  assignment: RoleWorkAutomationAssignment | null,
  aiConnected: boolean,
): RoleCapabilityStripItem[] {
  if (!assignment) return [];
  const connectionBlocked = /필요 연결 전 멈춤|연결 후/u.test(assignment.connectionGateLabel);
  return [
    {
      id: "role-ai-runtime",
      label: "AI",
      value: aiConnected ? "대화 가능" : "연결 필요",
      state: aiConnected ? "ready" : "blocked",
      detail: aiConnected ? "다음 답변 payload에 선택 역할을 넣어 호출합니다." : "AI 연결 전에는 역할 답변을 만든 척하지 않습니다.",
    },
    {
      id: "role-work-scope",
      label: "업무",
      value: roleWorkIntentLabel(assignment.workIntent),
      state: "ready",
      detail: assignment.candidateLabel,
    },
    {
      id: "role-connection-gate",
      label: "연결",
      value: connectionBlocked ? "필요" : "확인됨",
      state: connectionBlocked ? "blocked" : "ready",
      detail: assignment.connectionGateLabel,
    },
    {
      id: "role-approval-gate",
      label: "승인",
      value: "최종 전 잠금",
      state: "approval",
      detail: assignment.executionBoundary,
    },
  ];
}

function roleWorkIntentLabel(intent: RoleWorkAutomationAssignment["workIntent"]) {
  if (intent === "mail_or_inquiry") return "메일/문의";
  if (intent === "schedule") return "일정";
  if (intent === "repeat") return "반복";
  if (intent === "document_draft") return "문서";
  if (intent === "folder_tidy") return "파일";
  return "일반";
}

function workAutomationIntentFromAgentIntent(
  intent: ModyAssistantAgentIntent | undefined,
): WorkAutomationIntent | null {
  if (intent === "mail_ops") return "mail_or_inquiry";
  if (intent === "automation_check") return "repeat";
  if (intent === "document_learning") return "document_draft";
  if (intent === "folder_tidy") return "folder_tidy";
  return null;
}

function createRoleCommandWorkDescriptor(input: {
  teammate: AITeammate;
  intent: RoleWorkAutomationAssignment["workIntent"];
  plan: ReturnType<typeof createRoleCommandWorkAutomationPlan>;
  assignment?: RoleWorkAutomationAssignment | null;
}): RoleCommandWorkDescriptor {
  const label = roleWorkIntentLabel(input.intent);
  const base = {
    contract: "role_assignment_to_work_automation_engine_v1" as const,
    approvalGateLabel: WORK_AUTOMATION_APPROVAL_GATE_CONTRACT,
    oneLineLabel: `${input.teammate.name} -> ${label} 후보 -> 오피스 승인함`,
  };
  if (input.plan) {
    return {
      ...base,
      candidateLabel:
        input.intent === "schedule"
          ? "가능 시간 확인 -> 일정 후보 -> 승인함"
          : input.intent === "repeat"
            ? "반복 후보 저장 -> 사용자가 켜기 -> 점검 큐"
            : input.intent === "document_draft"
              ? "선택 자료 확인 -> 문서/보고서 초안 -> 승인함"
              : input.intent === "folder_tidy"
                ? "선택 폴더 확인 -> 정리 후보 -> 승인함"
                : "메일/문의 확인 -> 답장 초안 -> 일정 후보",
      pipelineLabel: input.plan.corePipelineLabel,
      evidencePath:
        input.intent === "document_draft"
          ? "role quick command -> document draft candidate -> WorkAutomationEngine -> ApprovalEngine"
          : input.intent === "folder_tidy"
            ? "role quick command -> folder tidy candidate -> WorkAutomationEngine -> ApprovalEngine"
            : "role quick command -> ConversationEngine -> WorkAutomationEngine -> ApprovalEngine",
      connectionGateLabel: input.plan.connectionGateLabel,
      connectionRequiredIds: input.plan.connectionRequiredIds.join("|"),
      candidateBlockedUntilConnections: input.plan.candidateCreationBlockedUntilConnections,
    };
  }
  if (input.intent === "document_draft") {
    return {
      ...base,
      candidateLabel: "선택 자료 확인 -> 문서/보고서 초안 -> 승인함",
      pipelineLabel: "자료 범위 확인 -> 초안 후보 -> 승인함 -> 실행 로그",
      evidencePath: "role quick command -> document draft candidate -> approval engine -> execution log",
      connectionGateLabel: "사용자가 선택한 자료와 양식만 읽고 저장/공유/제출은 승인 전 잠금",
      connectionRequiredIds: "",
      candidateBlockedUntilConnections: false,
    };
  }
  if (input.intent === "folder_tidy") {
    return {
      ...base,
      candidateLabel: "선택 폴더 확인 -> 정리 후보 -> 승인함",
      pipelineLabel: "선택 범위 확인 -> 정리 후보 -> 승인함 -> 실행 로그",
      evidencePath: "role quick command -> folder candidate -> dry run -> approval engine -> execution log",
      connectionGateLabel: "사용자가 선택한 폴더 범위만 읽고 이동/삭제/이름 변경은 승인 전 잠금",
      connectionRequiredIds: "",
      candidateBlockedUntilConnections: false,
    };
  }
  return {
    ...base,
    candidateLabel: input.assignment?.candidateLabel ?? "대화 의도 판단 -> 필요한 담당자/업무 후보 선택",
    pipelineLabel: input.assignment?.pipelineLabel ?? "요청 분류 -> 역할 배정 -> 후보 생성 -> 승인함",
    evidencePath: input.assignment?.evidencePath ?? "conversation engine -> role router -> work automation engine",
    connectionGateLabel: input.assignment?.connectionGateLabel ?? "필요한 연결과 자료 범위를 확인한 뒤 후보만 생성",
    connectionRequiredIds: "",
    candidateBlockedUntilConnections: false,
  };
}

function roleCommandConnectionPreviewLabel(
  plan: ReturnType<typeof createRoleCommandWorkAutomationPlan>,
  fallbackConnectionGateLabel = "",
) {
  if (!plan) return fallbackConnectionGateLabel || "자료 범위 확인";
  if (!plan.connectionRequiredIds.length) return "연결 확인됨";
  return plan.connectionRequiredIds.map((id) => (id === "mail" ? "메일" : "캘린더")).join("/");
}

