function createAIAnswerRuntimeProof(
  receipt: NonNullable<AITextGenerationResult["aiRuntimeReceipt"]> | null,
): ChatMessage["aiRuntimeProof"] | undefined {
  if (!receipt?.answerReady) return undefined;
  const runtimeContext = receipt.runtimeContext;
  const finalRoute = String(receipt.finalRoute || receipt.provider || receipt.runtime || "codex_oauth");
  const finalRouteLabel = userFacingAIRuntimeRouteLabel(finalRoute);
  const attemptedRoutes = (receipt.attemptedRoutes?.length ? receipt.attemptedRoutes : [finalRoute])
    .filter(Boolean)
    .join(">");
  const roleAssignmentContract = runtimeContext?.assignmentContract ?? "";
  const workAutomationContract = runtimeContext?.workAutomationContract ?? "";
  const teammateName = runtimeContext?.teammateName ?? "";
  const roleTitle = runtimeContext?.roleTitle ?? "";
  const workAutomationCandidateLabel = runtimeContext?.workAutomationCandidateLabel ?? "";
  const workAutomationConnectionGateLabel = runtimeContext?.workAutomationConnectionGateLabel ?? "";
  const workAutomationConnectionRequiredIds = runtimeContext?.workAutomationConnectionRequiredIds ?? "";
  const workAutomationCandidateBlockedUntilConnections =
    runtimeContext?.workAutomationCandidateBlockedUntilConnections === true;
  const workAutomationApprovalGateLabel =
    runtimeContext?.workAutomationApprovalGateLabel ?? "dry_run_receipt_connector_readiness_final_presence";
  const approvalQueueCount = runtimeContext?.approvalQueueCount ?? 0;
  const approvalCandidateHandoffReady = Boolean(
    workAutomationCandidateLabel &&
      !workAutomationCandidateBlockedUntilConnections &&
      runtimeContext?.externalMutationAllowed === false,
  );
  const approvalCandidateCount = approvalCandidateHandoffReady ? Math.max(1, approvalQueueCount) : approvalQueueCount;
  const approvalCandidateHandoffContract = approvalCandidateHandoffReady
    ? "ai_runtime_work_candidate_to_approval_queue_handoff_v1"
    : "";
  const approvalCandidateHandoffLabel = approvalCandidateHandoffReady
    ? `${workAutomationCandidateLabel} -> 오피스 승인함 -> 실행 로그`
    : "";
  const runtimeSource = runtimeContext?.source ?? "";
  const virtualOfficeWorkerStateLabel = workAutomationCandidateBlockedUntilConnections
    ? "연결 필요"
    : approvalQueueCount > 0
      ? "승인 대기"
      : workAutomationCandidateLabel
        ? "업무 후보"
        : "답변 완료";
  const virtualOfficeQueueLabel = workAutomationCandidateBlockedUntilConnections
    ? workAutomationConnectionGateLabel || "필요 연결 확인"
    : workAutomationCandidateLabel || workAutomationContract || "채팅 답변 완료";
  const virtualOfficeNextUserActionLabel = workAutomationCandidateBlockedUntilConnections
    ? "필요 연결 확인 후 이어가기"
    : workAutomationCandidateLabel || workAutomationContract
      ? "작업함 또는 승인함 확인"
      : "채팅에서 다음 요청 계속";
  const traceId = runtimeContext?.traceId || "";
  const traceContract = runtimeContext?.traceContract || AI_RUNTIME_TRACE_CONTRACT;
  return {
    contract: "ai_answer_receipt_to_visible_chat_proof",
    summary: [
      `AI 답변: ${finalRouteLabel}`,
      teammateName ? `역할: ${teammateName}` : "역할: 기본 대화",
      workAutomationCandidateLabel ? `업무 후보: ${workAutomationCandidateLabel}` : workAutomationContract ? "업무 후보: 연결됨" : "업무 후보: 일반 답변",
      "실행 잠금",
    ].join(" · "),
    finalRoute,
    finalRouteLabel,
    attemptedRoutes,
    roleContract: runtimeContext?.contract ?? "",
    roleAssignmentContract,
    teammateName,
    roleTitle,
    workAutomationContract,
    workAutomationCandidateLabel,
    workAutomationApprovalGateLabel,
    workAutomationConnectionGateLabel,
    workAutomationConnectionRequiredIds,
    workAutomationCandidateBlockedUntilConnections,
    requestedWorkSummary: runtimeContext?.requestedWorkSummary ?? "",
    plannedToolSequenceLabel: runtimeContext?.plannedToolSequenceLabel ?? "",
    approvalQueueCount,
    approvalCandidateHandoffContract,
    approvalCandidateHandoffReady,
    approvalCandidateHandoffLabel,
    approvalCandidateCount,
    approvalCandidateFinalBoundary: "approval_before_external_mutation",
    approvalCandidateExecutionLogLabel: approvalCandidateHandoffReady
      ? "실행 로그 후보 생성, 외부 실행은 최종 확인 전까지 잠금"
      : "",
    runtimeSource,
    traceId,
    traceContract: traceContract === AI_RUNTIME_TRACE_CONTRACT ? AI_RUNTIME_TRACE_CONTRACT : AI_RUNTIME_TRACE_CONTRACT,
    traceProofChain: AI_RUNTIME_TRACE_PROOF_CHAIN,
    virtualOfficeEventPath: "ai_runtime_receipt_to_selected_work_event_to_virtual_office_event_bus",
    virtualOfficeWorkerStateLabel,
    virtualOfficeStageLabel: workAutomationCandidateLabel || workAutomationContract ? "역할 적용 답변 검증" : "AI 답변 검증",
    virtualOfficeQueueLabel,
    virtualOfficeNextUserActionLabel,
    virtualOfficeSafetyBoundaryLabel: "외부 발송, 일정 등록, 파일 변경은 승인 전까지 실행하지 않습니다.",
    payloadContract: "createAITextGenerationPayload.roleContext",
    receiptContract: "aiRuntimeReceipt.runtimeContext",
    approvalContract: "dry_run_receipt_connector_readiness_final_presence",
    fakeResultPolicy: "stop_before_fake_answer_or_fake_work_card",
    externalMutation: false,
  };
}

function createCrewRoutingReceipt(
  routing: AITextGenerationResult["agentRouting"] | undefined,
): ChatMessage["agentRoutingReceipt"] | undefined {
  const targetCrewName = typeof routing?.targetTeammateName === "string"
    ? routing.targetTeammateName.trim().slice(0, 60)
    : "";
  const reason = typeof routing?.reason === "string"
    ? routing.reason.replace(/\s+/gu, " ").trim().slice(0, 220)
    : "";
  if (
    routing?.contract !== "agent_org_runtime_routing_v1" ||
    routing.status !== "routed" ||
    !targetCrewName ||
    !reason ||
    routing.externalMutation !== false
  ) return undefined;
  const evidenceCount = Number(routing.learningEvidenceCount);
  const learningEvidenceCount =
    routing.assignmentSource === "approved_folder_learning" && Number.isFinite(evidenceCount) && evidenceCount >= 0
      ? Math.floor(evidenceCount)
      : undefined;
  return {
    contract: "agent_org_runtime_routing_v1",
    sourceLabel: "메인 크루",
    targetCrewName,
    roleTitle: typeof routing.roleTitle === "string" ? routing.roleTitle.trim().slice(0, 80) : "",
    reason,
    assignmentSource: routing.assignmentSource === "approved_folder_learning" ? "approved_folder_learning" : undefined,
    learningEvidenceCount,
    externalMutation: false,
  };
}
function createFirstWorkResultHandoff(
  receipt: NonNullable<AITextGenerationResult["aiRuntimeReceipt"]> | null,
): ChatMessage["firstWorkResultHandoff"] | undefined {
  if (!receipt?.answerReady) return undefined;
  const runtimeContext = receipt.runtimeContext;
  const runtimeSource = runtimeContext?.source ?? "";
  if (!runtimeSource.startsWith("worker_role_setup_first_work")) return undefined;
  const handoff = createWorkAutomationRuntimeReceiptHandoff({ runtimeContext });
  const firstWorkRoleText = [
    runtimeContext?.teammateName,
    runtimeContext?.roleTitle,
    runtimeContext?.workAutomationCandidateLabel,
    runtimeContext?.requestedWorkSummary,
    runtimeContext?.plannedToolSequenceLabel,
  ].filter(Boolean).join(" ");
  const isMailWorkQueueHandoff = /메일|이메일|문의|답장|회신|mail|inquiry/iu.test(firstWorkRoleText);
  return {
    contract: "first_work_result_to_office_approval_handoff_v1",
    visible: "one_line_after_ai_answer",
    runtimeSource,
    teammateName: runtimeContext?.teammateName ?? "선택한 담당자",
    roleTitle: runtimeContext?.roleTitle ?? runtimeContext?.teammateName ?? "역할 지정",
    workCandidateLabel:
      runtimeContext?.workAutomationCandidateLabel ||
      handoff.requestedWorkSummary ||
      "첫 업무 후보",
    connectionGateLabel:
      runtimeContext?.workAutomationConnectionGateLabel ||
      (runtimeContext?.workAutomationCandidateBlockedUntilConnections ? "필요 연결 확인" : "연결 확인 완료"),
    approvalGateLabel: runtimeContext?.workAutomationApprovalGateLabel || handoff.approvalGateContract,
    payloadContract: "createAITextGenerationPayload.roleContext",
    receiptContract: "aiRuntimeReceipt.runtimeContext",
    handoffContract: handoff.contract,
    workContract: "role_assignment_to_work_automation_engine_v1",
    enginePath: handoff.enginePathContract,
    virtualOfficePath: handoff.virtualOfficeEventPath,
    eventPath: "ai_runtime_receipt_to_work_automation_candidate_to_office_approval",
    finalBoundary: "approval_before_external_mutation",
    fakePolicy: "no_first_work_result_without_live_ai_receipt",
    externalMutation: false,
    mailWorkQueueHandoff: isMailWorkQueueHandoff
      ? {
          contract: "first_work_mail_role_to_mailops_workqueue_handoff_v1",
          visible: "one_line_mail_rows_details_inside",
          actionLabel: "메일 직원 작업함 열기",
          route: "first_work_ai_answer_to_mailops_workqueue",
          targetHash: "#mailops-workbench-rows",
          reviewMode: "multi_mail_one_line_rows_details_inside",
          decisionScope: "reply_needed_hold_exclude_user_composed_mobile_share",
          editApprovalPolicy: "edit_drafts_then_approve_only",
          finalBoundary: "app_final_confirmation_before_external_send",
          fakePolicy: "no_mail_rows_before_connector_read",
          externalMutation: false,
        }
      : undefined,
  };
}

