function visibleWorkflowItems(items: string[] | undefined): string[] {
  if (!items?.length) return [];
  const nextChoice = items.find((item) => item.startsWith("막히면:"));
  const primaryItems = items.filter((item) => item !== nextChoice).slice(0, 4);
  return nextChoice ? [...primaryItems, nextChoice] : primaryItems;
}

function executionReceiptBlockedReason(receipt: ChatExecutionReceipt): string {
  if (receipt.blockedReason?.trim()) return receipt.blockedReason;
  if (receipt.kind === "mailops") return "메일 연결이나 계정 보관함 확인이 남아 있으면 발송과 일정 등록은 승인함에서 멈춥니다.";
  if (receipt.kind === "schedule_prep") return "캘린더 연결이나 일정 근거 확인이 남아 있으면 등록과 초대 발송은 승인함에서 멈춥니다.";
  if (receipt.kind === "document_learning") return "자료 선택이나 설치 앱 읽기 준비가 남아 있으면 원본 변경 없이 읽기 후보만 보여줍니다.";
  if (receipt.kind === "draft_report") return "보고서 자료 범위가 남아 있으면 파일 저장, 공유, 제출은 실행하지 않고 초안 후보만 남깁니다.";
  if (receipt.kind === "folder_tidy") return "폴더 범위와 실행 전 검토가 남아 있으면 실제 이동, 삭제, 이름 변경은 하지 않습니다.";
  if (receipt.kind === "automation") return "반복 업무가 아직 켜지지 않았거나 승인 기준이 남아 있으면 실행하지 않고 후보만 남깁니다.";
  if (receipt.kind === "computer_use") return "볼 창, 파일, 폴더 범위가 확인되지 않으면 클릭, 입력, 파일 변경은 승인함에서 잠급니다.";
  return "필요한 연결, 자료 선택, 승인 단계가 남아 있으면 외부 실행 없이 다음 선택지만 보여줍니다.";
}

function executionReceiptResultSummary(receipt: ChatExecutionReceipt): string {
  if (receipt.resultSummary?.trim()) return receipt.resultSummary;
  if (receipt.kind === "today_work") return "오늘 업무 후보를 정리했습니다.";
  if (receipt.kind === "mailops") return "메일 후보를 승인함에 올렸습니다.";
  if (receipt.kind === "schedule_prep") return "일정 후보와 등록 전 체크리스트를 만들었습니다.";
  if (receipt.kind === "document_learning") return "자료 읽기 후보를 준비했습니다.";
  if (receipt.kind === "draft_report") return "보고서 초안과 저장 후보를 만들었습니다.";
  if (receipt.kind === "folder_tidy") return "정리 후보와 실행 전 검토를 만들었습니다.";
  if (receipt.kind === "automation") return "반복 업무 후보와 실행 로그를 정리했습니다.";
  if (receipt.kind === "computer_use") return "PC 읽기 결과와 승인 카드를 만들었습니다.";
  return "실행 결과를 확인했습니다.";
}

function visibleExecutionReceiptBlockedReason(receipt: ChatExecutionReceipt): string {
  if (receipt.kind === "draft_report" && /반복\s*보고서|반복\s*후보/u.test(receipt.blockedReason ?? "")) return receipt.blockedReason ?? "";
  if (receipt.kind === "mailops") return "업무를 먼저 고르면 필요한 메일 연결만 확인합니다.";
  if (receipt.kind === "schedule_prep") return "캘린더 연결이 필요합니다.";
  if (receipt.kind === "document_learning") return "읽을 자료를 골라야 합니다.";
  if (receipt.kind === "draft_report") return "보고서 자료를 골라야 합니다.";
  if (receipt.kind === "folder_tidy") return "정리할 폴더를 골라야 합니다.";
  if (receipt.kind === "automation") return "반복 업무를 먼저 켜야 합니다.";
  if (receipt.kind === "computer_use") return "볼 창이나 파일을 골라야 합니다.";
  if (receipt.kind === "today_work") return "확인할 업무가 필요합니다.";
  return "필요한 준비가 남아 있습니다.";
}

function visibleExecutionReceiptNextChoice(receipt: ChatExecutionReceipt): string {
  const source = receipt.nextUserChoice.trim();
  if (receipt.kind === "draft_report" && /반복\s*후보\s*저장/u.test(source)) return "반복 후보 저장";
  if (receipt.kind === "mailops") return /메일\s*연결|계정\s*보관함/u.test(source) ? "메일 연결하기" : "승인함 보기";
  if (receipt.kind === "folder_tidy") return receipt.state === "approval" || /승인함|실행\s*전\s*검토/u.test(source) ? "오피스 보기" : "폴더 다시 선택";
  if (receipt.state === "approval" && /승인함|오피스/u.test(source)) return "승인함 보기";
  if (receipt.kind === "automation") return "반복 업무 다시 열기";
  if (receipt.kind === "computer_use") return "작업 범위 고르기";
  if (receipt.kind === "document_learning") return "자료 선택하기";
  if (/메일|계정\s*보관함/u.test(source)) return "메일 연결하기";
  if (/폴더|정리/u.test(source)) return "폴더 다시 선택";
  if (/반복\s*업무|빌더/u.test(source)) return "반복 업무 다시 열기";
  if (/내\s*PC|열린\s*창|최근\s*파일|브라우저/u.test(source)) return "작업 범위 고르기";
  if (/승인함|오피스/u.test(source)) return "승인함 보기";
  if (/자료|문서|보고서|기억\s*위치/u.test(source)) return "자료 선택하기";
  if (/캘린더|일정/u.test(source)) return "캘린더 연결하기";
  if (/연결/u.test(source)) return "연결 확인하기";
  return "다음 단계 확인";
}

function executionReceiptReviewStepDetail(receipt: ChatExecutionReceipt): string {
  if (receipt.kind === "mailops") return "수신자, 본문, 일정 시간은 발송/등록 전에 직접 확인합니다.";
  if (receipt.kind === "schedule_prep") return "시간, 참석자, 초대 문구는 등록 전에 직접 확인합니다.";
  if (receipt.kind === "document_learning") return "읽은 자료와 결과 후보만 확인하고 원본은 바꾸지 않습니다.";
  if (receipt.kind === "draft_report") return "저장, 공유, 제출 전에 자료 범위와 문서 형식을 직접 확인합니다.";
  if (receipt.kind === "folder_tidy") return "이동, 삭제, 이름 변경 전 정리 후보를 직접 확인합니다.";
  if (receipt.kind === "automation") return "반복 실행은 켜기 전에 조건, 시간, 승인 기준을 직접 확인합니다.";
  if (receipt.kind === "computer_use") return "클릭, 입력, 파일 변경 전 대상과 범위를 직접 확인합니다.";
  return "외부 실행이나 변경 전에 후보를 직접 확인합니다.";
}

function executionReceiptDecisionSteps(receipt: ChatExecutionReceipt): ChatExecutionDecisionStep[] {
  const confirmationLocation = receipt.confirmationLocation?.trim() || "오피스 승인함";
  const nextChoice = visibleExecutionReceiptNextChoice(receipt);
  return [
    {
      label: nextChoice,
      detail: `${confirmationLocation}에서 후보를 엽니다.`,
      state: "approval",
    },
    {
      label: "실행하기/고쳐달라고 하기/보류하기",
      detail: `${executionReceiptReviewStepDetail(receipt)} 마음에 드는 방식은 '다음부터 이렇게'로 저장합니다.`,
      state: "locked",
    },
    {
      label: "로그/되돌리기",
      detail: `${receipt.logLabel} · ${receipt.undoLabel}`,
      state: "ready",
    },
  ];
}

function userFacingCapabilityLabel(value: string | null | undefined): string {
  const source = (value ?? "업무 도구").trim();
  const label = source
    .replace(/\s*CrewKit\b/giu, "")
    .replace(/\bMailOps\b/giu, "메일 점검")
    .replace(/\bTidy\b/giu, "폴더 정리")
    .replace(/\bWriter\b/giu, "문서 작성")
    .replace(/\bDeck\b/giu, "발표자료")
    .replace(/\bMotion\b/giu, "영상 제작")
    .replace(/\bCodex\b/giu, "작업 도우미")
    .replace(/\bKnowledge\b/giu, "자료 학습")
    .trim();
  return label || "업무 도구";
}

function userFacingCapabilityDetail(value: string | null | undefined, fallback = "업무 도구"): string {
  const raw = String(value ?? "")
    .replace(/\bSkillBridge\b/giu, "업무 도구 추천")
    .replace(/\bSkillGrowth\b/giu, "기능 개선 기록")
    .replace(/\bSkillSourceInventory\b/giu, "새 PC 이어쓰기 목록")
    .replace(/\bCrewKitIndex\b/giu, "기능 목록")
    .replace(/\bCrewChannelIndex\b/giu, "AI 팀원 목록")
    .replace(/\bCrewChannelBlueprint\b/giu, "AI 팀원 기준")
    .replace(/\bCrewSoulBundle\b/giu, "AI 팀원 기억 묶음")
    .replace(/\bCrewSoul\b/giu, "AI 팀원 기억")
    .replace(/\bConversationDigest\b/giu, "대화 요약 기억")
    .replace(/\bPromptMemory\b/giu, "답변 기준 기억")
    .replace(/\bWorkPatternMemory\b/giu, "지난 업무 기억")
    .replace(/\bMailOpsPromptMemory\b/giu, "메일 업무 기억")
    .replace(/\bWriterPromptMemory\b/giu, "문서 업무 기억")
    .replace(/\bDelegationActionQueue\b/giu, "승인 후보 기록")
    .replace(/\bCrewKit\b/giu, "업무 도구")
    .replace(/\bMailOps\b/giu, "메일 점검")
    .replace(/\bCodex OAuth\b/giu, "AI 답변 연결")
    .replace(/\bCodex\s+CLI\b/giu, "AI 연결 복구")
    .replace(/\bCodex\b/giu, "AI 답변 연결")
    .replace(/\bOAuth\b/giu, "계정 연결")
    .replace(/\blocalhost callback\b/giu, "되돌아오기 주소")
    .replace(/\bcallback\b/giu, "되돌아오기 주소")
    .replace(/\bfallback\b/giu, "대체 경로")
    .replace(/\bskill file\b/giu, "기능 파일")
    .replace(/\bSkill\b/giu, "도구")
    .replace(/\bskill\b/giu, "도구");
  return userFacingCapabilityLabel(raw).trim() || fallback;
}

function userFacingMemoryReferenceLabel(path: string | null | undefined): string {
  const value = String(path ?? "").trim();
  if (!value) return "업무 기록";
  if (/DecisionMemory|DecisionLog|ApprovalDecisions/iu.test(value)) return "결정 기록";
  if (/DelegationActionQueue/iu.test(value)) return "승인 후보 기록";
  if (/DelegationArtifacts|delegation/iu.test(value)) return "AI 팀원 결과 기록";
  if (/WorkPatternMemory|memory\/work-patterns/iu.test(value)) return "지난 업무 기억";
  if (/PromptMemory|memory\/prompt/iu.test(value)) return "답변 기준 기억";
  if (/WorkLog/iu.test(value)) return "업무 기록";
  if (/CrewSoul|memory\/crew-souls|CrewChannel/iu.test(value)) return "AI 팀원 기억";
  if (/SkillGrowth|SkillBridge|SkillBootstrap|SkillSourceInventory|memory\/growth/iu.test(value)) return "기능 복원 기록";
  if (/final-actions|audit/iu.test(value)) return "최종 실행 감사 기록";
  return value.includes("memory/") ? "로컬 기억 기록" : value;
}

function homeApprovalDecisionReceiptWorkKindLabel(source: HomeApprovalDecisionReceipt["source"] | null | undefined): string {
  if (source === "mailops") return "메일";
  if (source === "folder_plan") return "폴더 정리";
  if (source === "repeat_work") return "반복 업무";
  if (source === "final_confirmation") return "마지막 확인";
  if (source === "browser_task") return "내 PC 작업";
  if (source === "local_file_pattern") return "다음부터 이렇게";
  if (source === "local_file") return "자료/보고서";
  return "업무";
}

function visibleConnectionRecoveryDetail(value: string | null | undefined, fallback = "연결을 다시 확인하세요."): string {
  const source = userFacingCapabilityDetail(value, fallback);
  if (/비밀번호|토큰|인증|로그인|계정|보관함|secret|credential/u.test(source)) return "로그인 정보를 다시 저장하세요.";
  if (/권한|관리자|초대|승인|permission|scope/u.test(source)) return "권한 승인이 필요합니다.";
  if (/앱 위치|사이트 링크|브라우저|설치|Windows|내 PC|화면/u.test(source)) return "앱 위치를 확인하세요.";
  if (/메일|IMAP|SMTP|Gmail|Outlook/u.test(source)) return "메일 연결을 다시 확인하세요.";
  if (/캘린더|일정/u.test(source)) return "일정 권한은 나중에 연결하세요.";
  if (/발송|등록|공유|삭제|최종 확인|잠금/u.test(source)) return "실행은 앱의 마지막 확인 전까지 멈춥니다.";
  if (/대체|복구|연결|확인/u.test(source)) return "연결을 다시 확인하세요.";
  return source.length > 48 ? fallback : source;
}

function visibleConnectionNextAction(value: string | null | undefined, fallback = "다음 단계 확인"): string {
  const source = userFacingCapabilityDetail(value, fallback);
  if (/보관함|비밀번호|토큰|인증|로그인|계정/u.test(source)) return "계정 보관함 열기";
  if (/내 PC|앱 위치|사이트 링크|브라우저|설치|화면/u.test(source)) return "읽기 후보 만들기";
  if (/권한|관리자|초대|승인/u.test(source)) return "권한 확인하기";
  if (/메일|IMAP|SMTP|Gmail|Outlook/u.test(source)) return "메일 연결하기";
  if (/캘린더|일정/u.test(source)) return "일정 후보로 보류";
  if (/오피스|승인함|큐/u.test(source)) return "승인함 보기";
  if (/연결|확인|재점검|live\s*check/u.test(source)) return "연결 다시 확인";
  return fallback;
}

function visibleConnectionFallbackRoute(value: string | null | undefined): string {
  return visibleConnectionNextAction(value, "다음 행동 고르기");
}

function visibleConnectionSafeAction(value: string | null | undefined): string {
  const source = userFacingCapabilityDetail(value, "");
  if (/비밀번호|토큰|secret|원문|API key|직접 연결 키/u.test(source)) return "비밀값은 채팅에 남기지 않음";
  if (/읽기/u.test(source)) return "읽기 전용 확인";
  if (/발송|등록|공유|삭제|실행|최종 승인|최종 확인/u.test(source)) return "최종 승인 전 실행 안 함";
  return "안전하게 보류";
}

function aiStatusLabel(status: string) {
  if (/required|missing|not_ready/u.test(status)) return "연결 필요";
  if (/refresh|credential|invalid|unreadable/u.test(status)) return "다시 로그인 필요";
  if (/failed|empty|error/u.test(status)) return "답변 생성 실패";
  if (/timeout|network/u.test(status)) return "연결 지연";
  if (/ready|ok|success/u.test(status)) return "준비됨";
  return "확인 필요";
}

function createStarterMessages(teammate?: AITeammate): ChatMessage[] {
  if (!teammate) return starterMessages;
  const isMainControl = teammate.id === defaultAITeammateId;
  return [
    {
      id: "assistant-welcome",
      role: "assistant",
      text: isMainControl
        ? `안녕하세요. ${teammate.name} 채널입니다. 복잡한 설정부터 하지 않아도 됩니다. 하고 싶은 일을 한 문장으로 말하면, 필요한 준비만 그때 하나씩 같이 열게요.`
        : `${teammate.name} 채널입니다. ${teammate.brief} 질문이면 먼저 답하고, 실행이 필요한 일은 확인한 뒤 진행하겠습니다.`,
      actions: isMainControl
        ? [
            { label: "처음 준비", action: "comfort_setup" },
            { label: "자료 선택", action: "learn_files" },
            { label: "오늘 업무", action: "open_office" },
          ]
        : [
            { label: "이 팀원에게 맡기기", action: "delegate_active_worker" },
            { label: "업무 도구 조정", action: "skill_market" },
            { label: "오피스", action: "open_office" },
          ],
    },
  ];
}

function mergeLocalMemoryStatus(
  current: LocalMemoryStatusResult | null,
  next: LocalMemoryStatusResult,
): LocalMemoryStatusResult {
  return {
    ...(current ?? {}),
    ...next,
    workPatterns: next.workPatterns ?? current?.workPatterns ?? [],
    workPatternCount:
      next.workPatternCount ??
      next.workPatterns?.length ??
      current?.workPatternCount ??
      current?.workPatterns?.length ??
      0,
    learningSources: next.learningSources ?? current?.learningSources ?? [],
    learningSourceCount:
      next.learningSourceCount ??
      next.learningSources?.length ??
      current?.learningSourceCount ??
      current?.learningSources?.length ??
      0,
    connectorRecoveryMemories: next.connectorRecoveryMemories ?? current?.connectorRecoveryMemories ?? [],
    connectorRecoveryMemoryCount:
      next.connectorRecoveryMemoryCount ??
      next.connectorRecoveryMemories?.length ??
      current?.connectorRecoveryMemoryCount ??
      current?.connectorRecoveryMemories?.length ??
      0,
    growthSuggestions: next.growthSuggestions ?? current?.growthSuggestions ?? [],
    growthSuggestionCount:
      next.growthSuggestionCount ??
      next.growthSuggestions?.length ??
      current?.growthSuggestionCount ??
      current?.growthSuggestions?.length ??
      0,
  };
}

/**
 * Claude API 키·내 PC 모델·구독 계정(Claude 등)도 '답할 수 있는 AI'다.
 * 예전 준비 판정은 ChatGPT 로그인·OpenAI·Gemini 만 셌다. 그래서 이 셋 중 하나로 연결한
 * 사용자는 홈에 늘 '연결 필요'가 떴고, 대화도 연결 안내로 빠졌다.
 * - Claude API: 키가 있고 대화 사용에 동의했을 때
 * - 내 PC 모델: 사용자가 답변 AI 로 고른 경우(isActive)
 * - 구독 계정: 답변 AI 로 고른 경우 + CLI 로그인이 확인된 경우(가용성 available)
 */
function isKeylessOrClaudeAIProviderReady(provider: AIProviderKeyStatus) {
  const id = provider.provider ?? "";
  if (id === "anthropic") return Boolean(provider.hasLocalKey) && provider.chatContentAllowed === true;
  if (id === "local") return provider.isActive === true;
  if (id.endsWith("_subscription")) return provider.isActive === true && provider.modelAvailability?.state === "available";
  return false;
}

