  const sideCalendarEvents = useMemo<SideCalendarEvent[]>(() => {
    const toKey = (iso: string) => {
      const parsed = new Date(iso);
      if (Number.isNaN(parsed.getTime())) return null;
      return `${parsed.getFullYear()}-${`${parsed.getMonth() + 1}`.padStart(2, "0")}-${`${parsed.getDate()}`.padStart(2, "0")}`;
    };
    const toTime = (iso: string) => {
      const parsed = new Date(iso);
      if (Number.isNaN(parsed.getTime())) return undefined;
      return `${`${parsed.getHours()}`.padStart(2, "0")}:${`${parsed.getMinutes()}`.padStart(2, "0")}`;
    };
    const collected: SideCalendarEvent[] = [];
    const seen = new Set<string>();
    for (const item of [...userComposedMailApprovalItems, ...memorySearchApprovalItems, ...memorySearchMailEvidenceItems]) {
      if (!item || seen.has(item.id)) continue;
      seen.add(item.id);
      const stamp = item.dueAt || item.deadlineAt || item.receivedAt;
      if (!stamp) continue;
      const date = toKey(stamp);
      if (!date) continue;
      collected.push({
        id: item.id,
        date,
        title: item.title || item.summary || "업무",
        time: toTime(stamp),
        kind: /mail|gmail|outlook|imap|email/u.test(item.source) ? "mail" : item.dueAt || item.deadlineAt ? "meeting" : "work",
        detail: item.summary,
      });
    }
    return collected;
  }, [userComposedMailApprovalItems, memorySearchApprovalItems, memorySearchMailEvidenceItems]);

