    // [data-minimal-home="true"] > :not(...) { display:none !important })이 계속 덮는다.
    chatStageIsEmpty && showChatIntroChrome && activeChatSurface !== "agent" && !crewContextActive;
  // 첫 화면은 좌우 패널을 접어 대화 하나에 집중시킨다. 다만 '접었으면 다시 펼 수
  // 있어야' 하므로, 사용자가 헤더 토글을 누르면 이 억제를 해제한다.
  // (이전에는 sidebarOpen 상태는 true 인데 레이아웃만 강제로 0px 이라, 열기
  //  버튼의 렌더 조건 !sidebarOpen 이 영원히 거짓이었다 — 되돌릴 방법이 없었다.)
  const minimalHomeSuppressesChrome = showMinimalHomeCanvas && !homeChromeForced;
  /* 오른쪽 패널(오피스·메일·연결·자료)을 열면 가운데가 입력칸만 남은 빈 화면이 됐다.
     대화가 비어 있고 패널이 옆에 떠 있을 때(전체 화면 보기가 아닐 때)는 사무실 장면 없이
     빠른 시작 칩과 '업무 이어가기'만 있는 작은 홈을 보여준다. chatStageIsEmpty·
     data-minimal-home(담요 CSS)은 건드리지 않는다 — 켜면 옆 패널까지 숨겨진다. */
  const showHomeBesidePanel =
    !showMinimalHomeCanvas &&
    isEmptyChat &&
    !chatConversationStarted &&
    workspacePanel !== "none" &&
    !workspaceWindowOpen &&
    activeChatSurface !== "agent" &&
    !crewContextActive;
                                                
                                                                        
                                                   
                                                   

                                                        
                                                
               
  /* 홈 채팅 옆 모델 줄이 쓰는 것들.
     오너가 "모델 설정하는게 없네" 라고 한 이유는 설정이 /account 안쪽에 있어서였다.
     지금 누가 답하는지는 대화할 때마다 알고 싶은 것이라 대화하는 자리로 가져온다. */
  const localAIModels = homeLocalAIModels;
  const homeModelChoices = useMemo<ModelChoice[]>(() => {
    const byProvider = (id: string) => aiProviderStatuses.find((item) => item.provider === id);
    const anthropicRecord = byProvider("anthropic");
    const geminiRecord = byProvider("gemini");
    const codexRecord = byProvider("codex_oauth");
    const openaiRecord = byProvider("openai");
    return buildModelChoices({
      // 회색인데 이유가 없으면 "왜 못 고르지?" 에서 멈춘다 — 무엇이 필요한지 적는다.
      codex: { ready: homeAIAccountConnected, needs: "ChatGPT 로그인", modelAvailability: codexRecord?.modelAvailability },
      openai: { ready: Boolean(openaiRecord?.hasLocalKey && openaiRecord.chatContentAllowed), needs: openaiRecord?.hasLocalKey ? "AI에 대화 보내기 허용" : "OpenAI API 키 연결", modelAvailability: openaiRecord?.modelAvailability },
      anthropic: anthropicRecord?.hasLocalKey
        ? { ready: anthropicRecord.chatContentAllowed === true, needs: "AI에 대화 보내기 허용", modelAvailability: anthropicRecord.modelAvailability }
        : { ready: false, needs: "Claude API 키 넣기" },
      gemini: geminiRecord?.hasLocalKey ? { ready: geminiRecord.chatContentAllowed === true, needs: "AI에 대화 보내기 허용", modelAvailability: geminiRecord.modelAvailability } : { ready: false, needs: "Gemini API 키 넣기" },
      localModels: localAIModels,
      subscriptions: subscriptionAIRuntimes.map((runtime) => ({
        providerId: runtime.providerId,
        label: runtime.label,
        installed: runtime.installed,
        loggedIn: runtime.loggedIn,
        models: runtime.models?.map((model) => ({ id: model.id, label: model.label, hint: model.hint ?? "" })),
        modelAvailability: runtime.modelAvailability,
      })),
    });
  }, [aiProviderStatuses, homeAIAccountConnected, localAIModels, subscriptionAIRuntimes]);

  // 계정/키가 바뀌면 이전 계정의 목록을 이어 쓰지 않는다. 모델 선택이나 조회 시각은 제외한다.
  const homeModelAccountsSignature = JSON.stringify(aiProviderStatuses.map((item) => [
    item.provider, item.hasLocalKey, item.keyFingerprint, item.accountId, item.email,
  ]));
  useEffect(() => {
    if (!bridge?.isAvailable) return;
    void refreshHomeModelCatalogs(false);
    return () => { homeModelRefreshGeneration.current += 1; };
  }, [bridge, homeModelAccountsSignature]);

  const showChatDestinationBar =
    !workerCompanionMode &&
    !showMinimalHomeCanvas &&
    workspacePanel === "none";
  const sidebarVisible = sidebarOpen;
  const statusVisible = statusOpen && !minimalHomeSuppressesChrome;
  // 진행 패널 안쪽은 처음 보일 때 만들고, 그 뒤로는 계속 둔다(아래 statusPanel 참고).
  const statusPanelBodyMountedRef = useRef(false);
  if (statusVisible && !workerCompanionMode) statusPanelBodyMountedRef.current = true;
  const statusPanelBodyMounted = statusPanelBodyMountedRef.current;
  // 첫 화면의 좌우 패널 억제를 푼다. 억제 상태에서 처음 풀 때는 '누른 쪽'만
  // 열리게 반대쪽을 접어둔다 — 진행 패널을 눌렀는데 사이드바까지 따라 열리면
  // 사용자가 요청하지 않은 것이 나타난다.
  const revealHomeChrome = (side: "sidebar" | "status") => {
    if (minimalHomeSuppressesChrome) {
      if (side === "sidebar") setStatusOpen(false);
      else setSidebarOpen(false);
    }
    setHomeChromeForced(true);
  };
  const showFirstChatSidebarGuide = chatStageIsEmpty && !showEmptyChatDashboard && !firstChatSidebarGuideSeen;
  const homeAIRuntimeAbsent = useMemo(() => {
    if (!desktopReady || !bridge?.isAvailable || aiConnected) return false;
    if (readWorkbenchMockRuntimeFromLocation()) return false;
    const codexStatus = aiProviderStatuses.find((provider) => provider.provider === "codex_oauth");
    if (codexStatus?.status !== "codex_oauth_not_connected") return false;
    const hasApiFallback = aiProviderStatuses.some(
      (provider) => (provider.provider === "openai" || provider.provider === "gemini") && provider.hasLocalKey,
    );
    if (hasApiFallback) return false;
    if (!homeToolchainStatus || homeToolchainStatus.status === "desktop_required") return false;
    return Boolean(homeToolchainStatus.tools?.some((tool) => tool.id === "codex" && tool.status === "missing"));
  }, [desktopReady, bridge, aiConnected, aiProviderStatuses, homeToolchainStatus]);
  useEffect(() => {
    if (!bridge?.isAvailable) return;
    if (readWorkbenchMockRuntimeFromLocation()) return;
    let cancelled = false;
    void bridge
      .getToolchainStatus()
      .then((result) => {
        if (!cancelled) setHomeToolchainStatus(result);
      })
      .catch(() => {
        if (!cancelled) setHomeToolchainStatus(null);
      });
    return () => {
      cancelled = true;
    };
  }, [bridge]);
  useEffect(() => {
    try {
      setFirstChatSidebarGuideSeen(window.localStorage.getItem(firstChatSidebarGuideSeenKey) === "true");
    } catch {
      // localStorage 가 막힌 환경에서는 현재 세션에서만 첫 안내를 관리합니다.
    }
  }, []);
  useEffect(() => {
    if (!hasRealUserMessageInCurrentChat || firstChatSidebarGuideSeen) return;
    setFirstChatSidebarGuideSeen(true);
    try {
      window.localStorage.setItem(firstChatSidebarGuideSeenKey, "true");
    } catch {
      // localStorage 가 막힌 환경에서는 상태만 갱신합니다.
    }
  }, [firstChatSidebarGuideSeen, hasRealUserMessageInCurrentChat]);
  const latestUserMessageText = (() => {
    for (let index = messages.length - 1; index >= 0; index -= 1) {
      const message = messages[index];
      if (message.role === "user") return message.text;
    }
    return "";
  })();
  const latestUserAskedForFeatureHelp = shouldShowFeatureCatalogForText(latestUserMessageText);
                                             
                                                   
                                                        
                                     
  const visibleMessages = isEmptyChat && activeChatSurface !== "agent"
    ? []
    : messages.filter((message) => message.id !== "assistant-welcome" || !hasRealUserMessageInCurrentChat);
  // 긴 대화는 최근 메시지만 그린다. 수백 개를 매번 다 그리면 보내기·대화 열기가 1초 가까이 멈췄다.
  // 더 보고 싶으면 목록 맨 위 버튼으로 이전 메시지를 이어 붙인다. 대화를 바꾸면 다시 최근부터.
  const [messageWindow, setMessageWindow] = useState({ threadId: "", size: CHAT_MESSAGE_WINDOW_SIZE });
  const messageWindowSize = messageWindow.threadId === activeThreadId ? messageWindow.size : CHAT_MESSAGE_WINDOW_SIZE;
  const hiddenEarlierMessageCount = Math.max(0, visibleMessages.length - messageWindowSize);
  const windowedVisibleMessages = hiddenEarlierMessageCount > 0 ? visibleMessages.slice(hiddenEarlierMessageCount) : visibleMessages;
                                                                             
  // 넘긴 표식이 창 밖(이전 메시지)에 있어도 맞게 보이도록 대화 전체로 정한다.
  const messageSpeakers = resolveChatMessageSpeakers(visibleMessages, activeTeammate, teammates);
  const workingSpeaker = resolveCurrentChatSpeaker(visibleMessages, activeTeammate, teammates);
                                                            
  const conversationChangeResults = useMemo(() => visibleMessages.flatMap((message) => {
    const files = sanitizeGeneratedFiles(message.generatedFiles);
    const receipt = sanitizeDeliverableReceipt(message.deliverableReceipt);
    return files && receipt?.status === "saved"
      ? [{ scope: { workspaceRoot: localMemory?.root || localMemory?.defaultRoot || "", threadId: activeThreadId, messageId: message.id }, files, receipt }]
      : [];
  }), [visibleMessages, localMemory?.root, localMemory?.defaultRoot, activeThreadId]);
  const conversationProjectName = useMemo(() => {
    const session = workSessions.state.sessions.find((item) => item.threadId === activeThreadId);
    return workSessions.state.projects.find((project) => project.id === session?.projectId)?.name ?? "";
  }, [workSessions.state.sessions, workSessions.state.projects, activeThreadId]);
  const revealChatMessageInWindow = (messageId: string) => {
    const index = visibleMessages.findIndex((message) => message.id === messageId);
    if (index >= 0 && index < hiddenEarlierMessageCount) setMessageWindow({ threadId: activeThreadId, size: visibleMessages.length - index });
  };
  // 이전 메시지를 위에 붙여도 지금 보던 메시지가 화면의 같은 자리에 머물게 한다.
  const showEarlierChatMessages = () => {
    const list = messageListRef.current;
    const anchor = list?.querySelector<HTMLElement>("li[data-message-id]");
    const anchorId = anchor?.getAttribute("data-message-id");
    // 맨 위(scrollTop 0)에서는 브라우저의 스크롤 고정이 꺼져 있어 1px 내려 두고 맡긴다.
    if (list && list.scrollTop < 1) list.scrollTop = 1;
    const anchorTop = anchor?.getBoundingClientRect().top ?? 0;
    setMessageWindow({ threadId: activeThreadId, size: messageWindowSize + CHAT_MESSAGE_WINDOW_SIZE });
    if (!list || !anchorId) return;
    requestAnimationFrame(() => {
      const moved = list.querySelector<HTMLElement>(`[data-message-id="${CSS.escape(anchorId)}"]`);
      if (moved) list.scrollTop += moved.getBoundingClientRect().top - anchorTop;
    });
  };
  const latestAIConnectionMessageId = [...visibleMessages].reverse().find(isAIConnectionFirstMessage)?.id;
  const runningTeammateEntries = teammates
    .map((teammate) => ({ teammate, run: workerRuns[teammate.id] }))
    .filter((entry) => Boolean(entry.run));
  const virtualOfficeSnapshot = useMemo(
    () =>
      createVirtualOfficeEventBusSnapshot({
        teammates,
        workerRuns,
        teammateLastDone,
        selectedWorkActionEvents: virtualOfficeEventHistory,
        aiConnected,
        desktopReady,
      }),
    [aiConnected, desktopReady, teammateLastDone, teammates, virtualOfficeEventHistory, workerRuns],
  );
  const virtualOfficeWorkers = virtualOfficeSnapshot.workers;
  const conversationWorker = virtualOfficeWorkers.find(worker => worker.teammateId === activeTeammateId);
  const latestConversationResult = [...visibleMessages].reverse().find(message => message.role === "assistant" && message.id !== "assistant-welcome" && !isAIConnectionFirstMessage(message) && Boolean(message.aiRuntimeProof || message.executionReceipt || message.workflow?.kind === "delegation_result"));
  const selectedModelProvider = aiProviderStatuses.find(provider => provider.isActive) ?? aiProviderStatuses.find(isAIProviderAnswerCapable) ?? aiProviderStatuses.find(provider => provider.modelPreference || provider.model);
  const selectedModelId = selectedModelProvider?.modelPreference || selectedModelProvider?.model || lastHomeAIRuntimeReceipt?.model || "";

  const generatedOfficeTeammates = teammates.filter((teammate) => teammate.id !== defaultAITeammateId);
  const generatedOfficeTeammateIds = new Set(generatedOfficeTeammates.map((teammate) => teammate.id));
  const generatedVirtualOfficeWorkers = virtualOfficeWorkers.filter(
    (worker) =>
      generatedOfficeTeammateIds.has(worker.teammateId) ||
      worker.eventEvidenceKind !== "idle_no_event" ||
      worker.status !== "idle",
  );
  const workerActivityRows = [
    ...generatedVirtualOfficeWorkers.filter((worker) => worker.status === "approval_pending"),
    ...generatedVirtualOfficeWorkers.filter((worker) => worker.status !== "approval_pending" && worker.status !== "idle"),
    ...generatedVirtualOfficeWorkers.filter((worker) => worker.status === "idle"),
  ];
  const visibleVirtualOfficeWorkers = workerActivityRows.slice(0, 1);
  const hiddenVirtualOfficeWorkers = workerActivityRows.slice(1);
  const mobileMailShareInlineWorker = workerActivityRows.find((worker) => worker.mobileMailShareSummary);
  const generatedOfficeActiveCount = generatedVirtualOfficeWorkers.filter((worker) => worker.activeMotionAllowed).length;
  const generatedOfficeApprovalCount = generatedVirtualOfficeWorkers.filter((worker) => worker.status === "approval_pending").length;
  const workerActivityHeadline = generatedOfficeActiveCount
    ? `${generatedOfficeActiveCount}명 작업 중`
    : generatedOfficeApprovalCount
      ? `${generatedOfficeApprovalCount}건 승인 대기`
      : `${generatedOfficeTeammates.length}명 대기`;
  const workerActivityTeammateTemplateById = new Map(teammates.map((teammate) => [teammate.id, teammate.templateId] as const));
  const workerCompanionActivityRows = workerActivityRows;
  const workerCompanionCustomCount = generatedOfficeTeammates.filter((teammate) => teammate.templateId === "custom").length;
  const workerCompanionBaseCount = Math.max(generatedOfficeTeammates.length - workerCompanionCustomCount, 0);
  const workerCompanionDisplayedCustomCount =
    workerCompanionPreferences.avatarMode === "custom" ? generatedOfficeTeammates.length : workerCompanionCustomCount;
  const workerCompanionDisplayedBaseCount = Math.max(generatedOfficeTeammates.length - workerCompanionDisplayedCustomCount, 0);
  const workerCompanionAvatarStyleFor = (worker: VirtualOfficeWorkerEvent) =>
    workerCompanionPreferences.avatarMode === "custom" || workerActivityTeammateTemplateById.get(worker.teammateId) === "custom"
      ? "custom_worker"
      : "base_worker";
  const workerCompanionAvatarStyleLabelFor = (worker: VirtualOfficeWorkerEvent) =>
    workerCompanionAvatarStyleFor(worker) === "custom_worker" ? "꾸미는 직원" : "기본 직원";
  const workerActivityWorkKindFor = (worker: VirtualOfficeWorkerEvent) => {
    const workerText = `${worker.workerName} ${worker.channelName} ${worker.teamLabel} ${worker.workLabel} ${worker.detail}`;
    if (/메일|문의|답장|mail|inbox/u.test(workerText)) return "mail";
    if (/문서|자료|파일|보고서|document|file/u.test(workerText)) return "document";
    return worker.workKind;
  };
  const workerActivityWorkflowRows = workerActivityRows
    .filter((worker) => {
      const kind = workerActivityWorkKindFor(worker);
      return kind === "mail" || kind === "document";
    })
    .slice(0, 2);
  const workerActivityWorkflowCards = workerActivityWorkflowRows.length
    ? workerActivityWorkflowRows.map((worker) => {
        const workKind = workerActivityWorkKindFor(worker);
        return {
          id: worker.id,
          workKind,
          state: worker.status,
          source: worker.source,
          primaryAction: worker.primaryAction,
          queueLabel: worker.queueLabel,
          pipelineLabel:
            workKind === "mail"
              ? "메일 읽기 -> 답장 초안 -> 승인함 -> 실행 잠금"
              : "자료 선택 -> 읽기/초안 후보 -> 승인 후보/승인함 -> 저장/공유 잠금",
          nextActionLabel: worker.nextUserActionLabel,
        };
      })
    : [
        {
          id: "mail-default-workflow",
          workKind: "mail",
          state: "idle",
          source: "default",
          primaryAction: "none",
          queueLabel: "업무 대기",
          pipelineLabel: "메일 읽기 -> 답장 초안 -> 승인함 -> 실행 잠금",
          nextActionLabel: "메일 업무 시작",
        },
        {
          id: "document-default-workflow",
          workKind: "document",
          state: "idle",
          source: "default",
          primaryAction: "none",
          queueLabel: "자료 대기",
          pipelineLabel: "자료 선택 -> 읽기/초안 후보 -> 승인 후보/승인함 -> 저장/공유 잠금",
          nextActionLabel: "문서 자료 선택",
        },
      ];
  const workerCompanionMailWorker =
    workerCompanionActivityRows.find((worker) => workerActivityWorkKindFor(worker) === "mail") ??
    workerActivityWorkflowRows.find((worker) => workerActivityWorkKindFor(worker) === "mail");
  const workerCompanionDocumentWorker =
    workerCompanionActivityRows.find((worker) => workerActivityWorkKindFor(worker) === "document") ??
    workerActivityWorkflowRows.find((worker) => workerActivityWorkKindFor(worker) === "document");
  const workerCompanionApprovalWorker =
    workerCompanionActivityRows.find((worker) => worker.status === "approval_pending") ??
    workerCompanionActivityRows.find((worker) => worker.primaryAction === "open_office");
  const workerCompanionApprovalValue =
    workerCompanionApprovalWorker?.queueLabel && /승인\s*\d+건/u.test(workerCompanionApprovalWorker.queueLabel)
      ? workerCompanionApprovalWorker.queueLabel
      : virtualOfficeSnapshot.approvalCount
        ? `승인 ${virtualOfficeSnapshot.approvalCount}건`
        : "대기 없음";
  const workerCompanionApprovalReady = Boolean(
    virtualOfficeSnapshot.approvalCount || workerCompanionApprovalWorker?.status === "approval_pending",
  );
  const workerCompanionWorkMonitorCards = [
    {
      id: "mail",
      label: "메일",
      value: workerCompanionMailWorker?.queueLabel ?? "업무 대기",
      detail: workerCompanionMailWorker?.workPipelineLabel ?? "메일 확인 -> 답장/일정 후보 -> 승인함",
      workerName: workerCompanionMailWorker?.workerName ?? "메일 직원",
      state: workerCompanionMailWorker?.status ?? "idle",
      stageLabel: workerCompanionMailWorker?.stageLabel ?? "메일 업무 대기",
      nextActionLabel: workerCompanionMailWorker?.nextUserActionLabel ?? "메일 업무 시작",
      safetyLabel: workerCompanionMailWorker?.safetyBoundaryLabel ?? "발송 전 승인함 잠금",
      action: "mailops_start",
      handoff: "mail_to_worker_status",
      handoffLabel: "업무 시작",
    },
    {
      id: "document",
      label: "문서",
      value: workerCompanionDocumentWorker?.queueLabel ?? "자료 대기",
      detail: workerCompanionDocumentWorker?.workPipelineLabel ?? "자료 선택 -> 초안/근거 -> 승인 후보",
      workerName: workerCompanionDocumentWorker?.workerName ?? "문서 직원",
      state: workerCompanionDocumentWorker?.status ?? "idle",
      stageLabel: workerCompanionDocumentWorker?.stageLabel ?? "문서 자료 대기",
      nextActionLabel: workerCompanionDocumentWorker?.nextUserActionLabel ?? "문서 자료 선택",
      safetyLabel: workerCompanionDocumentWorker?.safetyBoundaryLabel ?? "저장 전 승인함 잠금",
      action: "document_learning_setup",
      handoff: "document_to_worker_status",
      handoffLabel: "자료 선택",
    },
    {
      id: "approval",
      label: "승인",
      value: workerCompanionApprovalValue,
      detail: workerCompanionApprovalWorker?.safetyBoundaryLabel ?? "발송, 등록, 저장은 마지막 확인 전까지 멈춤",
      workerName: workerCompanionApprovalWorker?.workerName ?? "오피스 승인함",
      state: virtualOfficeSnapshot.approvalCount ? "approval_pending" : workerCompanionApprovalWorker?.status ?? "idle",
      stageLabel: workerCompanionApprovalWorker?.stageLabel ?? "승인 대기 확인",
      nextActionLabel: workerCompanionApprovalReady ? "승인함에서 마지막 확인" : "승인 후보 대기",
      safetyLabel: workerCompanionApprovalWorker?.safetyBoundaryLabel ?? "발송, 등록, 저장은 마지막 확인 전까지 멈춤",
      action: "open_office",
      handoff: "worker_result_to_office_approval_final_confirmation",
      handoffLabel: "마지막 확인",
    },
  ];
  const virtualOfficeSceneWorkers: VirtualOfficeSceneWorker[] = generatedVirtualOfficeWorkers.map((worker, index) => {
    const teammate = generatedOfficeTeammates.find((candidate) => candidate.id === worker.teammateId);
    const identityText = `${teammate?.templateId ?? ""} ${worker.workerName} ${worker.teamLabel} ${worker.workLabel} ${teammate?.roleTitle ?? ""}`;
    const fallbackRoles: VirtualOfficeSceneWorker["role"][] = ["mail", "doc", "file", "approval"];
    const role: VirtualOfficeSceneWorker["role"] = /메일|문의|답장|mail|inbox/u.test(identityText)
      ? "mail"
      : /문서|보고서|마케팅|개발|document|report|marketing|development/u.test(identityText)
        ? "doc"
        : /승인|재무|법무|계약|finance|legal|approval/u.test(identityText)
          ? "approval"
          : /파일|바탕화면|자료|정리|desktop|file|memory/u.test(identityText)
            ? "file"
            : fallbackRoles[index % fallbackRoles.length];
    const workEvent = worker.source === "work_event" && worker.eventId
      ? virtualOfficeEventHistory.find((event) => event.id === worker.eventId)
      : undefined;
    const workMotion = officeWorkMotionForEvent(workEvent, worker.teammateId, Date.now());
    const status: VirtualOfficeSceneWorker["status"] = worker.status === "completed"
      ? "done"
      : worker.status === "approval_pending" || worker.status === "connection_required" || worker.status === "failed"
      ? "waiting"
      : workMotion
        ? "working"
        : workEvent?.status === "running" ? "waiting" : "idle";

    return {
      id: `office-scene-${worker.teammateId}`,
      name: worker.workerName,
      role,
      roleLabel: teammate?.roleTitle || worker.workLabel,
      avatarId: teammate?.avatarId,
      status,
      workMotion,
      workMotionUntil: officeWorkMotionExpiry(workEvent),
      statusLines: [worker.stageLabel, worker.queueLabel, worker.detail, worker.safetyBoundaryLabel].filter(Boolean),
      queueCount: worker.status === "approval_pending" ? 1 : undefined,
      figure: Array.from(worker.workerName.trim())[0],
    };
  });
