  async function runTidyCrewKitFromComputerUseFolder(preview: ComputerUseApprovalPreview) {
    const folderPath = preview.localFile?.scopeKind === "folder" ? preview.localFile.path : "";
    if (!folderPath) {
      commitActionMessage("tidy-from-computer-use-folder-missing", {
        text: "정리 후보를 만들 폴더 위치가 없습니다. 먼저 내 PC 작업 도우미에서 파일/폴더 범위를 다시 골라 주세요.",
        actions: [{ label: "파일/폴더 작업 카드", action: "computer_file_task" }],
      });
      return;
    }
    await runTidyCrewKit(
      "chat",
      activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations"),
      activeThreadIdRef.current || activeThreadId,
      {
        selectedFolderPaths: [folderPath],
        sourceLabel: "내 PC 작업 도우미에서 고른 폴더",
      },
    );
  }

  async function runDocumentReportCandidate(
    threadId = activeThreadIdRef.current || activeThreadId,
    options: { repeatReportContext?: boolean } = {},
  ) {
    const candidate = documentReportCandidate;
    const repeatReportContext = options.repeatReportContext ?? isReportRepeatWorkCandidate(repeatWorkBuilder);
    const teammate = activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations");
    const sourceEvidence = getDocumentReportSourceEvidence(candidate, localMemory, memorySearchDocumentResults);
    const baseExecutionReceipt = {
      ...buildDraftReportExecutionReceipt(candidate),
      ...(repeatReportContext
        ? {
            nextUserChoice: "반복 후보 저장",
            blockedReason: "반복 보고서 후보를 먼저 저장하면 기본 꺼짐으로 남고, 보고서 초안은 저장·공유·제출 전 승인함에서 멈춥니다.",
          }
        : {}),
    };
    const draftPreviewText = [
      `${candidate.output} 후보`,
      `자료 범위: ${candidate.sourceScope}`,
      `문서 형식: ${candidate.format}`,
      `승인 기준: ${candidate.approval}`,
      `자료 근거: ${sourceEvidence.label}`,
      "자료를 선택하면 학습 결과를 기준으로 Word 문서, Excel 확인표, Markdown 초안, 적용 기록 후보까지 만들 수 있습니다.",
    ].join("\n");
    const activeBridge = bridge ?? createDesktopBridge();
    const queueItem = createDocumentReportDraftQueueItem({
      candidate,
      teammate,
      threadId,
      outputText: draftPreviewText,
    });
    let stagedWorkItem: WorkItem | undefined;
    let stageMessage = sourceEvidence.ready
      ? "설치 앱에서 같은 흐름을 실행하면 보고서 초안 저장 후보를 오피스 승인함에 올립니다."
      : "자료 선택 전에는 보고서 저장 후보를 승인함에 올리지 않습니다. 먼저 자료를 선택하거나 문서 학습을 실행해 주세요.";
    setWorkspacePanel("none");
    setWorkspacePanelCollapsed(false);
    setOperationDetail(`보고서 후보 실행: ${formatDocumentReportCandidateGoal(candidate)}`);
    setLastRun({
      kind: "feature",
      result: { status: "queued", label: "보고서 만들기" },
      boundary: {
        label: "보고서 만들기",
        detail: "자료를 먼저 붙이고 초안 후보와 확인 체크리스트까지만 만들며, 저장, 외부 공유, 제출은 승인 전 잠급니다.",
        tone: "chat",
      },
      routeLabel: "자료 선택 -> 문서 학습 -> 초안 후보 -> 오피스 승인함",
      runtimeProofLabel: "learn_files -> learned output artifacts -> report_draft_file approval work item",
      safetyGate: candidate.approval,
      nextUserChoice: "자료 선택 또는 AI 팀원에게 맡기기",
    });

    if (activeBridge.isAvailable && sourceEvidence.ready) {
      try {
        const result = await activeBridge.stageDelegationActionQueueItem(queueItem);
        if (result.root || result.defaultRoot) setLocalMemory(result);
        stagedWorkItem = result.stagedWorkItem;
        if (stagedWorkItem) rememberOfficeFinalActionFocus(stagedWorkItem.id);
        stageMessage =
          result.userMessage ??
          "보고서 초안 저장 후보를 오피스 승인함에 올렸습니다. 실제 저장, 공유, 제출은 최종 확인 전까지 잠겨 있습니다.";
        await refreshWorkspace(activeBridge);
      } catch (error) {
        stageMessage = error instanceof Error
          ? `보고서 승인 카드 생성이 막혔습니다. ${error.message}`
          : "보고서 승인 카드 생성이 막혔습니다. 오피스 승인함에서 다시 확인해 주세요.";
      }
    }
    const executionReceipt = {
      ...baseExecutionReceipt,
      ...(sourceEvidence.ready
        ? {
            state: stagedWorkItem ? "approval" as const : "ready" as const,
            nextUserChoice: stagedWorkItem ? "오피스 승인함에서 저장/공유 전 확인" : "오피스 승인함에서 저장 후보 확인",
            blockedReason: "",
          }
        : {}),
      ...(repeatReportContext
        ? {
            nextUserChoice: "반복 후보 저장",
            blockedReason: "반복 보고서 후보를 먼저 저장하면 기본 꺼짐으로 남고, 보고서 초안은 저장·공유·제출 전 승인함에서 멈춥니다.",
          }
        : {}),
    };

    commitMessagesToThread(threadId, (current) => [
      ...current,
      {
        id: `assistant-document-report-run-${Date.now()}`,
        role: "assistant",
        text: [
          "보고서 초안 준비를 시작합니다.",
          `자료 범위: ${candidate.sourceScope}`,
          `만들 결과: ${candidate.output}`,
          `문서 형식: ${candidate.format}`,
          `승인 기준: ${candidate.approval}`,
          `자료 근거: ${sourceEvidence.label}`,
          "미리보기: 제목, 목차, 핵심 요약, 확인 체크리스트 먼저 표시",
          "저장 후보: Word 문서, Excel 확인표, Markdown 초안, 적용 기록 후보",
          "승인: DOCX/XLSX/Markdown 저장, 외부 공유, 제출 전 확인",
          "먼저 자료를 선택하고, 읽은 내용은 원본 변경 없이 요약과 초안 후보로만 사용합니다.",
          sourceEvidence.ready ? `승인 후보: ${queueItem.artifactTitle}` : "승인 후보: 자료 선택 후 생성",
          stageMessage,
          "DOCX/XLSX/Markdown 저장, 외부 공유, 제출은 오피스 승인 전까지 실행하지 않습니다.",
        ].join("\n"),
        workflow: {
          kind: stagedWorkItem ? "approval_queue" : "office_decision",
          label: "보고서 초안 준비",
          status: stagedWorkItem ? "approval" : "ready",
          detail: stagedWorkItem
            ? "보고서 초안 저장 후보를 오피스 승인함에 올렸고, 마지막 확인 전까지 파일 저장과 공유를 잠급니다."
            : "사용자가 고른 자료만 읽고 초안 후보를 만든 뒤 저장/공유 전 승인함으로 넘깁니다.",
          items: [
            `자료: ${candidate.sourceScope}`,
            `자료 근거: ${sourceEvidence.label}`,
            `결과: ${candidate.output}`,
            `형식: ${candidate.format}`,
            sourceEvidence.ready ? `승인 후보: ${queueItem.artifactTitle}` : "승인 후보: 자료 선택 후 생성",
            stagedWorkItem?.title
              ? `오피스 카드: ${stagedWorkItem.title}`
              : sourceEvidence.ready
                ? "설치 앱에서 오피스 승인 카드 생성"
                : "자료 선택 후 오피스 승인 카드 생성",
            "원본 변경 없음",
            "DOCX/XLSX/Markdown 저장/공유/제출 승인 전 잠금",
          ],
        },
        executionReceipt,
        actions: [
          ...(repeatReportContext ? [{ label: "반복 후보 저장" as const, action: "repeat_work_save_draft" as const }] : []),
          { label: "자료 선택하기", action: "learn_files" },
          { label: "AI 팀원에게 맡기기", action: "workers" },
          { label: "오피스 보기", action: "open_office" },
        ],
      },
    ]);

  }

