  function saveRepeatWorkBuilderDraft() {
    if (typeof window === "undefined") return;
    const trimmedWhat = repeatWorkBuilder.what.trim();
    if (!trimmedWhat) {
      commitActionMessage("repeat-work-empty", {
        text: "반복 업무로 만들 내용을 한 줄만 적어 주세요. 예: 매일 아침 메일과 오늘 일정을 확인",
      });
      return;
    }

    const connectorPlan = inferRepeatWorkConnectorPlan(repeatWorkBuilder);
    const repeatWorkPath = "저장 후보 -> 기본 꺼짐 -> 사용자가 켠 뒤 점검 -> 오피스 승인함";
    if (editingRepeatAutomationRuleId) {
      const existingRule = readLocalAutomationRules().find((rule) => rule.id === editingRepeatAutomationRuleId);
      if (existingRule) {
        const updatedRules = updateLocalAutomationRule(existingRule.id, {
          title: `반복 업무: ${trimmedWhat}`,
          goal: `${repeatWorkBuilder.when}에 ${trimmedWhat} 후 ${repeatWorkBuilder.where}에 보여줍니다.`,
          trigger: repeatWorkBuilder.when,
          output: repeatWorkBuilder.where,
          approval: repeatWorkBuilder.approval,
          connectorIds: connectorPlan.connectorIds,
          connectorLabels: connectorPlan.connectorLabels,
        });
        const updatedRule = updatedRules.find((rule) => rule.id === existingRule.id) ?? existingRule;
        setLastRepeatAutomationRule(updatedRule);
        setEditingRepeatAutomationRuleId("");
        setPendingRepeatAutomationDeleteId("");
        setLocalAutomationRevision((value) => value + 1);
        setOperationDetail("반복 업무 수정 완료");
        setLastRun({
          kind: "feature",
          result: { status: "queued", label: "반복 업무 수정" },
          boundary: { label: "반복 설정", detail: "저장된 반복 업무를 쉬운 문장으로 수정", tone: "chat" },
          routeLabel: "반복 업무 관리",
          runtimeProofLabel: "로컬 반복 업무 수정",
          safetyGate: "수정만 저장, 외부 실행 없음",
          nextUserChoice: "반복 업무 점검 또는 오피스 승인함",
        });
        commitActionMessage("repeat-work-updated", {
          text: [
            "반복 업무를 수정했습니다.",
            `${updatedRule.title}`,
            `언제: ${updatedRule.trigger}`,
            `무엇: ${trimmedWhat}`,
            `보여줄 곳: ${updatedRule.output}`,
            `승인 기준: ${updatedRule.approval}`,
            "수정은 로컬 반복 업무 기준만 바꾸며 외부 발송, 일정 등록, 파일 변경은 실행하지 않았습니다.",
          ].join("\n"),
      actions: [
        { label: updatedRule.enabled ? "반복 업무 끄기" : "반복 업무 켜기", action: "repeat_work_enable_latest" },
        ...(isReportRepeatWorkCandidate(repeatWorkBuilder) ? [{ label: "보고서 초안 확인" as const, action: "delegation_report_draft" as const }] : []),
        { label: "반복 업무 점검", action: "automation_check" },
        { label: "오피스 보기", action: "open_office" },
      ],
        });
        return;
      }
      setEditingRepeatAutomationRuleId("");
    }
    const draft = saveLocalAutomationDraft({
      title: `반복 업무: ${trimmedWhat}`,
      goal: `${repeatWorkBuilder.when}에 ${trimmedWhat} 후 ${repeatWorkBuilder.where}에 보여줍니다.`,
      trigger: repeatWorkBuilder.when,
      output: repeatWorkBuilder.where,
      approval: repeatWorkBuilder.approval,
      connectorIds: connectorPlan.connectorIds,
      connectorLabels: connectorPlan.connectorLabels,
      provenance: {
        source: "work_pack",
        sourceLabel: "쉬운 반복 업무 빌더",
        intent: trimmedWhat,
        evidenceLabels: [
          `추천 이유: ${repeatWorkBuilder.when} 반복 확인`,
          `언제: ${repeatWorkBuilder.when}`,
          `결과 위치: ${repeatWorkBuilder.where}`,
          `필요 연결: ${connectorPlan.connectorLabels.join(", ")}`,
          `승인: ${repeatWorkBuilder.approval}`,
          "승인함: 실행하기, 고쳐달라고 하기, 보류하기는 오피스 승인함",
          `실행 경로: ${repeatWorkPath}`,
        ],
        capturedAt: new Date().toISOString(),
      },
    });
    const rule = createLocalAutomationRuleFromDraft(draft);
    const previewWorkItem = localAutomationDraftToWorkItem(draft);
    setLastRepeatAutomationRule(rule);
    setLastRepeatWorkApprovalPreview(previewWorkItem);
    setPendingRepeatAutomationDeleteId("");
    setLocalAutomationRevision((value) => value + 1);
    setOperationDetail("반복 업무 후보 저장 완료");
    setLastRun({
      kind: "feature",
      result: { status: "queued", label: "반복 업무 만들기" },
      boundary: { label: "지금 처리", detail: "문장 빌더에서 반복 업무 후보 저장", tone: "chat" },
      routeLabel: "반복 설정",
      runtimeProofLabel: "문장 빌더 -> 기본 꺼짐 저장 -> 사용자가 켠 뒤 점검 -> 오피스 승인함/실행 로그",
      safetyGate: "기본 꺼짐, 승인 기준 저장",
      nextUserChoice: "반복 업무 점검 또는 필요한 연결",
    });
    commitActionMessage("repeat-work-saved", {
      text: [
        "반복 업무 후보를 저장했습니다.",
        `언제: ${draft.trigger}`,
        `무엇: ${draft.goal}`,
        `보여줄 곳: ${draft.output}`,
        `승인 기준: ${draft.approval}`,
        `추천 이유: ${repeatWorkBuilder.when}마다 ${trimmedWhat} 흐름을 확인하기 위해 저장했습니다.`,
        `필요 연결: ${connectorPlan.connectorLabels.join(", ")}`,
        `승인 후보: ${previewWorkItem.title}`,
        "상태: 승인 대기 · 오피스 승인함에서 실행하기, 고쳐달라고 하기, 보류하기",
        `실행 경로: ${repeatWorkPath}`,
        "반복 업무는 기본 꺼짐 상태입니다. 사용자가 켜고 점검할 때만 실행 후보를 만듭니다.",
      ].join("\n"),
      repeatWorkApprovalPreview: previewWorkItem,
      actions: [
        { label: "반복 업무 켜기", action: "repeat_work_enable_latest" },
        ...(isReportRepeatWorkCandidate(repeatWorkBuilder) ? [{ label: "보고서 초안 확인" as const, action: "delegation_report_draft" as const }] : []),
        { label: "반복 업무 점검", action: "automation_check" },
        { label: "오피스 보기", action: "open_office" },
        { label: "필요 연결", action: "external_accounts" },
      ],
    });
    void recordTeammateWorkEvent(
      rule.id,
      activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations"),
        previewWorkItem.title,
        "done",
        `${repeatWorkBuilder.when} · ${repeatWorkBuilder.where} · ${repeatWorkBuilder.approval}`,
        {
          source: "쉬운 반복 업무 빌더",
          connectorCount: connectorPlan.connectorIds.length,
          ruleEnabled: rule.enabled,
          approvalLocked: true,
        },
      );
  }

  function syncLocalAutomationRuleToDesktop(rule: LocalAutomationRule) {
    const activeBridge = bridge?.isAvailable ? bridge : createDesktopBridge();
    if (!activeBridge?.isAvailable) return;
    const desktopRule = createDesktopTriggerRuleFromLocalRule(rule);
    void activeBridge.updateTriggerRule(desktopRule).catch(() => undefined);
  }

  function setSecureMailWindowsNotification(rule: LocalAutomationRule, enabled: boolean) {
    if (rule.id !== SECURE_MAIL_POLLING_RULE_ID) return;
    const nextRules = updateLocalAutomationRule(rule.id, {
      notificationChannels: {
        appInbox: rule.notificationChannels?.appInbox !== false,
        os: enabled,
        telegram: rule.notificationChannels?.telegram === true,
      },
    });
    const updatedRule = nextRules.find((item) => item.id === rule.id) ?? rule;
    setLastRepeatAutomationRule(updatedRule);
    setPendingRepeatAutomationDeleteId("");
    setLocalAutomationRevision((value) => value + 1);
    setOperationDetail(enabled ? "메일 Windows 알림 켜기 완료" : "메일 Windows 알림 끄기 완료");
    syncLocalAutomationRuleToDesktop(updatedRule);
    commitActionMessage(enabled ? "secure-mail-windows-notification-enabled" : "secure-mail-windows-notification-disabled", {
      text: [
        `메일 5분 자동 점검 Windows 알림을 ${enabled ? "켰습니다" : "껐습니다"}.`,
        enabled
          ? "새 메일이 감지되어 메일 자동 점검 알림 초안이 만들어진 뒤에만 Windows 알림을 한 번 표시합니다."
          : "앱 승인함 알림 초안만 만들고 Windows 알림은 표시하지 않습니다.",
        "메일 발송, 캘린더 등록, 첨부 이동/삭제는 계속 오피스 마지막 확인 전까지 잠겨 있습니다.",
      ].join("\n"),
      actions: [
        { label: updatedRule.enabled ? "반복 업무 점검" : "5분 점검 켜기", action: updatedRule.enabled ? "automation_check" : "secure_mail_polling_enable" },
        { label: "오피스 보기", action: "open_office" },
      ],
    });
  }

  function enableLatestRepeatWorkRule() {
    if (typeof window === "undefined") return;
    const rules = readLocalAutomationRules();
    const candidate = lastRepeatAutomationRule ?? rules[0] ?? null;
    if (!candidate) {
      commitActionMessage("repeat-work-enable-empty", {
        text: "켤 반복 업무 후보가 아직 없습니다. 먼저 네 칸을 채워 반복 후보를 저장해 주세요.",
      });
      return;
    }
    if (candidate.enabled) {
      commitActionMessage("repeat-work-enable-already", {
        text: `이미 켜져 있습니다.\n${candidate.title}\n반복 업무 점검을 누르면 설치 앱에서 연결된 업무툴을 읽고 승인 후보와 실행 로그를 만듭니다.`,
        actions: [
          { label: "반복 업무 점검", action: "automation_check" },
          { label: "필요 연결", action: "external_accounts" },
        ],
      });
      return;
    }

    const nextRules = toggleLocalAutomationRule(candidate.id);
    const enabledRule = nextRules.find((rule) => rule.id === candidate.id) ?? { ...candidate, enabled: true };
    setLastRepeatAutomationRule(enabledRule);
    setPendingRepeatAutomationDeleteId("");
    setLocalAutomationRevision((value) => value + 1);
    syncLocalAutomationRuleToDesktop(enabledRule);
    setOperationDetail("반복 업무 켜기 완료");
    setLastRun({
      kind: "feature",
      result: { status: "queued", label: "반복 업무 켜기" },
      boundary: { label: "반복 설정", detail: "사용자가 켠 반복 업무만 점검 대상", tone: "chat" },
      routeLabel: "반복 업무",
      runtimeProofLabel: "로컬 반복 업무 켜짐",
      safetyGate: "외부 실행 전 오피스 승인함 보류",
      nextUserChoice: "반복 업무 점검 또는 오피스 승인함",
    });
    commitActionMessage("repeat-work-enabled", {
      text: [
        "반복 업무를 켰습니다.",
        `${enabledRule.title}`,
        `언제: ${enabledRule.trigger}`,
        `보여줄 곳: ${enabledRule.output}`,
        `승인 기준: ${enabledRule.approval}`,
        "이제 반복 업무 점검 대상에 포함됩니다. 외부 발송, 일정 등록, 파일 변경은 승인 전까지 실행하지 않습니다.",
      ].join("\n"),
      actions: [
        { label: "옆에 고정", pinAutomationRuleId: enabledRule.id },
        { label: "반복 업무 점검", action: "automation_check" },
        { label: "오피스 보기", action: "open_office" },
      ],
    });
    void recordTeammateWorkEvent(
      enabledRule.id,
      activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations"),
      enabledRule.title,
      "done",
      `켜짐 · ${enabledRule.trigger} · ${enabledRule.output}`,
      {
        source: "쉬운 반복 업무 빌더",
        ruleEnabled: true,
        approvalLocked: true,
      },
    );
  }

