    const nextRules = rule.enabled ? readLocalAutomationRules() : toggleLocalAutomationRule(rule.id);
    const enabledRule = nextRules.find((item) => item.id === rule.id) ?? { ...rule, enabled: true };
    const previewWorkItem = createWorkPackLocalCheckWorkItem(enabledRule);
    setLastRepeatAutomationRule(enabledRule);
    setLastRepeatWorkApprovalPreview(previewWorkItem);
    setPendingRepeatAutomationDeleteId("");
