  function buildEasySetupConnectionGate(signal: EasySetupPreviewSignal, statuses: ConnectorStatusRecord[]) {
    if (signal.featureId === "feature-mail") {
      const ready = hasReadyConnector(statuses, "mail");
      return {
        id: "mail-connection",
        blocked: !ready,
        label: ready ? "메일 읽기 준비" : "메일/캘린더 연결 필요",
        title: ready ? "메일 읽기 전용 확인 가능" : "연결 전에는 메일을 읽은 척하지 않습니다",
        detail: ready
          ? "연결된 메일을 읽기 전용 후보로 사용하고 발송, 이동, 삭제는 승인 전까지 잠급니다."
          : "메일 제목, 보낸 사람, 답장 초안, 일정 후보, 수신자 판단은 실제 연결이 확인된 뒤에만 만듭니다.",
        approvalDetail: "발송, 일정 등록, 메일 이동/삭제는 오피스 승인함 최종 확인 전까지 실행하지 않습니다.",
        action: "mail_connection" as HomeAction,
        actionLabel: "메일/캘린더 연결",
        blockedPreview: "메일/캘린더 연결 전에는 메일 수, 답장 초안, 일정 후보를 만들지 않습니다.",
      };
    }
    if (signal.featureId === "feature-schedule-prep") {
      const ready = hasReadyConnector(statuses, "calendar");
      return {
        id: "calendar-connection",
        blocked: !ready,
        label: ready ? "캘린더 읽기 준비" : "캘린더 연결 필요",
        title: ready ? "일정 후보 확인 가능" : "연결 전에는 가능 시간을 읽은 척하지 않습니다",
        detail: ready
          ? "연결된 캘린더를 읽기 전용 후보로 확인하고 실제 등록은 승인 전까지 잠급니다."
          : "가능 시간, 참석자, 알림, 충돌 시간, 일정 제목 후보는 캘린더 연결이 확인된 뒤에만 만듭니다.",
        approvalDetail: "캘린더 등록, 초대 발송, 외부 공유는 오피스 승인함 최종 확인 전까지 실행하지 않습니다.",
        action: "calendar_connection" as HomeAction,
        actionLabel: "캘린더 연결",
        blockedPreview: "캘린더 연결 전에는 가능 시간과 일정 후보를 만들지 않습니다.",
      };
    }
    return null;
  }

