  function easySetupWorkPatternSourceKind(featureId: string): LocalMemoryWorkPattern["sourceKind"] {
    if (featureId === "feature-mail" || featureId === "feature-schedule-prep") return "mailops";
    if (featureId === "feature-document-learning") return "document_learning";
    if (featureId === "feature-tidy") return "folder_plan";
    if (featureId === "feature-draft-report") return "document_writer";
    if (featureId === "feature-computer-use") return "desktop_control";
    return "general";
  }

  function easySetupWorkPatternSourceLabel(signal: EasySetupPreviewSignal) {
    if (signal.featureId === "feature-mail") return "메일 점검 승인 기준";
    if (signal.featureId === "feature-schedule-prep") return "일정 승인 기준";
    if (signal.featureId === "feature-document-learning") return "문서 학습 승인 기준";
    if (signal.featureId === "feature-tidy") return "폴더 정리 승인 기준";
    if (signal.featureId === "feature-draft-report") return "보고서 승인 기준";
    if (signal.featureId === "feature-repeat-work") return "반복 업무 승인 기준";
    if (signal.featureId === "feature-computer-use") return "내 PC 작업 승인 기준";
    return "쉬운 시작 다음부터 이렇게";
  }

  function selectEasyStartTemplate(template: GeneralUserStartTemplate) {
    setSelectedEasyStartId(template.id);
    setEasySetupPreviewSignal(createEasySetupPreviewSignal(template));
    setOperationDetail(`${template.label} 미리보기 준비`);
  }

  async function runEasySetupPreview(template: GeneralUserStartTemplate) {
    if (busy) return;
    const catalogItem = getFeatureLauncherCatalogItem(template.featureId);
    const nextUserChoice = catalogItem?.nextUserChoice ?? "오피스 승인함 또는 필요한 연결 확인";
    const runtimeProofLabel = catalogItem?.runtimeProofLabel ?? template.runtimeLabel;
    setSelectedEasyStartId(template.id);
    setEasySetupPreviewSignal(createEasySetupPreviewSignal(template));
    setLastRun({
      kind: "feature",
      result: { status: "queued", label: template.label },
      boundary: { label: "쉬운 세팅", detail: "미리보기 후 승인함에서 실행 확인", tone: "chat" },
      featureId: template.featureId,
      routeLabel: template.readinessLabel,
      runtimeProofLabel,
      safetyGate: catalogItem?.safetyGate ?? template.safetyLabel,
      nextUserChoice,
      blockedReason: catalogItem?.blockedReason ?? easySetupBlockedReason(template.featureId),
    });
    setOperationDetail(`${template.label} 미리보기 준비`);
  }

  function easySetupActionStageLabel(stage: EasySetupActionStage) {
    if (stage === "prepare") return "자료/계정 준비";
    if (stage === "approval") return "승인 확인";
    return "실제 실행";
  }

  function easySetupActionHandoffDetail(signal: EasySetupPreviewSignal, stage: EasySetupActionStage) {
    const stageLabel = easySetupActionStageLabel(stage);
    return `${stageLabel}로 이동합니다. ${signal.firstThreeMinuteSuccess} 흐름을 유지하고, ${signal.confirmationLocation}에서 승인 전 확인합니다.`;
  }

  function runEasySetupAction(signal: EasySetupPreviewSignal, action: HomeAction, stage: EasySetupActionStage) {
    if (busy) return;
    const stageLabel = easySetupActionStageLabel(stage);
    setLastRun({
      kind: "feature",
      result: { status: "queued", label: signal.label },
      boundary: { label: "쉬운 세팅 실행", detail: easySetupActionHandoffDetail(signal, stage), tone: "chat" },
      featureId: signal.featureId,
      routeLabel: stageLabel,
      runtimeProofLabel: signal.runtimeProofLabel,
      safetyGate: signal.safetyLabel,
      nextUserChoice: signal.nextUserChoice,
      blockedReason: signal.blockedReason,
    });
    setOperationDetail(`${signal.label} ${stageLabel}로 이동`);
    void runHomeAction(action);
  }

  async function rememberEasySetupPattern(signal: EasySetupPreviewSignal) {
    if (rememberingMessageId) return;
    const teammate = activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("personal");
    const saveId = `easy-setup-pattern-${signal.id}-${Date.now()}`;
    const sourceKind = easySetupWorkPatternSourceKind(signal.featureId);
    const sourceLabel = easySetupWorkPatternSourceLabel(signal);
    const tidySafetySignals = signal.featureId === "feature-tidy"
      ? [
          `겹침 처리: ${tidyCandidate.collisionPolicy}`,
          `제외 단어: ${formatTidyExcludedKeywordsLabel(tidyCandidate.excludedPathKeywords)}`,
          "삭제/덮어쓰기: 하지 않음",
        ]
      : [];
    const tidySafetySummary = signal.featureId === "feature-tidy"
      ? ` ${formatTidyCandidateSafetySummary(tidyCandidate)}`
      : "";
    setRememberingMessageId(saveId);
    setOperationPhase("syncing");
    setOperationDetail("쉬운 시작 방식 저장 중");
    try {
      const result = await rememberWorkPattern({
        id: saveId,
        sourceKind,
        sourceLabel,
        teammateId: teammate.id,
        teammateName: teammate.name,
        summary: `${signal.label}은 ${signal.setupPreview} 흐름으로 먼저 미리보고, ${signal.setupApproval} 기준으로 승인 후 실행합니다.${tidySafetySummary}`,
        signals: [
          `쉬운 시작 기능: ${signal.label}`,
          `저장 분류: ${sourceLabel}`,
          `업무 종류: ${labelWorkPatternSourceKind(sourceKind)}`,
          `실행 증거: ${signal.runtimeProofLabel}`,
          `준비 버튼: ${signal.prepareLabel}`,
          `실행 버튼: ${signal.runLabel}`,
          `승인 버튼: ${signal.approvalLabel}`,
          `막히면: ${signal.visibleNextUserChoice}`,
          `작동 확인: ${signal.runtimeProofLabel}`,
          ...tidySafetySignals,
          "다음 유사 요청에서 추천 카드로 먼저 보여줌",
          "저장한 방식은 AI 답변 프롬프트에 참고 기준으로만 반영",
          "외부 발송, 일정 등록, 파일 변경은 저장된 방식이 있어도 승인 전 실행하지 않음",
        ],
        artifactPaths: [
          "memory/work-patterns/WorkPatternMemory.md",
          `memory/crew-souls/${teammate.id}/PromptMemory.md`,
          `memory/crew-souls/${teammate.id}/WorkLog.md`,
        ],
        metrics: {
          source: "easy_setup_preview",
          templateId: signal.id,
          featureId: signal.featureId,
          workPatternSourceKind: sourceKind,
          approvalBoundaryKept: true,
          rawSecretMaterialStored: false,
        },
      });
      const saved = result?.status === "local_memory_work_learning_saved";
      if (saved) {
        setLastMemoryUpdateSignal({
          id: saveId,
          teammateId: teammate.id,
          teammateName: teammate.name,
          channelName: teammate.channelName,
          summary: `${signal.label} 쉬운 시작 방식을 저장했습니다.`,
          crewSoulPath: `memory/crew-souls/${teammate.id}/PromptMemory.md`,
          workLogPath: `memory/crew-souls/${teammate.id}/WorkLog.md`,
          createdAt: Date.now(),
        });
      }
      commitActionMessage(`remember-easy-setup-${signal.id}`, {
        text: saved
          ? [
              `${signal.label} 방식을 다음부터 이렇게 처리하도록 저장했습니다.`,
              `저장 위치: 저장한 방식 ${result.workPatternCount ?? 0}건`,
              "승인이 필요한 작업은 저장된 방식이 있어도 실행 전 다시 확인합니다.",
            ].join("\n")
          : [
              `${signal.label} 방식은 설치된 Windows 앱에서 저장한 방식으로 보관됩니다.`,
              "지금은 웹 미리보기라 실제 로컬 기억 파일을 쓰지 않았습니다.",
              "설치 앱에서 같은 버튼을 누르면 다음 유사 요청에 추천 카드로 먼저 보여줍니다.",
            ].join("\n"),
        actions: [
          { label: "저장한 방식 보기", action: "memory_inspect" },
          { label: signal.approvalLabel, action: signal.approvalAction },
        ],
      });
    } finally {
      setRememberingMessageId("");
      setOperationPhase("idle");
      setOperationDetail("대화 대기");
    }
  }

  async function runHomeAction(action: HomeAction) {
    if (action === "retry_pending_ai_request") {
      await resumePendingAIRequest();
      return;
    }
    if (action === "resume_connector_blocked_request") {
      resumePendingConnectorBlockedRequest();
      return;
    }
    if (
      pendingConnectorResume &&
      (action === pendingConnectorResume.resumeHomeAction || action === "mailops_check" || action === "calendar_connection")
    ) {
      const nextStatuses = await refreshConnectorStatusesForResume();
      if (pendingConnectorResumeConnectionsReady(pendingConnectorResume, nextStatuses)) {
        resumePendingConnectorBlockedRequest();
        return;
      }
    }
    if (busy) return;
    const featureId = getFeatureLauncherIdForAction(action, aiConnected);
    if (featureId) recordRecentFeatureLaunch(featureId);
    setSettingsOpen(false);
    if (action === "comfort_setup") {
      openComfortSetupCard();
      return;
    }
    if (action === "open_office") {
      const shouldOpenOfficeDetail = Boolean(mailOpsSession?.result);
      if (shouldOpenOfficeDetail) setMailOpsDetailsOpen(false);
      openWorkspacePanel("open_office");
      if (shouldOpenOfficeDetail) setWorkspaceWindowOpen(true);
      return;
    }
    if (action === "mail_automation_approval_focus") {
      openMailAutomationApprovalFocus();
      return;
    }
    if (action === "work_pattern_manager") {
      setSettingsOpen(false);
      setWorkspacePanelCollapsed(false);
      setWorkspacePanel("skills");
      setWorkspaceWindowOpen(true);
      setWorkspacePanelViewMap((current) => ({ ...current, skills: "records" }));
      setInlineSingleSettingId(null);
      setInlineVaultOpen(false);
      setInlineSelectedConnectorId(null);
      setInlineRecommendedConnectorIds([]);
      setInlineConnectGoal("저장한 방식을 수정하거나 삭제합니다");
      setInlineConnectNotice("저장한 방식 관리만 열었습니다. 원본 파일, 외부 계정, 과거 대화는 바꾸지 않습니다.");
      setOperationDetail("저장한 방식 관리 열림");
      return;
    }
    if (action === "memory_search_approval_request") {
      await stageLatestMemorySearchDraftApproval();
      return;
    }
    if (action === "ai_alternatives") {
      // '대체 답변 연결'이 외부 사이트 비밀번호 보관함으로 가던 자리. AI 를 고르는 목록을 연다.
      openWorkspacePanel("ai_settings");
      setAIAlternativesOpen(true);
      setInlineConnectNotice("GPT 말고 쓸 AI를 골라 주세요. 이 PC에 로그인된 구독 계정이 있으면 맨 위에 보여드려요.");
      setOperationDetail("다른 AI 연결 방법 열림");
      if (bridge) {
        void bridge
          .listSubscriptionAIRuntimes()
          .then((result) => setSubscriptionAIRuntimes(result.runtimes ?? []))
          .catch(() => undefined);
      }
      return;
    }
    if (action === "ai_connection_recheck") {
      // 로그인 창은 새로 열지 않고, 이미 끝난 로그인이 있는지 다시 확인한다.
      if (!bridge?.isAvailable) {
        setComposerNotice("AI 연결 확인은 설치된 Windows 앱에서 할 수 있어요.");
        return;
      }
      setComposerNotice("AI 연결을 다시 확인하고 있어요. 로그인이 끝나 있으면 바로 알려드릴게요.");
      startCodexOAuthCompletionWatch(
        bridge,
        { status: "codex_oauth_login_started", provider: "codex_oauth" },
        activeThreadIdRef.current,
      );
      return;
    }
    if (action === "connect_ai") {
      const now = Date.now();
      const aiConnectionThreadId = activeThreadIdRef.current;
      // 'AI 연결하러 가기'·'AI 연결 확인'은 언제나 AI 연결 화면을 연다. 로그인 재확인은 그 화면 옆에서 이어서 진행한다.
      openWorkspacePanel("connect_ai");
      // Claude·Gemini·API 키·내 PC 모델처럼 GPT 가 아닌 AI 를 이미 쓰고 있으면, 쓰지 않는 ChatGPT 로그인 창을
      // 새로 열지 않는다. 연결 화면에서 사용자가 쓸 AI 를 고르고, 확인되면 보관한 요청을 이어서 처리한다.
      if (hasOtherAnswerCapableAIProvider(aiProviderStatusesRef.current)) {
        setInlineConnectNotice("AI 연결 화면을 열었어요. 쓰실 AI를 고르거나 연결을 다시 확인해 주세요. 확인되면 보관한 요청을 이어서 처리합니다.");
        setOperationDetail("AI 연결 화면 열림");
        return;
      }
      if (aiConnectionActionInFlightRef.current || now - aiConnectionLastStartedAtRef.current < 1_500) {
        setInlineConnectNotice("AI 로그인 요청은 이미 처리 중입니다. 새 창을 반복해서 열지 않고 현재 요청 결과만 기다립니다.");
        return;
      }
      // Claude·Gemini·OpenAI 키·내 PC 모델처럼 GPT 가 아닌 AI 가 이미 답할 수 있으면,
      // GPT 로그인을 새로 연다고 해서 그 확인 기록을 지우지 않는다. 지우면 크루 위임·
      // 첫 업무 버튼이 다시 잠기고, 사용자는 쓰지도 않는 ChatGPT 로그인으로 계속 떠밀린다.
      if (!hasOtherAnswerCapableAIProvider(aiProviderStatusesRef.current)) {
        homeAIRuntimeReceiptConnectionSignatureRef.current = "";
        homeAIRuntimeProofInvalidatedRef.current = true;
        setLastHomeAIRuntimeReceipt(null);
        setHomeAIRuntimeLiveProofs(null);
        setAiConnected(false);
      }
      aiConnectionActionInFlightRef.current = true;
      aiConnectionLastStartedAtRef.current = now;
      setBusy(true);
      setOperationPhase("connecting");
      setOperationDetail("AI 로그인 준비 · 실제 답변 재확인");
      try {
        const result = bridge?.isAvailable
          ? await bridge.startAIProviderOAuth("codex_oauth", { forceReconnect: false }).catch((error) => ({
              status: "codex_oauth_start_failed",
              provider: "codex_oauth",
              authMode: "codex_oauth" as const,
              userMessage: "AI 로그인을 시작하지 못했습니다. 앱을 다시 실행하거나 AI 연결 설정을 확인해 주세요.",
              errorMessage: error instanceof Error ? error.message : String(error),
              diagnosticStage: "oauth_start_failed",
              recoveryActions: [
                "AI 로그인 다시 열기",
                "설치 앱과 로컬 도구 로그인 상태 확인",
                "대체 답변 엔진 준비",
              ],
              rawSecretMaterialStored: false as const,
            }))
          : null;
        setLastCodexOAuthStart(result);
        commitThreadActionMessage(aiConnectionThreadId, "ai-connect", {
          text:
            (result ? formatAIConnectionStartMessage(result) : null) ??
            "AI 연결은 설치된 Windows 앱에서 안전한 로그인 창을 열어 진행합니다.",
          actions: pendingAIRequest
            ? [{ label: "연결 후 이어 처리", action: "retry_pending_ai_request" }]
            : [],
        });
        if (bridge) await refreshWorkspace(bridge);
        if (bridge && result) {
          startCodexOAuthCompletionWatch(bridge, result, aiConnectionThreadId);
        }
      } finally {
        aiConnectionActionInFlightRef.current = false;
        setBusy(false);
        if (!codexOAuthCompletionWatchRef.current) {
          setOperationPhase("idle");
          setOperationDetail("대화 대기");
        }
      }
      return;
    }
    const panel = workspacePanelForAction(action);
    if (
      panel &&
      action !== "delegation_report_draft" &&
      action !== "learn_files" &&
      action !== "learn_folders" &&
      action !== "calendar_connection" &&
      action !== "computer_use"
    ) {
      setWorkspacePanelCollapsed(false);
      setWorkspacePanel(panel);
      setWorkspaceWindowOpen(action === "workers");
      applyWorkspaceSingleSettingForAction(action);
    }
    if (action === "mail_connection") {
      setOperationDetail("메일/캘린더 연결 입력 패널 열림");
      return;
    }
    if (
      action === "ai_settings" ||
      action === "calendar_connection" ||
      action === "messenger_connectors" ||
      action === "telegram_connection" ||
      action === "slack_connection" ||
      action === "discord_connection"
    ) {
      setOperationDetail(getPanelOnlyActionDetail(action));
        if (action === "calendar_connection") {
          commitGuideMessage("calendar-connection", {
            text:
              "일정 준비는 캘린더 연결을 확인한 뒤 가능한 시간과 일정 제목 후보를 먼저 보여줍니다. 실제 캘린더 등록은 승인 전까지 실행하지 않습니다.",
            workflow: buildRepresentativeFeatureWorkflow("calendar_connection", "ready"),
            executionReceipt: buildSchedulePrepExecutionReceipt(scheduleCandidate),
            actions: [
            { label: "메일 점검", action: "mailops_check" },
            { label: "계정 보관함", action: "external_accounts" },
            { label: "오피스 보기", action: "open_office" },
          ],
        });
      }
      return;
    }
    if (action === "external_accounts") {
      openWorkspacePanel("external_accounts");
      commitGuideMessage("external-accounts", {
        text:
          "외부 사이트 아이디와 비밀번호는 채팅에 쓰지 말고 연결 패널이나 계정 보관함에 저장합니다. 저장된 값은 OS 보안 저장소로 암호화되고, 저는 필요한 작업 때 참조만 사용합니다.",
        actions: [{ label: "계정 보관함 입력", action: "external_accounts" }],
      });
      return;
    }
    if (action === "memory_root") {
      openWorkspacePanel("memory_root");
      return;
    }
    if (action === "memory_inspect") {
      await inspectPortableMemory();
      return;
    }
    if (action === "workspace_skill_proposals") {
      await reviewNextWorkspaceSkillProposal();
      return;
    }
    if (action === "workspace_skill_activate") {
      await activateWorkspaceSkillForTeammate();
      return;
    }
    if (action === "learn_folders") {
      await attachFoldersToChat("", "", "learning");
      return;
    }
    if (action === "computer_scope_panel") {
      openWorkspacePanel("computer_scope_panel");
      setOperationDetail("내 PC 작업 범위 선택");
      return;
    }
    if (action === "delegate_active_worker") {
      const target = activeTeammate ?? teammates[0];
      if (target) {
        await delegateToSpecificTeammate(target, `${target.name} 채널에서 지금 요청을 맡아줘`);
      }
      return;
    }
    if (action === "worker_first_work") {
      await startFirstWorkWithSelectedRole();
      return;
    }
    if (action === "worker_companion_window") {
      await openWorkerCompanionWindow();
      return;
    }
    if (action === "restore_last_removed_worker") {
      restoreLastRemovedTeammate();
      return;
    }
    if (isPanelOnlyAction(action)) {
      setOperationDetail(getPanelOnlyActionDetail(action));
      return;
    }

    if (action === "automation_log") {
      await openAutomationCheckLog();
      return;
    }

    if (
      !desktopReady &&
      action !== "learn_files" &&
      action !== "delegation_report_draft" &&
      action !== "daily_activity_report" &&
      action !== "mail_recipient_list_review" &&
      action !== "repeat_work_enable_latest" &&
      action !== "webmail_metadata_rehearsal" &&
      !isComputerUseAction(action)
    ) {
      commitActionMessage("desktop-required", {
        text: "이 단계는 설치된 Windows 앱에서 바로 이어집니다. 지금 화면이 설치 앱이면 잠시 후 다시 눌러 주세요.",
      });
      return;
    }

    if (isComputerUseAction(action)) {
      setBusy(true);
      setOperationPhase("checking");
      setOperationDetail("내 PC 작업 도우미 권한 확인");
      try {
        const activeBridge = bridge ?? createDesktopBridge();
        const nextRecords = activateFeature("desktop_control", "내 PC 작업 도우미 기본 안전 모드");
        setFeatureRecords(nextRecords);
        const statusResult = activeBridge.isAvailable
          ? await activeBridge.getDesktopControlStatus({ featureEnabled: true })
          : desktopControlStatus;
        if (statusResult) setDesktopControlStatus(statusResult);

        if (action !== "computer_use") {
          setOperationDetail(getComputerUseOperationLabel(action));
          const result = await runComputerUseRequest(action);
          if (action === "computer_recent_files") {
            setComputerUseRecentFileCandidates(result.observedFiles?.slice(0, 5) ?? []);
          }
          if (action === "computer_file_task" && result.status === "work_item_staged") {
            setComputerUseRecentFileCandidates([]);
          }
          if (result.stagedWorkItem) {
            rememberOfficeFinalActionFocus(result.stagedWorkItem.id);
            await refreshWorkspace(activeBridge);
          }
          setComputerUsePreviewSignal(createComputerUsePreviewSignal(action, result));
          commitActionMessage(`desktop-control-${action}`, {
            text: formatDesktopControlResult(result),
            executionReceipt: buildComputerUseExecutionReceipt(result, action),
            computerUseApprovalPreview: createComputerUseApprovalPreview(result),
            actions: getComputerUseFollowupActions(action, result),
          });
          return;
        }

        const enabledReadCount =
          statusResult?.capabilities.filter((capability) => capability.enabled && capability.externalMutation === false).length ?? 0;
        const lockedMutationCount =
          statusResult?.capabilities.filter((capability) => capability.externalMutation && !capability.enabled).length ?? 0;
        commitActionMessage("computer-use", {
          text: [
            "내 PC 작업을 기본 안전 모드로 켰습니다.",
            desktopReady
              ? `${enabledReadCount}개 읽기/준비 기능을 사용할 수 있고, 클릭·입력·파일 쓰기 같은 ${lockedMutationCount}개 변경 작업은 승인 전 잠겨 있습니다.`
              : "설치된 Windows 앱에서 실행하면 창 확인, 파일 선택, 브라우저 업무 카드 만들기가 연결됩니다.",
            "브라우저 업무 카드는 오피스 승인함에서 화면 증거, 대상 매칭, 마지막 확인, 최종 문구 확인 순서로 이어집니다.",
          ].join("\n"),
          workflow: buildRepresentativeFeatureWorkflow("computer_use", "safe"),
          actions: [
            { label: "작업 범위 고르기", action: "computer_scope_panel" },
            { label: "열린 창 확인", action: "computer_windows" },
            { label: "최근 파일", action: "computer_recent_files" },
            { label: "브라우저 업무 카드", action: "computer_browser_task" },
            { label: "오피스 승인함", action: "open_office" },
          ],
        });
        setComputerUsePreviewSignal({
          id: `computer-use-safe-${Date.now()}`,
          title: "기본 안전 모드",
          rangeLabel: desktopReady ? "설치 앱 브리지에서 창/파일/브라우저 후보를 읽습니다." : "설치 앱에서 이어 실행합니다.",
          previewLabel: "열린 창, 최근 파일, 브라우저 업무 카드 중 하나를 골라 미리보기로 만듭니다.",
          approvalLabel: "클릭, 입력, 파일 변경은 승인 전까지 잠겨 있습니다.",
          logLabel: "실행 기록은 오피스 승인함과 감사 로그에 남깁니다.",
          rollbackLabel: "변경 전 단계라 되돌릴 작업은 아직 없습니다.",
          state: "ready",
        });
      } finally {
        setBusy(false);
        setOperationPhase("idle");
        setOperationDetail("대화 대기");
      }
      return;
    }

    if (action === "prepare_tools") {
      setBusy(true);
      setOperationPhase("toolchain");
      setOperationDetail("기본 업무 도구 확인 중");
      try {
        const result = bridge?.isAvailable ? await bridge.prepareToolchain() : null;
        const hasPendingAIRequest = Boolean(pendingAIRequestRef.current ?? pendingAIRequest);
        commitActionMessage("prepare-tools", {
          text: result ? formatToolchainMessage(result) : "설치된 Windows 앱에서 Git, Node.js, Python 같은 기본 도구를 확인합니다.",
          actions: buildToolchainRecoveryActions(hasPendingAIRequest),
        });
      } finally {
        setBusy(false);
        setOperationPhase("idle");
        setOperationDetail("대화 대기");
      }
      return;
    }

    if (action === "install_ai_runtime") {
      setBusy(true);
      setOperationPhase("toolchain");
      setOperationDetail("AI 연결 복구 도구 설치 중");
      try {
        const result = bridge?.isAvailable ? await bridge.installCodexRecoveryTool() : null;
        const installed =
          result?.status === "codex_install_completed" || result?.status === "codex_install_already_ready";
        commitActionMessage("install-ai-runtime", {
          text:
            result?.userMessage ??
            "AI 연결 복구 도구 설치는 설치된 Windows 앱 안에서만 실행됩니다.",
          actions: installed
            ? [
                { label: "AI 연결 다시 확인", action: "connect_ai" },
                { label: "작업 상태 보기", action: "open_office" },
              ]
            : [
                { label: "대체 답변 연결", action: "external_accounts" },
                { label: "연결 복구 확인", action: "prepare_tools" },
              ],
        });
        if (installed && bridge?.isAvailable) {
          void bridge
            .getToolchainStatus()
            .then(setHomeToolchainStatus)
            .catch(() => undefined);
        }
      } finally {
        setBusy(false);
        setOperationPhase("idle");
        setOperationDetail("대화 대기");
      }
      return;
    }
    if (action === "mailops_check") {
      await runMailOpsCrewKit("manual", activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations"));
      return;
    }

    if (action === "mail_live_e2e_rehearsal") {
      setBusy(true);
      setOperationPhase("checking");
      setOperationDetail("메일 live 리허설 실행 중");
      try {
        const activeBridge = bridge ?? createDesktopBridge();
        const result = await activeBridge.runMailLiveE2ERehearsal({ limit: 10 });
        setMailLiveE2ERehearsalResult(result);
        setMailOpsSession((current) => {
          if (!current?.result) return current;
          return {
            ...current,
            result: {
              ...current.result,
              messageCount: Math.max(current.result.messageCount ?? 0, result.messageCount ?? 0),
              ignoredItemsCount: Math.max(current.result.ignoredItemsCount ?? 0, result.ignoredItemsCount ?? 0),
              approvalQueueCount: Math.max(current.result.approvalQueueCount ?? 0, result.approvalQueueCount ?? 0),
              liveRehearsalReportPath: result.liveRehearsalReportPath,
              liveRehearsalReportJsonPath: result.liveRehearsalReportJsonPath,
              liveRehearsalReportSummary: result.liveRehearsalReportSummary,
              liveRehearsalEvidenceChecklist: result.liveRehearsalEvidenceChecklist,
            },
          };
        });
        if (activeBridge.isAvailable) await refreshWorkspace(activeBridge);
        recordMailLiveE2ERehearsalVirtualOfficeEvent(result);
        setWorkspacePanel("none");
        setWorkspacePanelCollapsed(false);
        setWorkspaceWindowOpen(false);
        commitActionMessage("mail-live-e2e-rehearsal", {
          text: formatMailLiveE2ERehearsalMessage(result),
          workflow: buildRepresentativeFeatureWorkflow("mailops_check", result.status === "ready_for_live_rehearsal" ? "ready" : "blocked"),
          executionReceipt: buildMailLiveE2ERehearsalReceipt(result),
          actions: [
            { label: "직원 활동 보기", action: "workers" },
            { label: "리포트 열기", action: "mail_live_e2e_report" },
            { label: "오피스 승인함", action: "mail_automation_approval_focus" },
            { label: "메일 다시 읽기", action: "mailops_check" },
            { label: "반복 업무 점검", action: "automation_check" },
          ],
        });
      } finally {
        setBusy(false);
        setOperationPhase("idle");
        setOperationDetail("대화 대기");
      }
      return;
    }

    if (action === "mail_live_e2e_evidence_template") {
      setBusy(true);
      setOperationPhase("checking");
      setOperationDetail("메일 수동 증거 템플릿 생성 중");
      try {
        const activeBridge = bridge ?? createDesktopBridge();
        const result = await activeBridge.runMailLiveE2ERehearsal({ writeEvidenceTemplate: true });
        setMailLiveE2ERehearsalResult(result);
        const templatePath =
          result.manualEvidenceTemplatePath ??
          result.strictReadiness?.evidenceTemplatePath ??
          "mail-live-e2e-manual-evidence.example.json";
        const guidePath =
          result.manualEvidenceGuidePath ??
          result.strictReadiness?.evidenceGuidePath ??
          "mail-live-e2e-manual-evidence-guide.md";
        commitActionMessage("mail-live-e2e-evidence-template", {
          text: [
            result.userMessage ?? "메일 live 수동 증거 템플릿을 만들었습니다.",
            `템플릿 위치: ${templatePath}`,
            `작성 가이드: ${guidePath}`,
            result.strictReadiness?.evidenceTemplateCommand
              ? `CLI 확인: ${result.strictReadiness.evidenceTemplateCommand}`
              : "",
            "이 템플릿에는 비밀번호, 2차 인증값, 토큰, 원문 HTML을 넣지 않습니다.",
          ].filter(Boolean).join("\n"),
          workflow: buildRepresentativeFeatureWorkflow(
            "mailops_check",
            result.status === "mail_live_e2e_evidence_template_created" ? "ready" : "blocked",
          ),
          actions: [
            { label: "실전 리허설", action: "mail_live_e2e_rehearsal" },
            { label: "리포트 열기", action: "mail_live_e2e_report" },
            { label: "오피스 승인함", action: "open_office" },
          ],
        });
      } finally {
        setBusy(false);
        setOperationPhase("idle");
        setOperationDetail("대화 대기");
      }
      return;
    }

    if (action === "mail_live_e2e_import_evidence") {
      setBusy(true);
      setOperationPhase("checking");
      setOperationDetail("메일 수동 증거 가져오기");
      try {
        const activeBridge = bridge ?? createDesktopBridge();
        const result = await activeBridge.runMailLiveE2ERehearsal({ importManualEvidence: true, limit: 10 });
        const imported = result.status === "mail_live_e2e_manual_evidence_import_canceled"
          ? false
          : result.status !== "desktop_required" && !/import_(?:invalid|too_large|unavailable|canceled)/u.test(result.status);
        if (imported) {
          setMailLiveE2ERehearsalResult(result);
          setMailOpsSession((current) => {
            if (!current?.result) return current;
            return {
              ...current,
              result: {
                ...current.result,
                messageCount: Math.max(current.result.messageCount ?? 0, result.messageCount ?? 0),
                ignoredItemsCount: Math.max(current.result.ignoredItemsCount ?? 0, result.ignoredItemsCount ?? 0),
                approvalQueueCount: Math.max(current.result.approvalQueueCount ?? 0, result.approvalQueueCount ?? 0),
                liveRehearsalReportPath: result.liveRehearsalReportPath,
                liveRehearsalReportJsonPath: result.liveRehearsalReportJsonPath,
                liveRehearsalReportSummary: result.liveRehearsalReportSummary,
                liveRehearsalEvidenceChecklist: result.liveRehearsalEvidenceChecklist,
              },
            };
          });
        }
        if (imported) {
          recordMailLiveE2ERehearsalVirtualOfficeEvent(result);
          setMailOpsDetailsOpen(true);
        }
        commitActionMessage("mail-live-e2e-import-evidence", {
          text: [
            result.userMessage ?? "메일 live 수동 증거 JSON을 가져왔습니다.",
            result.manualEvidenceImportFileName ? `가져온 파일: ${result.manualEvidenceImportFileName}` : "",
            result.manualEvidence?.evidenceSource ? `증거 출처: ${result.manualEvidence.evidenceSource}` : "",
            result.manualEvidence?.ignoredKeys?.length
              ? `무시한 키: ${result.manualEvidence.ignoredKeys.join(", ")}`
              : imported
                ? "무시한 키: 없음"
                : "",
            imported ? formatMailLiveE2ERehearsalMessage(result) : "",
            "수동 증거 import는 허용된 숫자/상태 키만 읽고 비밀번호, 토큰, 원문 HTML 값은 반영하지 않습니다.",
          ].filter(Boolean).join("\n"),
          workflow: buildRepresentativeFeatureWorkflow(
            "mailops_check",
            result.strictReadiness?.status === "strict_ready" ? "ready" : imported ? "blocked" : "blocked",
          ),
          executionReceipt: imported ? buildMailLiveE2ERehearsalReceipt(result) : undefined,
          actions: [
            { label: "증거 템플릿", action: "mail_live_e2e_evidence_template" },
            { label: "실전 리허설", action: "mail_live_e2e_rehearsal" },
            { label: "리포트 열기", action: "mail_live_e2e_report" },
          ],
        });
      } finally {
        setBusy(false);
        setOperationPhase("idle");
        setOperationDetail("대화 대기");
      }
      return;
    }

    if (action === "mail_live_e2e_report") {
      setBusy(true);
      setOperationPhase("checking");
      setOperationDetail("메일 live 리허설 리포트 열기");
      try {
        const activeBridge = bridge ?? createDesktopBridge();
        const result = await activeBridge.openMailLiveE2EReport();
        commitActionMessage("mail-live-e2e-report", {
          text: [
            result.userMessage ?? "메일 live 리허설 리포트를 확인했습니다.",
            result.reportPath ? `리포트 위치: ${result.reportPath}` : "",
            "리포트 열기는 읽기 동작이며 외부 발송, 일정 등록, 파일 변경을 실행하지 않습니다.",
          ].filter(Boolean).join("\n"),
          workflow: buildRepresentativeFeatureWorkflow(
            "mailops_check",
            result.status === "mail_live_e2e_report_opened" ? "ready" : "blocked",
          ),
          actions: [
            { label: "실전 리허설", action: "mail_live_e2e_rehearsal" },
            { label: "반복 업무 점검", action: "automation_check" },
            { label: "오피스 승인함", action: "open_office" },
          ],
        });
      } finally {
        setBusy(false);
        setOperationPhase("idle");
        setOperationDetail("대화 대기");
      }
      return;
    }

    if (action === "webmail_metadata_rehearsal") {
      setBusy(true);
      setOperationPhase("checking");
      setOperationDetail("웹메일 목록 리허설 실행 중");
      try {
        const activeBridge = bridge ?? createDesktopBridge();
        const result = await activeBridge.requestDesktopControlAction({
          capability: "read_webmail_metadata",
          featureEnabled: true,
          instruction: "IMAP이 막힌 회사 웹메일의 받은메일함 목록에서 제목, 보낸 사람 표시명, 시간, 첨부 표시만 읽고 업무 후보를 리허설합니다.",
          webmailFallback: {
            connectorId: "company-webmail",
            providerLabel: "회사 웹메일",
            loginUrl: "https://mail.example.com/login",
            accountReferenceId: "os-keychain:/modycrew/company-webmail/account",
            passwordReferenceId: "os-keychain:/modycrew/company-webmail/password",
            browserSessionReferenceId: "os-keychain:/modycrew/company-webmail/session",
            twoFactorMode: "manual_once_then_session",
            cadenceMinutes: 5,
            mailboxLabel: "받은메일함",
            writingProfile: {
              toneLabel: "사용자 기존 메일 말투 우선",
              formatLabel: "짧은 업무형 답장 초안",
              calendarPreference: "연동 캘린더 충돌 확인 후 후보만 생성",
            },
          },
        });
        if (activeBridge.isAvailable) await refreshWorkspace(activeBridge);
        commitActionMessage("webmail-metadata-rehearsal", {
          text: formatWebmailMetadataRehearsalMessage(result),
          workflow: buildRepresentativeFeatureWorkflow(
            "mailops_check",
            result.status === "webmail_metadata_work_ready" ? "ready" : "blocked",
          ),
          executionReceipt: buildWebmailMetadataRehearsalReceipt(result),
          actions: [
            { label: "실전 리허설", action: "mail_live_e2e_rehearsal" },
            { label: "5분 점검 켜기", action: "secure_mail_polling_enable" },
            { label: "오피스 승인함", action: "open_office" },
            { label: "계정 보관함", action: "external_accounts" },
          ],
        });
      } finally {
        setBusy(false);
        setOperationPhase("idle");
        setOperationDetail("대화 대기");
      }
      return;
    }

    if (action === "mail_recipient_list_review") {
      await runMailRecipientListReview();
      return;
    }

    if (action === "repeat_work_enable_latest") {
      enableLatestRepeatWorkRule();
      return;
    }

    if (action === "repeat_work_save_draft") {
      saveRepeatWorkBuilderDraft();
      return;
    }

    if (action === "repeat_work_delete_confirm_latest") {
      confirmLatestRepeatWorkDeletion();
      return;
    }

    if (action === "repeat_work_builder") {
      openRepeatWorkBuilderFromEasySetup();
      return;
    }

    if (action === "secure_mail_polling_rule") {
      prepareSecureMailPollingRule();
      return;
    }

    if (action === "secure_mail_polling_enable") {
      enableSecureMailPollingRule();
      return;
    }

    if (action === "today_check") {
      await runTodayWorkCheck(activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations"));
      return;
    }

    if (action === "automation_check") {
      await runAutomationCheck(activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations"));
      return;
    }

    if (action === "tidy_check") {
      await runTidyCrewKit(
        "manual",
        activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations"),
        activeThreadIdRef.current,
        createTidyCandidateRuntimeOptions(),
      );
      return;
    }

    if (action === "tidy_dry_run") {
      await runTidyDryRun(activeTeammate ?? teammates[0] ?? createAITeammateFromTemplate("operations"));
      return;
    }

    if (action === "merge_delegation_results") {
      mergeLatestDelegationResults();
      return;
    }

    if (action === "delegation_report_draft") {
      void createDelegationFollowupDraft("report");
      return;
    }

    if (action === "daily_activity_report") {
      const reportAgent = ensureRoleTeammate("operations", "보고 담당 자동 입사");
      await generateDailyActivityReport({
        reportAgent,
        teammatesForNames: [...teammates, reportAgent],
        auto: false,
      });
      return;
    }

    if (action === "delegation_mail_draft") {
      void createDelegationFollowupDraft("mail");
      return;
    }

    if (action === "delegation_approval_request") {
      void createDelegationFollowupDraft("approval");
      return;
    }
    if (action === "delegation_writer_crewkit") {
      await startWriterCrewKitFromDelegationDraft();
      return;
    }
    if (action === "delegation_mailops") {
      await startMailOpsFromDelegationDraft();
      return;
    }

    if (action === "learn_files") {
      await attachFoldersToChat("", "", "learning");
      return;
    }

  }

