    setWorkerCompanionMode(false);
    const shouldOpenOfficeDetail = Boolean(mailOpsSession?.result);
    if (shouldOpenOfficeDetail) setMailOpsDetailsOpen(false);
    openWorkspacePanel("open_office");
    if (shouldOpenOfficeDetail) setWorkspaceWindowOpen(true);
