  function releaseSetupBridgeLabel(status: string) {
    if (status === "running") return "여는 중";
    if (status.includes("opened")) return "준비 파일 열림";
    if (status.includes("recorded")) return "검사 결과 반영";
    if (status.includes("desktop_required")) return "설치 앱 필요";
    if (status.includes("missing")) return "준비 파일 필요";
    if (status === "error") return "확인 실패";
    return "준비 전";
  }

  function releaseSetupRecheckLabel(status: string) {
    if (status === "running") return "검사 중";
    if (status.includes("recorded")) return "결과 반영됨";
    if (status.includes("desktop_required")) return "설치 앱 필요";
    if (status.includes("missing")) return "이벤트 파일 필요";
    if (status === "error") return "검사 실패";
    return "검사 전";
  }

  function releaseSetupRecheckHint(rowId: string, status: string) {
    if (status === "running") return "현재 릴리즈 readiness 산출물을 다시 읽고 있습니다.";
    if (status.includes("recorded")) {
      if (rowId === "ai_runtime_live_unblock") return "결과가 반영됐습니다. AI live 상태가 통과하면 다음 메일/캘린더 단계로 넘어갑니다.";
      if (rowId === "release_live_smoke_unblock") return "결과가 반영됐습니다. 메일/캘린더 실기가 통과하면 첫 사용자 관찰로 넘어갑니다.";
      if (rowId === "first_user_observation_unblock") return "결과가 반영됐습니다. 관찰 증거가 통과하면 최종 릴리즈 준비로 넘어갑니다.";
    }
    if (status.includes("desktop_required")) return "설치 앱에서 다시 검사를 실행해야 상태를 반영할 수 있습니다.";
    if (status.includes("missing")) return "릴리즈 readiness 이벤트 파일이 없어서 먼저 검증 산출물을 만들어야 합니다.";
    if (status === "error") return "검사 메시지를 확인하고 다시 검사 버튼을 한 번 더 눌러 주세요.";
    return "값을 넣거나 기록을 남긴 뒤 다시 검사를 누르면 이 단계 상태가 갱신됩니다.";
  }

  function releaseSetupStatusPassed(status: string) {
    const normalized = status.toLowerCase();
    const hasPassSignal = ["passed", "ready", "ok", "completed", "done", "verified"].some((token) => normalized.includes(token));
    const hasBlockSignal = ["blocked", "missing", "required", "needs", "failed", "error"].some((token) => normalized.includes(token));
    return hasPassSignal && !hasBlockSignal;
  }

  function releaseSetupStepState(stepIndex: number, rows: Array<{ status: string }>) {
    const firstBlockedIndex = rows.findIndex((candidate) => !releaseSetupStatusPassed(candidate.status));
    if (firstBlockedIndex === -1) return "done";
    if (stepIndex < firstBlockedIndex) return "done";
    if (stepIndex === firstBlockedIndex) return "current";
    return "waiting";
  }

  function releaseSetupStepResultLabel(status: string, stepState: string) {
    if (releaseSetupStatusPassed(status)) return "통과 확인됨";
    if (stepState === "current") return "막힘 확인 필요";
    if (stepState === "waiting") return "앞 단계 대기";
    return "확인 필요";
  }

