function parseOfficeQueueChatCommand(text: string): OfficeQueueChatCommand | null {
  const normalized = text.trim().toLowerCase();
  if (!normalized) return null;
  if (/최종\s*(확인|승인|실행)|실행\s*(확인|준비)|dry[-\s]?run|드라이런/u.test(normalized)) {
    return {
      kind: "final_confirmation",
      note: text.trim(),
    };
  }
  if (/^(승인|진행|확정|좋아|오케이|ok)(해|해줘|합니다|할게| 처리|$)/u.test(normalized) || /승인\s*(해|할게|합니다|처리)/u.test(normalized)) {
    return {
      kind: "artifact_decision",
      decision: "approved",
      note: "채팅에서 승인했습니다. 실제 외부 실행은 앱의 마지막 확인 전에는 진행하지 않습니다.",
    };
  }
  if (/^(수정|고쳐|다시|변경|재작업)(해|해줘|요청|으로|$)/u.test(normalized) || /(수정|재작업)\s*(요청|으로)/u.test(normalized)) {
    return {
      kind: "artifact_decision",
      decision: "change_requested",
      note: text.trim() || "채팅에서 수정 요청했습니다.",
    };
  }
  if (/^(취소|보류|대기|잠깐)(해|해줘|처리|$)/u.test(normalized) || /(취소|보류)\s*(해|처리|할게|합니다)/u.test(normalized)) {
    return {
      kind: "artifact_decision",
      decision: "held",
      note: text.trim() || "채팅에서 취소/보류 처리했습니다.",
    };
  }
  return null;
}

function findLatestPendingApprovalArtifact(
  artifacts: LocalMemoryDelegationArtifactRecord[],
): LocalMemoryDelegationArtifactRecord | null {
  return [...artifacts]
    .filter((artifact) =>
      artifact.artifactKind === "approval" &&
      !artifact.approvalDecision &&
      (artifact.approvalStatus === "pending" || !artifact.approvalStatus),
    )
    .sort((left, right) => Date.parse(right.createdAt || "") - Date.parse(left.createdAt || ""))
    [0] ?? null;
}

function findLatestFinalActionWorkItem(items: WorkItem[]): WorkItem | null {
  return [...items]
    .filter((item) => Boolean(item.finalAction))
    .sort((left, right) => Date.parse(right.receivedAt || "") - Date.parse(left.receivedAt || ""))
    [0] ?? null;
}

function finalActionDryRunStatusLabel(status: string): string {
  if (status === "final_action_dry_run_ready") return "실행 전 검토 완료, 실제 실행 잠금";
  if (status === "final_action_dry_run_needs_input") return "필수 확인값 필요, 실제 실행 잠금";
  if (status === "final_action_dry_run_blocked") return "필요 연결 없음, 실제 실행 잠금";
  if (status === "not_final_action") return "최종 실행 후보 아님";
  if (status === "desktop_required") return "설치 앱 필요";
  return status || "dry-run 상태 확인 필요";
}

function finalActionExecutionStatusLabel(status: string): string {
  if (status === "final_execution_live_adapter_required") return "고급 live 실행 승인 없음, 실제 실행 잠금";
  if (status === "final_execution_confirmation_required") return "최종 실행 조건 부족, 실제 실행 잠금";
  if (status === "final_execution_review_recorded") return "검토만 기록, 외부 실행 없음";
  if (status === "final_execution_provider_dispatched") return "provider 실행 완료";
  if (status === "not_final_action") return "최종 실행 후보 아님";
  if (status === "desktop_required") return "설치 앱 필요";
  return status || "실행 게이트 상태 확인 필요";
}

function findMailOpsPreviewWorkItem(items: WorkItem[], card: MailOpsApprovalPreviewCard): WorkItem | null {
  const finalActionItems = items.filter((item) => Boolean(item.finalAction));
  if (card.workItemId) {
    const direct = finalActionItems.find((item) => item.id === card.workItemId);
    if (direct) return direct;
  }
  const normalizedTitle = normalizeSearchText(card.title);
  const normalizedDetail = normalizeSearchText(card.detail);
  const actionKind =
    /명단|대량|bulk|recipient list/u.test(`${card.badge} ${card.title} ${card.detail}`)
      ? "send_bulk_email"
      : /일정|calendar|캘린더/u.test(`${card.badge} ${card.title} ${card.detail}`)
      ? "create_calendar_event"
      : /답장|메일|email|mail/u.test(`${card.badge} ${card.title} ${card.detail}`)
        ? "send_email"
        : "";
  return (
    finalActionItems.find((item) => actionKind && item.finalAction?.kind === actionKind) ??
    finalActionItems.find((item) => {
      const haystack = normalizeSearchText(`${item.title} ${item.summary} ${item.sourceLabel} ${item.finalAction?.label ?? ""}`);
      return Boolean(
        (normalizedTitle && haystack.includes(normalizedTitle)) ||
        (normalizedDetail && haystack.includes(normalizedDetail)) ||
        (normalizedTitle && normalizedTitle.includes(haystack.slice(0, 24))),
      );
    }) ??
    findLatestFinalActionWorkItem(finalActionItems)
  );
}

function normalizeSearchText(value: string) {
  return value.replace(/\s+/g, " ").trim().toLowerCase();
}

