function normalizeWorkerCompanionAvatarMode(value: unknown): WorkerCompanionAvatarMode {
  return value === "custom" || value === "base" ? value : defaultWorkerCompanionPreferences.avatarMode;
}

function normalizeWorkerCompanionPreferences(value: unknown): WorkerCompanionPreferences {
  const record = value && typeof value === "object" ? (value as Partial<Record<keyof WorkerCompanionPreferences, unknown>>) : {};
  return {
    sizePreset: normalizeWorkerCompanionSizePreset(record.sizePreset),
    positionPreset: normalizeWorkerCompanionPositionPreset(record.positionPreset),
    motionStyle: normalizeWorkerCompanionMotionStyle(record.motionStyle),
    avatarMode: normalizeWorkerCompanionAvatarMode(record.avatarMode),
  };
}

