function getWorkspacePanelLayoutHint(panel: WorkspacePanel, view: WorkspacePanelView) {
  if (view === "focus") {
    if (panel === "learn") return "자료 선택에 필요한 버튼만 먼저 보입니다.";
    if (panel === "connect") return "연결할 항목과 안전 확인만 먼저 보입니다.";
    if (panel === "messengers") return "승인 채널에서 지금 쓸 것만 먼저 보입니다.";
    if (panel === "skills") return "추천 도구와 켜기 버튼만 먼저 보입니다.";
    if (panel === "office") return "오늘 처리할 일과 다음 버튼만 먼저 보입니다.";
    if (panel === "workers") return "현재 담당자와 바로 실행할 버튼만 먼저 보입니다.";
    return "지금 필요한 정보만 먼저 보입니다.";
  }
  if (view === "setup") {
    if (panel === "learn") return "폴더, 파일, 출처 관리는 이 탭에 모았습니다.";
    if (panel === "connect") return "계정, 보관함, 권한 설정은 이 탭에 모았습니다.";
    if (panel === "messengers") return "메신저 채널 선택과 연결 설정은 이 탭에 모았습니다.";
    if (panel === "skills") return "도구를 켜고 끄는 구성은 이 탭에 모았습니다.";
    if (panel === "office") return "승인함과 결정 흐름 설정은 이 탭에 모았습니다.";
    if (panel === "workers") return "크루 추가와 역할 구성은 이 탭에 모았습니다.";
    return "설정과 범위 조정은 이 탭에 모았습니다.";
  }
  if (panel === "learn") return "저장된 출처와 분석 근거는 기록 탭에서만 펼칩니다.";
  if (panel === "connect") return "막혔던 연결과 복구 근거는 기록 탭에서만 펼칩니다.";
  if (panel === "messengers") return "채널 점검과 연결 이력은 기록 탭에서만 펼칩니다.";
  if (panel === "skills") return "저장한 업무 방식과 사용 흔적은 기록 탭에서만 펼칩니다.";
  if (panel === "office") return "실행 로그와 승인 영수증은 기록 탭에서만 펼칩니다.";
  if (panel === "workers") return "크루의 업무 방식과 이력은 기록 탭에서만 펼칩니다.";
  return "근거와 로그는 기록 탭에서만 펼칩니다.";
}

