function userFacingSkillSourceKindLabel(kind: string | null | undefined) {
  const normalized = (kind ?? "").toLowerCase();
  if (/bundled|built.?in|default/u.test(normalized)) return "앱 기본 기능";
  if (/local|memory|folder|profile/u.test(normalized)) return "내 PC 기억";
  if (/connector|oauth|account|mail|calendar/u.test(normalized)) return "연결 계정";
  if (/external|tool/u.test(normalized)) return "외부 계정 확인";
  if (/growth|skill|bridge|custom/u.test(normalized)) return "저장한 업무 방식";
  return "업무 도구";
}

function userFacingToolHintLabel(hint: string | null | undefined) {
  const value = hint ?? "";
  const normalized = value.toLowerCase();
  if (/spreadsheet|sheet|excel|xlsx|표|정산/u.test(normalized)) return "표/정산 자료";
  if (/presentation|powerpoint|ppt|slide|deck|canva|figma|발표/u.test(normalized)) return "발표자료";
  if (/document|word|docx|hwp|pdf|문서/u.test(normalized)) return "문서 자료";
  if (/data analytics|analytics|analysis|리포트|분석/u.test(normalized)) return "데이터 분석";
  if (/public equity|investment|invest|finance|주식|투자/u.test(normalized)) return "투자 리서치";
  if (/remotion|video|render|node|영상|렌더/u.test(normalized)) return "영상 제작 확인";
  if (/codex|git|python|cli|terminal|repo|개발/u.test(normalized)) return "작업 준비 확인";
  if (/computer|desktop|browser|folder|file|pc/u.test(normalized)) return "내 PC 작업";
  if (/drive|notion|slack|gmail|calendar|mail/u.test(normalized)) return "업무 계정 연결";
  return userFacingCapabilityDetail(value, "외부 계정 확인");
}

