function skillPriorityForTeam(team: AITeammateTeam, skill: AISkillPack) {
  let score = skill.recommendedTeam === team ? 4 : skill.recommendedTeam === "personal" ? 1 : 0;
  if (team === "mail" && skill.id === "mail_calendar_operator") score += 4;
  if (team === "desktop" && (skill.id === "folder_organizer" || skill.id === "computer_use_operator")) score += 4;
  if (team === "operations" && (skill.id === "connector_discovery" || skill.id === "work_pattern_learning")) score += 2;
  if (team === "marketing" && (skill.id === "presentation_deck" || skill.id === "remotion_video")) score += 3;
  if (team === "development" && skill.id === "codex_cli_workbench") score += 3;
  if (team === "finance" && (skill.id === "document_writer" || skill.id === "workspace_knowledge")) score += 2;
  if (team === "legal" && (skill.id === "document_writer" || skill.id === "approval_guard")) score += 2;
  if (team === "custom" && (skill.id === "portable_memory" || skill.id === "workspace_knowledge" || skill.id === "codex_cli_workbench")) score += 2;
  if (skill.connectorIds?.length) score += 0.5;
  return score;
}

