function getBaseCrewReadiness(teammates: AITeammate[]) {
  const channels = baseCrewTeams.map((team) => {
    const template = aiTeammateTemplates.find((item) => item.id === team) ?? aiTeammateTemplates[1];
    const teammate = teammates.find((item) => item.templateId === team);
    return { team, template, teammate };
  });
  const missingTeams = channels.filter((channel) => !channel.teammate).map((channel) => channel.team);
  return {
    channels,
    missingTeams,
    installedCount: channels.length - missingTeams.length,
    ready: missingTeams.length === 0,
  };
}

function isMailOpsRequest(text: string) {
  if (isMailOpsInformationQuestion(text)) return false;
  const compact = text.replace(/\s+/gu, " ").trim();
  const excludesMail =
    /(?:메일|이메일|메일함|문의)(?:\s*(?:확인|작업|처리))?\s*(?:은|는|부터|쪽은)?\s*(?:일단\s*)?(?:패스|제외|빼|말고|하지\s*마|안\s*(?:해|할|봐)|나중|보류)/u.test(compact);
  const hasMailTarget = /메일|이메일|메일함|문의|imap|smtp|gmail|outlook|회사\s*메일/u.test(compact);
  const hasMailAction =
    /(?:메일|이메일|메일함|문의).{0,36}(?:읽|확인|점검|분류|검색|찾|요약|정리|답장|회신|초안|작성|보내|발송|처리|자동화)|(?:읽|확인|점검|분류|검색|찾|요약|정리|답장|회신|초안|작성|보내|발송|처리|자동화).{0,36}(?:메일|이메일|메일함|문의)/u.test(compact);
  return !excludesMail && hasMailTarget && hasMailAction;
}
function parseMailOpsCandidateRequest(text: string): MailOpsCandidateState | null {
  const raw = text.trim();
  if (!raw || isMailOpsInformationQuestion(raw)) return null;
  const hasBulkSignal = hasBulkMailDraftSignal(raw);
  const hasMailSignal = hasBulkSignal || /메일|이메일|답장|문의|예약|일정|캘린더|gmail|outlook|회사\s*메일/u.test(raw);
  const hasActionSignal = hasBulkSignal || /읽|확인|점검|정리|초안|후보|분류|요약|준비|찾|알려|보내|발송|해줘|해주세요/u.test(raw);
  if (!hasMailSignal || !hasActionSignal) return null;

  return {
    accountScope: inferMailOpsAccountScope(raw),
    checkScope: inferMailOpsCheckScope(raw),
    output: inferMailOpsOutput(raw),
    approval: inferMailOpsApproval(raw),
    ...(hasUserComposedMailSignal(raw) ? inferUserComposedMailCheckPlan(raw) : {}),
    ...(hasBulkSignal ? inferBulkMailCandidatePlan(raw) : {}),
  };
}

function inferMailOpsAccountScope(text: string) {
  if (/gmail|지메일/u.test(text)) return "Gmail";
  if (/outlook|아웃룩/u.test(text)) return "Outlook";
  if (/회사\s*메일|업무\s*메일/u.test(text)) return "회사 메일";
  return "연결된 메일 전체";
}

function inferMailOpsCheckScope(text: string) {
  if (hasBulkMailDraftSignal(text)) return "발송 대상, 제외 대상, 중복 주소, 수신거부";
  if (/문의|고객|상담/u.test(text)) return "문의/고객 메일";
  if (/예약|일정|미팅|캘린더/u.test(text)) return "일정 관련 메일";
  if (/오늘|금일/u.test(text)) return "오늘 받은 메일";
  if (/읽지\s*않|안\s*읽/u.test(text)) return "읽지 않은 메일";
  if (/중요|급한|긴급/u.test(text)) return "중요 메일";
  return "읽지 않은 메일과 오늘 받은 메일";
}

function inferMailOpsOutput(text: string) {
  if (hasBulkMailDraftSignal(text)) return "대상 그룹, 제외 규칙, 샘플 문안";
  if (/일정|캘린더|예약|미팅/u.test(text) && !/답장|초안/u.test(text)) return "일정 후보";
  if (/답장|초안/u.test(text) && !/일정|캘린더|예약/u.test(text)) return "답장 초안";
  if (/요약|정리|승인함/u.test(text) && !/답장|일정|캘린더/u.test(text)) return "승인함 요약";
  return "답장 초안과 일정 후보";
}

function inferMailOpsApproval(text: string) {
  if (hasBulkMailDraftSignal(text)) return "전체 명단과 샘플 문안 확인 후 최종 승인";
  if (/미리보기|먼저\s*보기|초안만/u.test(text)) return "먼저 미리보기만";
  if (/일정|캘린더|예약/u.test(text) && !/답장|발송|보내/u.test(text)) return "일정 등록 전 승인";
  if (/답장|발송|보내/u.test(text) && !/일정|캘린더/u.test(text)) return "발송 전 승인";
  return "발송/일정 등록 전 항상 승인";
}

function formatMailOpsCandidateGoal(candidate: MailOpsCandidateState) {
  const bulkPlan = createBulkMailDraftPlan(candidate);
  const composedPlan = createUserComposedMailCheckPlan(candidate);
  const bulkDetail = bulkPlan
    ? ` 대량 발송 계획: 제목 '${bulkPlan.subject}', 대상 '${bulkPlan.targetGroups}', 제외 '${bulkPlan.exclusionRules}', 개인화 '${bulkPlan.personalizationFields}', 샘플 '${bulkPlan.sampleReview}'. 본문 초안은 승인 전 샘플로만 사용.`
    : "";
  const composedDetail = composedPlan.hasDraft
    ? ` 직접 작성 메일 점검: 받는 사람 '${composedPlan.to}', 제목 '${composedPlan.subject}', 첨부 '${composedPlan.attachments}', 점검 기준 '${composedPlan.checkFocus}'. 본문은 문장/위험 표현/누락만 확인하고 최종 승인 전 발송 금지.`
    : "";
  return `${candidate.accountScope}에서 ${candidate.checkScope}을 읽고 ${candidate.output}를 만들기. 승인 기준: ${candidate.approval}.${bulkDetail}${composedDetail}`;
}

