function buildMailOpsWorkbenchCards(result: MailWorkIntakeResult): MailOpsWorkbenchCard[] {
  if (!hasMailOpsWorkbenchInput(result)) return [];
  const stats = result.workAnalysis?.stats;
  const previews = result.approvalPreviews ?? [];
  const approvalCards = buildMailOpsApprovalPreviewCards(result);
  const replyPreviewCount = previews.filter((preview) =>
    /send_email|draft_reply|reply/u.test(`${preview.kind ?? ""} ${preview.title ?? ""}`),
  ).length;
  const replyCount = stats?.replyCandidates ?? replyPreviewCount;
  const ignoredCount = result.ignoredItemsCount ?? stats?.ignoredItems ?? 0;
  const reviewCount =
    result.reviewItemsCount ?? stats?.reviewItems ?? approvalCards.filter((card) => card.state === "review").length;
  const approvalCount = result.approvalQueueCount ?? stats?.approvalCandidates ?? approvalCards.length;
  const calendarCount =
    stats?.calendarCandidates ??
    result.calendarBusyWindowCount ??
    approvalCards.filter((card) => /calendar|일정|회의|미팅/u.test(`${card.previewType ?? ""} ${card.title} ${card.detail}`)).length;
  const attachmentCount = Math.max(
    result.attachmentOrganizerPlan?.attachmentCandidateCount ??
      result.attachmentOrganizerPlan?.candidateSummaries?.length ??
      stats?.attachmentSignals ??
      0,
    approvalCards.filter((card) => /attachment|첨부|파일|folder_plan/u.test(`${card.previewType ?? ""} ${card.title} ${card.detail}`)).length,
  );
  const mobileReviewHandoffSignals = (stats as { mobileReviewHandoffSignals?: number } | undefined)?.mobileReviewHandoffSignals ?? 0;
  const mobileHandoffCount = Math.max(
    mobileReviewHandoffSignals,
    previews.filter((preview) =>
      (preview.mobileReceiveFilterIds?.length ?? 0) > 0 ||
      (preview.mobileReceiveFilterLabels?.length ?? 0) > 0 ||
      /mobile_review_handoff|모바일|휴대폰|승인\s*대기|긴급|요약\s*전달/u.test(
        `${preview.kind ?? ""} ${preview.title ?? ""} ${preview.sourceLabel ?? ""}`,
      ),
    ).length,
  );
  const userComposedCount = approvalCards.filter((card) =>
    /user_composed|작성\s*메일|직접\s*작성/u.test(`${card.previewType ?? ""} ${card.title} ${card.detail}`),
  ).length;
  const hasReplyDraft =
    replyCount > 0 ||
    approvalCards.some((card) => /reply|send_email|draft/u.test(`${card.previewType ?? ""} ${card.title}`));

  return [
    {
      id: "reply-needed",
      label: "답장 보낼 메일",
      title: hasReplyDraft ? "초안 보기 -> 수정 -> 승인하면 발송" : "답장 후보 없음",
      detail: hasReplyDraft
        ? "AI가 답장이 필요한 메일을 먼저 골라 초안을 만들고, 사용자는 문구를 고친 뒤 승인만 하면 됩니다."
        : "이번 점검에서는 바로 답장할 메일을 찾지 못했습니다. 연결 또는 범위를 바꾸면 다시 분류합니다.",
      countLabel: `${replyCount}건`,
      status: hasReplyDraft ? "active" : "empty",
      proofLabel: "답장 후보와 승인 카드 기반",
    },
    {
      id: "review-needed",
      label: "확인 필요",
      title: reviewCount > 0 ? "사람 판단이 필요한 메일은 멈춤" : "추가 확인 없음",
      detail:
        reviewCount > 0
          ? "근거가 부족하거나 금액, 계약, 민감정보가 걸린 메일은 자동 답장하지 않고 질문/보류 후보로 둡니다."
          : "검토 대기 항목이 없더라도 발송, 등록, 공유는 승인 전까지 잠겨 있습니다.",
      countLabel: `${reviewCount}건`,
      status: reviewCount > 0 ? "review" : "empty",
      proofLabel: "reviewItems 분류 기반",
    },
    {
      id: "no-reply",
      label: "답장 안 보낼 메일",
      title: ignoredCount > 0 ? "알림/참조/잡음은 발송 후보에서 제외" : "제외 후보 없음",
      detail:
        ignoredCount > 0
          ? "광고, 단순 알림, 참조성 메일은 답장 후보에서 빼고 사용자가 필요하면 다시 후보로 올릴 수 있습니다."
          : "이번 결과에는 자동 제외할 메일이 없습니다. 제외 기준은 이후 승인/보류 선택으로 배웁니다.",
      countLabel: `${ignoredCount}건`,
      status: ignoredCount > 0 ? "ready" : "empty",
      proofLabel: "ignoredItems 분류 기반",
    },
    {
      id: "calendar-candidate",
      label: "일정 후보",
      title: calendarCount > 0 ? "회의/예약 메일은 시간 후보로 분리" : "일정 후보 없음",
      detail:
        calendarCount > 0
          ? "메일 안의 일정 조율, 회의, 예약 요청은 답장 초안과 분리하고 캘린더 등록 전 마지막 확인으로 보냅니다."
          : "일정 후보가 없으면 캘린더 등록 카드는 만들지 않습니다. 일정 신호가 생기면 별도 후보로 분리합니다.",
      countLabel: `${calendarCount}건`,
      status: calendarCount > 0 ? "ready" : "empty",
      proofLabel: "calendarCandidates 분류 기반",
    },
    {
      id: "attachment-candidate",
      label: "첨부 정리",
      title: attachmentCount > 0 ? "중요 첨부는 정리 후보로 분리" : "첨부 정리 후보 없음",
      detail:
        attachmentCount > 0
          ? "계약서, 세금계산서, 견적서 같은 첨부는 로컬 사본 검토 뒤 폴더 정리 승인 카드로 넘깁니다."
          : "첨부 신호가 없으면 다운로드나 폴더 이동 후보를 만들지 않습니다.",
      countLabel: `${attachmentCount}건`,
      status: attachmentCount > 0 ? "ready" : "empty",
      proofLabel: "attachmentOrganizerPlan 기반 · 다운로드/이동 전 승인 잠금",
    },
    {
      id: "mobile-handoff",
      label: "휴대폰에서 볼 메일",
      title: mobileHandoffCount > 0 ? "휴대폰 확인 후보를 한 줄로 전달" : "휴대폰 후보 대기",
      detail:
        mobileHandoffCount > 0
          ? "긴급, 승인 대기, 요약 전달 후보만 휴대폰으로 보내고 실제 발송은 앱 마지막 확인 전까지 잠급니다."
          : "휴대폰 공유/PWA로 선택한 메일이 들어오면 이 작업함에 같은 방식으로 정리합니다.",
      countLabel: `${mobileHandoffCount}건`,
      status: mobileHandoffCount > 0 ? "ready" : "empty",
      proofLabel: "mobile_review_handoff 기반",
    },
    {
      id: "user-composed-check",
      label: "내가 쓴 메일 점검",
      title: "직접 쓴 메일도 보내기 전에 점검",
      detail: "사용자가 작성하거나 붙여넣은 메일은 수신자, 첨부, 금지 표현, 말투를 확인하고 수정 후 승인하면 발송합니다.",
      countLabel: userComposedCount > 0 ? `${userComposedCount}건` : "작성 전",
      status: userComposedCount > 0 ? "ready" : "empty",
      proofLabel: "사용자 응답 대기 · 발송 없음",
    },
    {
      id: "approval-send",
      label: "수정 후 승인 발송",
      title: approvalCount > 0 ? "승인 대기에서 최종 확인" : "승인 후보 대기",
      detail: "여러 메일 초안을 한 화면에서 고치고, 승인한 항목만 마지막 확인 뒤 발송 또는 일정 등록으로 넘어갑니다.",
      countLabel: `${approvalCount}건`,
      status: approvalCount > 0 ? "locked" : "empty",
      proofLabel: "approve_before_send_external_mutation_false",
    },
  ];
}

function buildMailOpsWorkbenchQuickRows(cards: MailOpsWorkbenchCard[] | undefined): MailOpsWorkbenchQuickRow[] {
  const actionLabels: Record<string, string> = {
    "reply-needed": "초안 수정",
    "review-needed": "근거 확인",
    "no-reply": "제외 유지",
    "calendar-candidate": "일정 확인",
    "attachment-candidate": "첨부 확인",
    "mobile-handoff": "휴대폰 확인",
    "user-composed-check": "보내기 전 점검",
    "approval-send": "승인 발송",
  };
  return (cards ?? []).map((card) => ({
    id: card.id,
    label: card.label,
    countLabel: card.countLabel,
    nextActionLabel: actionLabels[card.id] ?? "상세 보기",
    detail: card.detail,
    proofLabel: card.proofLabel,
    status: card.status,
  }));
}

