function hasMailOpsWorkbenchInput(result: MailWorkIntakeResult | null | undefined) {
  if (!result || isMailConnectorMissingStatus(result.status)) return false;
  const stats = result.workAnalysis?.stats;
  return (
    Boolean(result.review) ||
    (result.messageCount ?? stats?.totalMessages ?? 0) > 0 ||
    (result.createdWorkItemsCount ?? stats?.workItems ?? 0) > 0 ||
    (result.approvalPreviews?.length ?? 0) > 0 ||
    (result.approvalQueueCount ?? stats?.approvalCandidates ?? 0) > 0
  );
}

function buildMailOpsWorkbenchInputEvidence(result: MailWorkIntakeResult | null | undefined): MailOpsWorkbenchInputEvidence {
  const stats = result?.workAnalysis?.stats;
  const missing = Boolean(result && isMailConnectorMissingStatus(result.status));
  const readCount = result?.review?.rowCount ?? result?.messageCount ?? stats?.totalMessages ?? 0;
  const approvalPreviewCount = result?.approvalPreviews?.length ?? result?.approvalQueueCount ?? stats?.approvalCandidates ?? 0;
  const replyCandidateCount = stats?.replyCandidates ?? Math.max(0, approvalPreviewCount);
  const reviewCount = result?.reviewItemsCount ?? stats?.reviewItems ?? result?.review?.personalizationReviewCount ?? 0;
  const ignoredCount = result?.ignoredItemsCount ?? stats?.ignoredItems ?? result?.review?.excludedCount ?? 0;
  return {
    status: result && !missing && hasMailOpsWorkbenchInput(result) ? "ready" : "blocked",
    sourceLabel: result?.review
      ? "명단/대량 메일 검토 결과"
      : result?.connectorId || result?.providerId
        ? `읽기 전용 메일 결과 · ${result.connectorId || result.providerId}`
        : missing
          ? "메일 연결 필요"
          : "메일 읽기 결과 대기",
    inputCountLabel: result?.review ? "검토 행" : "읽은 메일",
    readCount,
    approvalPreviewCount,
    replyCandidateCount,
    reviewCount,
    ignoredCount,
    proofLabel: result?.review
      ? "recipient_list_review_to_workbench_rows"
      : result && !missing
        ? "connected_mail_read_to_workbench_rows"
        : "connection_required_no_fake_workbench",
    boundaryLabel: "읽기/초안/분류만 수행 · 최종 확인 전 외부 발송 0건",
  };
}

function normalizeMailOpsDecisionReasonChips(chips?: MailOpsDecisionReasonChipInput[]): MailOpsDecisionReasonChip[] | undefined {
  const states = new Set(["ready", "review", "excluded", "locked"]);
  const normalized = (chips ?? [])
    .map((chip, index) => {
      const id = (chip.id || `reason_${index + 1}`).trim();
      const label = (chip.label || "근거").trim();
      const value = (chip.value || chip.detail || "확인 필요").trim();
      const detail = (chip.detail || chip.value || "메일 인테이크 결과에서 만든 검토 근거입니다.").trim();
      const state = states.has(chip.state || "") ? (chip.state as MailOpsDecisionReasonChip["state"]) : "review";
      return { id, label, value, detail, state };
    })
    .filter((chip) => chip.id && chip.label && chip.value && chip.detail)
    .slice(0, 4);
  return normalized.length ? normalized : undefined;
}

function buildMailOpsRecipientLearningSignals(review?: MailWorkIntakeResult["review"] | null) {
  if (!review) {
    return {
      decisionSummary: "",
      decisionBadges: [] as string[],
      nextLearningAction: "",
    };
  }
  const override = review.userDecisionOverride;
  const effectiveCount = override?.effectiveRecipientCount ?? review.validRecipientCount ?? review.dryRunSummary?.wouldSendCount;
  const learnedDefaultDecisionSummary = review.learnedDefaultDecisionSummary;
  const learnedDefaultDecisionMatrix = review.learnedDefaultDecisionMatrix;
  const decisionBadges = [
    override?.patchSummary ? `이번 수정 ${override.patchSummary}` : "",
    override?.includeLabels?.length ? `포함 ${override.includeLabels.slice(0, 2).join(", ")}` : "",
    override?.excludeLabels?.length ? `제외 ${override.excludeLabels.slice(0, 2).join(", ")}` : "",
    override?.holdLabels?.length ? `보류 ${override.holdLabels.slice(0, 2).join(", ")}` : "",
    override?.source === "learned_suggestion" ? "학습 추천 적용" : "",
    learnedDefaultDecisionSummary ? "학습 기본 추천" : "",
    review.learnedOverrideSuggestionSummary ? "학습 추천 있음" : "",
    learnedDefaultDecisionMatrix?.send?.[0] && !review.learnedOverrideSuggestionSummary
      ? compactInlineText(learnedDefaultDecisionMatrix.send[0], 80)
      : "",
    review.learningDecisionHints?.[0] ? compactInlineText(review.learningDecisionHints[0], 80) : "",
  ].filter(Boolean);
  const decisionSummary = override?.summary
    ? `수정 반영: ${override.summary} · 최종 후보 ${effectiveCount ?? 0}건`
    : learnedDefaultDecisionSummary
      ? learnedDefaultDecisionSummary
    : review.learnedOverrideSuggestionSummary
      ? `학습 추천 대기: ${review.learnedOverrideSuggestionSummary}`
      : review.recipientDecisionSummary || "";
  const nextLearningAction = override?.sourceSummary
    ? `수정 출처: ${override.sourceSummary}`
    : learnedDefaultDecisionSummary
      ? "학습 기본 추천을 명단 검토표에 먼저 제시하고, 최종 발송은 사용자 확인 뒤에만 실행"
    : review.learnedOverrideSuggestionSummary
      ? `다음 요청에 "${review.learnedOverrideSuggestionSummary}" 기준을 제안`
      : review.nextReviewFocus || "";
  return {
    decisionSummary: compactInlineText(decisionSummary, 180),
    decisionBadges: decisionBadges.map((label) => compactInlineText(label, 90)).slice(0, 8),
    nextLearningAction: compactInlineText(nextLearningAction, 160),
  };
}

function buildMailOpsWorkCaseStatusBoard(result: MailWorkIntakeResult | null): MailOpsWorkCaseStatusCard[] {
  const analysis = result?.workAnalysis;
  const stats = analysis?.stats;
  const recipientLearningSignals = buildMailOpsRecipientLearningSignals(result?.review ?? null);
  const scenarioById = new Map((analysis?.scenarioCoverage ?? []).map((scenario) => [scenario.id, scenario]));
  const defaultChoiceById = new Map(defaultMailOpsScenarioChoices.map((choice) => [choice.id, choice]));
  const countByCase = new Map<string, number>([
    ["read_only_intake", result?.messageCount ?? stats?.totalMessages ?? 0],
    ["reply_draft", stats?.replyCandidates ?? 0],
    ["calendar_coordination", stats?.calendarCandidates ?? result?.calendarBusyWindowCount ?? 0],
    ["recipient_selection", stats?.recipientDecisionSignals ?? result?.review?.validRecipientCount ?? 0],
    ["bulk_mail", stats?.bulkMailSignals ?? (result?.review ? result.review.validRecipientCount : 0)],
    ["follow_up_tracking", stats?.followUpSignals ?? 0],
    ["attachment_followup", stats?.recipientSourceSignals ?? stats?.attachmentSignals ?? 0],
    [
      "high_risk_approval",
      (stats?.invoicePaymentSignals ?? 0) +
        (stats?.contractLegalSignals ?? 0) +
        (stats?.publicTaxSignals ?? 0) +
        (stats?.complaintEscalationSignals ?? 0),
    ],
    ["work_memory_learning", result?.learningStatus ? result.workPatternCount ?? 0 : 0],
  ]);
  const caseIds = [
    "read_only_intake",
    "reply_draft",
    "calendar_coordination",
    "recipient_selection",
    "bulk_mail",
    "follow_up_tracking",
    "attachment_followup",
    "high_risk_approval",
    "work_memory_learning",
  ];

  return caseIds.map((id) => {
    const scenario = scenarioById.get(id);
    const choice = defaultChoiceById.get(id);
    const evidenceCount = scenario?.evidenceCount ?? countByCase.get(id) ?? 0;
    const observed = scenario?.status === "observed" || evidenceCount > 0;
    const approvalCount = result?.approvalQueueCount ?? stats?.approvalCandidates ?? 0;
    const needsReview =
      id === "recipient_selection" || id === "bulk_mail" || id === "attachment_followup" || id === "high_risk_approval";
    const tone: MailOpsWorkCaseStatusCard["tone"] = observed
      ? needsReview || approvalCount > 0
        ? "approval"
        : "ready"
      : needsReview
        ? "review"
        : "locked";
      const statusLabel = observed
      ? evidenceCount > 0
        ? `${evidenceCount}건 관측`
        : "처리됨"
      : id === "work_memory_learning" && !result?.learningStatus
        ? "학습 대기"
        : "필요 시 열림";
    const recipientDecisionCase =
      Boolean(result?.review) && (id === "recipient_selection" || id === "bulk_mail" || id === "work_memory_learning");
    const decisionSummary = recipientDecisionCase ? recipientLearningSignals.decisionSummary : "";
    const decisionBadges = recipientDecisionCase ? recipientLearningSignals.decisionBadges : [];
    const nextLearningAction = recipientDecisionCase ? recipientLearningSignals.nextLearningAction : "";

    return {
      id,
      label: scenario?.label ?? choice?.label ?? (id === "work_memory_learning" ? "업무 방식 학습" : "메일 업무"),
      badge: id === "work_memory_learning" ? "학습" : mailOpsScenarioBadge(id, scenario?.label ?? choice?.label ?? "메일"),
      statusLabel,
      tone,
      detail:
        scenario?.guidance ||
        choice?.detail ||
        (id === "work_memory_learning"
          ? "실행하기, 고쳐달라고 하기, 보류하기 결과를 다음 메일 처리 기준으로 남깁니다."
          : "필요한 메일 업무만 열고 후보로 정리합니다."),
      process: scenario?.nextAction || choice?.nextAction || "업무 후보를 만들고 오피스 승인함에서 확인",
      connectionNeed:
        id === "work_memory_learning"
          ? "승인/수정 결과 기록"
          : scenario
            ? mailOpsScenarioConnectionNeed(id)
            : choice?.connectionNeed ?? "업무를 고른 뒤 필요한 연결만 확인",
      approvalPath:
        id === "work_memory_learning"
          ? "사용자가 승인하거나 수정한 결과만 다음 기준으로 반영"
          : scenario
            ? mailOpsScenarioApprovalPath(id)
            : choice?.approvalPath ?? "외부 실행 전 오피스 마지막 확인",
      learningMemory:
        id === "work_memory_learning"
          ? result?.learningStatus
            ? `저장한 방식 ${result.workPatternCount ?? 0}건`
            : "승인/수정 결과가 생기면 저장"
          : scenario?.learningValue || choice?.learningMemory || mailOpsScenarioLearningMemory(id),
      evidenceLabel: observed ? `${evidenceCount}건 근거` : "아직 실행 안 함",
      ...(decisionSummary ? { decisionSummary } : {}),
      ...(decisionBadges.length ? { decisionBadges } : {}),
      ...(nextLearningAction ? { nextLearningAction } : {}),
    };
  });
}

function formatBulkSendPlanInsightItems(plan?: NonNullable<MailWorkIntakeResult["workAnalysis"]>["bulkSendPlan"]): string[] {
  if (!plan || plan.status !== "review_required") return [];
  return [
    plan.targetGroups?.length ? `대상 그룹: ${plan.targetGroups.slice(0, 3).join(", ")}` : "",
    plan.excludedGroups?.length ? `제외 확인: ${plan.excludedGroups.slice(0, 3).join(", ")}` : "",
    plan.personalizationFields?.length ? `개인화: ${plan.personalizationFields.slice(0, 3).join(", ")}` : "",
    plan.approvalGate ?? "",
  ].filter(Boolean);
}

function formatFollowUpPlanInsightItems(plan?: NonNullable<MailWorkIntakeResult["workAnalysis"]>["followUpPlan"]): string[] {
  if (!plan || plan.status !== "review_required") return [];
  return [
    plan.waitingSignals?.length ? `신호: ${plan.waitingSignals.slice(0, 3).join(", ")}` : "",
    plan.nextCheckLabel ? `다음 확인: ${plan.nextCheckLabel}` : "",
    plan.suggestedCadence?.length ? `주기: ${plan.suggestedCadence.slice(0, 2).join(" / ")}` : "",
    plan.approvalGate ?? "",
  ].filter(Boolean);
}

function formatRecipientSourcePlanInsightItems(plan?: NonNullable<MailWorkIntakeResult["workAnalysis"]>["recipientSourcePlan"]): string[] {
  if (!plan || plan.status !== "review_required") return [];
  return [
    plan.sourceTypes?.length ? `원천: ${plan.sourceTypes.slice(0, 3).join(", ")}` : "",
    plan.fileReviewChecklist?.length ? `검토: ${plan.fileReviewChecklist.slice(0, 2).join(" / ")}` : "",
    plan.matchingRules?.length ? `규칙: ${plan.matchingRules.slice(0, 2).join(" / ")}` : "",
    plan.approvalGate ?? "",
  ].filter(Boolean);
}

function formatRecipientCopyPlanInsightItems(plan?: NonNullable<MailWorkIntakeResult["workAnalysis"]>["recipientCopyPlan"]): string[] {
  if (!plan || plan.status !== "review_required") return [];
  return [
    plan.sendTargetRules?.length ? `받는 사람: ${plan.sendTargetRules.slice(0, 2).join(" / ")}` : "",
    plan.ccReviewRules?.length ? `참조: ${plan.ccReviewRules.slice(0, 2).join(" / ")}` : "",
    plan.bccReviewRules?.length ? `숨은참조: ${plan.bccReviewRules.slice(0, 2).join(" / ")}` : "",
    plan.holdReviewRules?.length ? `보류: ${plan.holdReviewRules.slice(0, 2).join(" / ")}` : "",
    plan.approvalGate ?? "",
  ].filter(Boolean);
}

function formatConnectionReadinessPlanInsightItems(
  plan?: NonNullable<MailWorkIntakeResult["workAnalysis"]>["connectionReadinessPlan"],
): string[] {
  if (!plan || plan.status !== "review_required") return [];
  return [
    plan.workCaseLabels?.length ? `업무: ${plan.workCaseLabels.slice(0, 3).join(", ")}` : "",
    plan.providerOptions?.length ? `메일 종류: ${plan.providerOptions.slice(0, 2).join(" / ")}` : "",
    plan.vaultInputs?.length ? `보관함 입력: ${plan.vaultInputs.slice(0, 3).join(", ")}` : "",
    plan.twoFactorChecklist?.length ? `2차 인증: ${plan.twoFactorChecklist.slice(0, 3).join(" / ")}` : "",
    plan.permissionBoundaries?.length ? `권한 경계: ${plan.permissionBoundaries.slice(0, 3).join(" / ")}` : "",
    plan.approvalGate ?? "",
  ].filter(Boolean);
}

