function buildMailOpsTemplateLibrary(choices: MailOpsScenarioChoice[]): MailOpsTemplateCard[] {
  const priority = [
    "read_only_intake",
    "customer_inquiry",
    "reply_draft",
    "calendar_coordination",
    "bulk_mail",
    "recipient_selection",
    "follow_up_tracking",
    "mail_info_digest",
    "mobile_review_handoff",
    "quote_proposal",
    "invoice_payment",
    "vendor_procurement",
    "document_submission",
    "high_risk_approval",
    "contract_legal",
    "public_tax",
    "complaint_escalation",
    "reservation_order",
    "compliance_unsubscribe",
    "security_account_alert",
    "internal_collaboration",
  ];
  const byId = new Map(choices.map((choice) => [choice.id, choice]));
  return priority
    .map((id) => byId.get(id) ?? defaultMailOpsScenarioChoices.find((choice) => choice.id === id))
    .filter((choice): choice is MailOpsScenarioChoice => Boolean(choice))
    .map((choice) => ({
      id: `template-${choice.id}`,
      scenarioId: choice.id,
      label: choice.label,
      badge: choice.badge,
      appliesTo: mailOpsTemplateAppliesTo(choice.id),
      preparedOutput: mailOpsScenarioPreparedOutput(choice.id),
      settings: mailOpsTemplateSettings(choice.id),
      skillFlow: mailOpsTemplateSkillFlow(choice.id),
      safetyGate: choice.safetyGate,
      primaryAction: choice.primaryAction,
      primaryLabel: choice.primaryLabel,
    }));
}

function buildMailOpsSkillMap(choice: MailOpsScenarioChoice): MailOpsSkillMapStep[] {
  return [
    {
      id: "template",
      label: "템플릿",
      title: choice.label,
      detail: mailOpsTemplateAppliesTo(choice.id),
      state: "active",
    },
    {
      id: "connection",
      label: "연결",
      title: choice.connectionNeed,
      detail: mailOpsTemplateSettings(choice.id),
      state: "ready",
    },
    {
      id: "output",
      label: "결과",
      title: mailOpsScenarioPreparedOutput(choice.id),
      detail: mailOpsTemplateSkillFlow(choice.id),
      state: "ready",
    },
    {
      id: "approval",
      label: "승인",
      title: choice.approvalPath,
      detail: mailOpsScenarioFinalActionBoundary(choice.id),
      state: "approval",
    },
    {
      id: "learning",
      label: "학습",
      title: choice.learningMemory,
      detail: mailOpsScenarioLearningApplication(choice.id),
      state: "learn",
    },
  ];
}

function mailOpsTemplateAppliesTo(id: string): string {
  if (/mobile_review_handoff/u.test(id)) return "중요 메일, 승인 대기, 밖에서 휴대폰으로 확인할 항목";
  if (/mail_info_digest/u.test(id)) return "중요 메일 요약, 처리 현황, 확인 필요 정보 전달";
  if (/customer|reply/u.test(id)) return "문의 답장, 회신 요청, 고객 상담 메일";
  if (/calendar|reservation_order/u.test(id)) return "미팅 요청, 예약 변경, 방문/상담 일정";
  if (/bulk|recipient|compliance/u.test(id)) return "명단 발송, 공지, 마케팅, 수신자/참조 판단";
  if (/quote|vendor/u.test(id)) return "견적, 발주, 거래처 조건, 납기 문의";
  if (/invoice/u.test(id)) return "정산, 청구, 세금계산서, 입금 확인";
  if (/contract|public_tax|high_risk/u.test(id)) return "계약, 세무, 공공기관, 제출/신고 메일";
  if (/complaint/u.test(id)) return "불만, 환불, 긴급 장애, 책임 표현 검토";
  if (/document|attachment/u.test(id)) return "첨부, 보고서, 증빙, 제출 파일 확인";
  if (/security/u.test(id)) return "로그인, 2차 인증, 권한, 계정 보안 알림";
  if (/follow_up/u.test(id)) return "마감, 회신 대기, 재안내, 리마인드 후보";
  if (/internal/u.test(id)) return "팀 공지, 내부 공유, 담당자/마감 확인";
  return "메일함 읽기, 업무 분류, 확인 필요 메일";
}

function mailOpsTemplateSettings(id: string): string {
  if (/mobile_review_handoff/u.test(id)) return "메일 읽기 권한, 알림 채널, 휴대폰 한 줄 요약, 앱 최종 확인";
  if (/mail_info_digest/u.test(id)) return "메일 읽기 권한, 전달 대상, 공유 채널, 민감정보 제외 기준";
  if (/calendar|reservation_order/u.test(id)) return "메일 읽기와 캘린더 가능한 시간 확인부터, 등록 권한은 마지막에 확인";
  if (/bulk|recipient|compliance|attachment/u.test(id)) return "메일 계정, 명단 파일, 제외 규칙, 샘플 검토 기준";
  if (/security|connection/u.test(id)) return "계정 보관함, 공식 로그인 화면, 2차 인증, 앱 비밀번호";
  if (/quote|vendor|invoice|contract|public_tax|document|hr|high_risk/u.test(id)) return "메일 근거, 관련 파일 위치, 담당자 검토 기준";
  return "Gmail/Outlook/회사 메일 중 하나만 읽기 전용으로 준비";
}

function mailOpsTemplateSkillFlow(id: string): string {
  if (/mobile_review_handoff/u.test(id)) return "메일 분석 -> 휴대폰 한 줄 요약 -> 승인/수정/보류 -> 앱 최종 확인";
  if (/mail_info_digest/u.test(id)) return "메일 요약 -> 확인 필요 정보 -> 전달 후보 -> 승인함";
  if (/calendar|reservation_order/u.test(id)) return "메일 분석 -> 시간 후보 -> 캘린더 충돌 확인 -> 승인함";
  if (/bulk|recipient|compliance|attachment/u.test(id)) return "메일/파일 분석 -> 대상/제외 판단 -> 샘플 문안 -> 최종 확인";
  if (/quote|vendor|invoice/u.test(id)) return "조건 추출 -> 금액/납기/증빙 체크 -> 답장 초안 -> 승인함";
  if (/contract|public_tax|hr|document|high_risk/u.test(id)) return "고위험 분류 -> 체크리스트 -> 담당자 검토 -> 실행 잠금";
  if (/follow_up/u.test(id)) return "마감 신호 -> 다음 확인 시점 -> 알림/초안 후보 -> 자동 발송 차단";
  return "메일 분류 -> 초안/확인 질문 -> 승인함 -> 처리 방식 학습";
}

function buildMailOpsScenarioChoiceBoard(result: MailWorkIntakeResult | null): MailOpsScenarioChoice[] {
  const observed = (result?.workAnalysis?.scenarioCoverage ?? [])
    .filter((scenario) => scenario.status === "observed")
    .map((scenario): MailOpsScenarioChoice => {
      const action = mailOpsScenarioPrimaryAction(scenario.id);
      const secondaryAction = mailOpsScenarioSecondaryAction(scenario.id);
      return {
        id: scenario.id,
        label: scenario.label,
        badge: mailOpsScenarioBadge(scenario.id, scenario.label),
        workGroup: mailOpsScenarioWorkGroup(scenario.id),
        detail: scenario.guidance || scenario.purpose,
        nextAction: scenario.nextAction || scenario.userDecision,
        connectionNeed: mailOpsScenarioConnectionNeed(scenario.id),
        approvalPath: mailOpsScenarioApprovalPath(scenario.id),
        learningMemory: scenario.learningValue || mailOpsScenarioLearningMemory(scenario.id),
        safetyGate: scenario.safetyGate,
        evidenceCount: scenario.evidenceCount,
        state: "observed",
        primaryAction: action,
        primaryLabel: mailOpsScenarioPrimaryLabel(scenario.id, action),
        ...(secondaryAction ? {
          secondaryAction,
          secondaryLabel: mailOpsScenarioSecondaryLabel(scenario.id),
        } : {}),
      };
    });
  const seen = new Set(observed.map((item) => item.id));
  return [
    ...observed.sort((a, b) => b.evidenceCount - a.evidenceCount || a.label.localeCompare(b.label, "ko-KR")),
    ...defaultMailOpsScenarioChoices.filter((item) => !seen.has(item.id)),
  ].slice(0, 20);
}

function createMailOpsCandidateFromScenarioChoice(choice: MailOpsScenarioChoice): MailOpsCandidateState {
  if (/bulk_mail|recipient_selection|compliance_unsubscribe|attachment_followup/u.test(choice.id)) {
    return {
      accountScope: "메일 근거와 첨부/엑셀 명단",
      checkScope: "발송 대상, 제외 대상, 중복 주소, 수신거부",
      output: "대상 그룹, 제외 규칙, 샘플 문안",
      approval: "전체 명단과 샘플 문안 확인 후 실행하기",
      bulkSubject: choice.id === "bulk_mail" ? "대량 메일 제목 초안" : "",
      bulkBody: choice.id === "bulk_mail"
        ? "여러 사람에게 보낼 내용을 입력하고, 명단 검토 후 샘플 문안으로 먼저 확인합니다."
        : "",
      targetGroups: "명단 파일에서 추천 대상 그룹 확인",
      exclusionRules: "수신거부, 중복 주소, 최근 발송 완료 대상 제외",
      personalizationFields: "이름, 회사/기관, 업무 맥락",
      sampleReview: "샘플 3건 먼저 확인",
    };
  }
  if (/security_account_alert|connection_preflight/u.test(choice.id)) {
    return {
      accountScope: "공식 연결 화면과 계정 보관함",
      checkScope: "로그인, 2차 인증, 앱 비밀번호, 권한 알림",
      output: "연결 준비 체크리스트와 복구 경로",
      approval: "비밀번호와 인증코드는 채팅에 쓰지 않고 사용자 확인",
    };
  }
  if (/calendar_coordination|reservation_order/u.test(choice.id)) {
    return {
      accountScope: "메일과 캘린더 후보",
      checkScope: "일정 표현, 참석자, 가능한 시간, 충돌",
      output: "일정 후보와 등록 전 체크리스트",
      approval: "캘린더 등록과 초대 발송 전 실행하기",
    };
  }
  if (/quote_proposal|vendor_procurement|contract_legal|public_tax|invoice_payment|hr_recruiting|document_submission/u.test(choice.id)) {
    return {
      accountScope: "메일 근거와 관련 파일",
      checkScope: "기한, 금액, 개인정보, 첨부, 제출/공유 범위",
      output: "고위험 검토 체크리스트와 보류/수정 후보",
      approval: "제출, 공유, 발송은 오피스 승인함 최종 확인",
    };
  }
  if (/customer_inquiry|complaint_escalation/u.test(choice.id)) {
    return {
      accountScope: "고객 문의 메일",
      checkScope: "문의 유형, 담당자, 답변 범위, 금지 표현",
      output: "응대 초안과 추가 확인 질문",
      approval: "가격, 보상, 책임 표현은 사용자 확인 후 발송",
    };
  }
  return {
    accountScope: "연결된 메일 전체",
    checkScope: choice.nextAction,
    output: choice.label.includes("답장") ? "답장 초안과 수정 후보" : "업무 후보와 승인 카드",
    approval: choice.safetyGate || "발송/일정 등록 전 항상 승인",
  };
}

