function buildMailOpsResultInsightGroups(result: MailWorkIntakeResult) {
  const analysis = result.workAnalysis;
  if (!analysis) return [];
  return [
    { label: "업무 방식", items: analysis.workingStyle ?? [] },
    { label: "연결 준비", items: analysis.connectionPreparation ?? [] },
    { label: "연결/2차 인증 준비", items: formatConnectionReadinessPlanInsightItems(analysis.connectionReadinessPlan) },
    { label: "답장 톤", items: analysis.replyToneGuidance ?? [] },
    { label: "일정 추천", items: analysis.scheduleGuidance ?? [] },
    { label: "수신자 판단", items: analysis.recipientGuidance ?? [] },
    { label: "발송 계획", items: analysis.sendingPlanGuidance ?? [] },
    { label: "참조/숨은참조 판단", items: formatRecipientCopyPlanInsightItems(analysis.recipientCopyPlan) },
    { label: "대량 발송 계획", items: formatBulkSendPlanInsightItems(analysis.bulkSendPlan) },
    { label: "후속 확인 계획", items: formatFollowUpPlanInsightItems(analysis.followUpPlan) },
    { label: "첨부/엑셀 명단 계획", items: formatRecipientSourcePlanInsightItems(analysis.recipientSourcePlan) },
    { label: "학습 신호", items: analysis.learningSignals ?? [] },
    {
      label: "업무 경우의 수",
      items: (analysis.scenarioCoverage ?? [])
        .filter((scenario) => scenario.status === "observed")
        .map((scenario) => `${scenario.label}: ${scenario.guidance} 다음: ${scenario.nextAction}`),
    },
    { label: "개선 제안", items: analysis.improvementSuggestions ?? [] },
    { label: "자동화 후보", items: analysis.automationOpportunities ?? [] },
    { label: "승인 정책", items: analysis.approvalPolicy ?? [] },
    { label: "주의", items: analysis.riskNotes ?? [] },
  ].filter((group) => group.items.length > 0);
}

