function applyInitialLearningProfileToSecureMailPollingRule(result: MailWorkIntakeResult): LocalAutomationRule | null {
  const profile = result.initialLearningProfile;
  if (!profile || typeof window === "undefined") return null;

  const { rule } = ensureSecureMailPollingRule();
  const profileLabels = buildInitialLearningSecurePollingLabels(profile);
  const profileSummary = profile.profileSummary || "초기 메일함 학습 기준";
  const safeLabelSummary = profileLabels.slice(0, 3).join(" · ") || "말투/광고 제외/승인 기준";
  const existingEvidence = rule.provenance?.evidenceLabels ?? [];
  const nextRules = updateLocalAutomationRule(rule.id, {
    goal: replaceRuleLearningLine(
      rule.goal,
      `초기 학습 기준: ${profileSummary} · ${safeLabelSummary}`,
    ),
    output: replaceRuleLearningLine(
      rule.output,
      `초기 학습 반영: ${safeLabelSummary}를 5분 점검의 제외/승인 후보 기준으로 사용`,
    ),
    approval: replaceRuleLearningLine(
      rule.approval,
      "학습 저장 경계: safe labels only, 사용자 승인 전 외부 발송/일정 등록/파일 변경 없음",
    ),
    provenance: {
      source: rule.provenance?.source ?? "work_pack",
      sourceLabel: rule.provenance?.sourceLabel ?? "보안 메일 자동 점검",
      intent: "초기 메일함 학습 기준을 5분 메일 점검의 메타데이터 선필터, 승인 후보, 대량/일정/첨부 잠금 기준으로 반영",
      evidenceLabels: uniqueRuleEvidenceLabels([
        ...existingEvidence,
        "initial_mail_profile_learning_secret_blind",
        "profile_to_5m_polling_to_approval_queue",
        "safe_labels_only_user_approved",
        "tone_noise_bulk_approval_to_secure_mail_polling",
        ...profileLabels,
      ]),
      confidencePercent: Math.max(rule.provenance?.confidencePercent ?? 0, 94),
      capturedAt: new Date().toISOString(),
    },
    latestRunMessage: `초기 학습 기준 반영: ${safeLabelSummary}`,
  });
  return nextRules.find((item) => item.id === rule.id) ?? rule;
}

function replaceRuleLearningLine(text: string, learningLine: string): string {
  const base = text
    .split("\n")
    .filter((line) => !/^초기 학습 (기준|반영|저장 경계)|^학습 저장 경계/u.test(line.trim()))
    .join("\n")
    .trim();
  return [base, learningLine].filter(Boolean).join("\n").slice(0, 900);
}

function buildInitialLearningSecurePollingLabels(profile: NonNullable<MailWorkIntakeResult["initialLearningProfile"]>): string[] {
  return uniqueRuleEvidenceLabels([
    profile.writingStyleProfile?.toneLabel ? `말투 기준: ${profile.writingStyleProfile.toneLabel}` : "",
    profile.noiseFilterProfile?.rules?.[0] || "",
    profile.noiseFilterProfile?.skippedBeforeBodyCount
      ? `광고/뉴스레터 본문 전 제외 ${profile.noiseFilterProfile.skippedBeforeBodyCount}건`
      : "",
    profile.bulkMailProfile?.status === "review_required"
      ? `대량 발송 기준: ${profile.bulkMailProfile.targetGroups?.slice(0, 2).join(", ") || "검토 필요"}`
      : "",
    profile.approvalHabitProfile?.approvalRequiredFor?.[0] || "",
    profile.scanDepthProfile?.sampledMessageCount
      ? `초기 학습 범위: ${profile.scanDepthProfile.sampledMessageCount}건`
      : "",
  ]).slice(0, 8);
}

function uniqueRuleEvidenceLabels(labels: string[]): string[] {
  const seen = new Set<string>();
  return labels
    .map((label) => label.replace(/\s+/gu, " ").trim())
    .filter((label) => {
      if (!label || seen.has(label)) return false;
      seen.add(label);
      return true;
    })
    .slice(0, 24);
}

function buildMailAttachmentOrganizerCards(result: MailWorkIntakeResult) {
  const plan = result.attachmentOrganizerPlan;
  if (!plan || plan.status !== "ready_for_download_review") return [];
  const candidateSummaries = plan.candidateSummaries ?? [];
  const candidatePreview = candidateSummaries
    .slice(0, 3)
    .map((candidate) => `${candidate.subjectLabel ?? "첨부 후보"} -> ${candidate.targetFolderHint ?? "메일 첨부"}`)
    .join(" / ");
  return [
    {
      id: "candidate",
      label: "후보",
      title: `${plan.attachmentCandidateCount ?? plan.candidateSummaries?.length ?? 0}건 감지`,
      detail: candidatePreview
        ? `대표 후보: ${candidatePreview}`
        : "첨부 표시와 계약/견적/세금계산서/자료 신호를 기준으로 골랐습니다.",
      state: "ready",
    },
    {
      id: "download",
      label: "다운로드",
      title: plan.downloadPlan?.downloadRootLabel || "메일 첨부 임시 보관함",
      detail: plan.downloadPlan?.allowedFilePolicy || "실행 파일은 자동으로 열지 않고 업무 파일만 후보로 둡니다.",
      state: "review",
    },
    {
      id: "folder",
      label: "폴더",
      title: plan.organizePlan?.targetFolderHints?.slice(0, 3).join(" / ") || "메일 첨부",
      detail: "승인 카드 후 최종 적용 영수증 downloaded_mail_attachment_to_folder_plan_final_apply를 남깁니다.",
      state: "approval",
    },
    {
      id: "lock",
      label: "잠금",
      title: "삭제·덮어쓰기·공유 안 함",
      detail: plan.approvalGate || "사용자 최종 승인 전까지 외부 변경을 실행하지 않습니다.",
      state: "locked",
    },
  ];
}

function buildMailOpsApprovalPreviewCards(result: MailWorkIntakeResult): MailOpsApprovalPreviewCard[] {
  if (result.approvalPreviews?.length) {
    return result.approvalPreviews.slice(0, 8).map((preview) => {
      const previewType = `${(preview as { type?: string }).type ?? preview.kind ?? ""}`;
      const calendar = preview.kind === "create_calendar_event" || /calendar|schedule/u.test(previewType);
      const bulk = preview.kind === "bulk_send_plan" || /bulk/u.test(previewType);
      const followUp = preview.kind === "follow_up_plan" || /follow/u.test(previewType);
      const recipientSource = preview.kind === "recipient_source_plan" || /recipient_source/u.test(previewType);
      const recipientList = preview.kind === "recipient_list_review" || /recipient_list/u.test(previewType);
      const scenarioReview = preview.kind === "scenario_review" || /scenario/u.test(previewType);
      const review = preview.status === "needs_review";
      const state = review ? "review" : preview.requiresFinalUserPresence ? "approval" : "locked";
      const meta = [
        preview.sourceLabel,
        preview.timeRangeLabel,
        preview.conflictLabel,
        preview.reminderLabel,
        ...(preview.attendeeLabels ?? []),
      ].filter(Boolean).slice(0, 5) as string[];
      return {
        id: preview.id,
        badge: preview.badge ?? (recipientList || recipientSource ? "명단" : followUp ? "후속" : bulk ? "대량" : calendar ? "일정" : "답장"),
        pipelineStepId: calendar ? "schedule_candidate" : "reply_draft",
        previewType: previewType || "reply_draft",
        previewStatus: preview.status,
        title: preview.title,
        detail:
          preview.summary ||
          preview.blockedReason ||
          (recipientList
            ? "CSV/XLSX 명단에서 만든 발송 후보 샘플과 제외 대상을 확인하는 카드입니다."
            : recipientSource
              ? "첨부/엑셀 명단 원천과 제외 규칙을 확인해야 하는 발송 대상 준비 카드입니다."
            : followUp
              ? "회신 대기와 마감 신호를 다음 확인 계획으로 잠근 후속 추적 카드입니다."
              : bulk
                ? "대상 그룹, 제외 대상, 개인화 샘플을 확인해야 하는 대량 메일 계획입니다."
                : scenarioReview
                  ? "업무 종류별 위험 기준과 확인 항목을 사용자 승인 전까지 잠그는 메일 업무 카드입니다."
                : calendar
                  ? "메일에서 감지한 일정 후보입니다. 등록은 앱의 마지막 확인 전까지 잠겨 있습니다."
                  : "메일 답장 초안입니다. 발송은 앱의 마지막 확인 전까지 잠겨 있습니다."),
        countLabel: preview.countLabel ?? "1건",
        state,
        handoffLabel: preview.handoffLabel || (bulk
          ? "대량 메일 계획 - 마지막 확인 준비"
          : followUp
            ? "후속 확인 계획 - 마지막 확인 준비"
            : recipientList
              ? "명단 발송 샘플 - 마지막 확인 준비"
              : recipientSource
                ? "명단 원천 검토 - 마지막 확인 준비"
                : scenarioReview
                  ? "메일 업무 케이스 - 마지막 확인 준비"
                  : calendar
                    ? "일정 후보 - 마지막 확인 준비"
                    : "답장 초안 - 마지막 확인 준비"),
        preparedOutput: preview.preparedOutput,
        verificationEvidence: preview.verificationEvidence,
        finalActionBoundary: preview.finalActionBoundary,
        mailWorkReview: preview.mailWorkReview,
        mobileReceiveFilterIds: preview.mobileReceiveFilterIds,
        mobileReceiveFilterLabels: preview.mobileReceiveFilterLabels,
        steps: (preview.checklist?.length
          ? preview.checklist
          : recipientList
            ? ["전체 행 수 확인", "중복/제외 확인", "샘플 문안 검토", "실행하기 전 발송 차단"]
            : recipientSource
              ? ["파일 원천 확인", "중복/제외 확인", "샘플 문안 검토", "주소 원문 비노출"]
            : followUp
              ? ["후속 대상 확인", "다음 확인 시점", "리마인드 초안 검토", "자동 독촉 차단"]
              : bulk
                ? ["대상 그룹 확인", "제외 대상 확인", "샘플 문안 검토", "실행하기 전 발송 차단"]
                : scenarioReview
                  ? ["업무 종류 확인", "위험 기준 확인", "고쳐달라고 하기 또는 보류", "실행하기 전 실행 차단"]
                : calendar
                  ? ["가능 시간 확인", "고쳐달라고 하기", "등록 확인 대기"]
                  : ["초안 보기", "고쳐달라고 하기", "실행하기 대기"]).slice(0, 4),
        decisionRail: createMailOpsDecisionRail(
          state,
          calendar,
          recipientList || recipientSource
            ? "명단 발송 준비"
            : followUp
              ? "후속 확인"
              : bulk
                ? "대량 발송"
                : scenarioReview
                  ? preview.badge || "업무 검토"
                  : undefined,
        ),
        draftBody: preview.draftBody,
        meta,
        blockedReason: preview.blockedReason,
        workItemId: preview.workItemId,
      };
    });
  }

  const stats = result.workAnalysis?.stats;
  const approvalCount = result.approvalQueueCount ?? stats?.approvalCandidates ?? 0;
  const replyCount = stats?.replyCandidates ?? 0;
  const calendarCount = stats?.calendarCandidates ?? result.calendarBusyWindowCount ?? 0;
  const bulkCount = stats?.bulkMailSignals ?? 0;
  const followUpCount = stats?.followUpSignals ?? 0;
  const recipientSourceCount = stats?.recipientSourceSignals ?? 0;
  const reviewCount = result.reviewItemsCount ?? stats?.reviewItems ?? 0;
  const cards: MailOpsApprovalPreviewCard[] = [];

  if (replyCount > 0 || approvalCount > 0) {
    cards.push({
      id: "reply-draft",
      badge: "승인",
      pipelineStepId: "reply_draft",
      previewType: "reply_draft",
      previewStatus: "approval_required",
      title: "답장 초안 승인",
      detail: "메일 답장 후보는 초안 보기와 고쳐달라고 하기를 거친 뒤에만 마지막 발송 후보로 넘어갑니다.",
      countLabel: replyCount > 0 ? `${replyCount}건` : `${approvalCount}건`,
      state: "approval",
      handoffLabel: "답장 초안 - 오피스 승인함 실행하기",
      steps: ["초안 보기", "고쳐달라고 하기", "실행하기 대기"],
      decisionRail: createMailOpsDecisionRail("approval", false),
    });
  }

  if (calendarCount > 0) {
    cards.push({
      id: "calendar-candidate",
      badge: "일정",
      pipelineStepId: "schedule_candidate",
      previewType: "calendar_candidate",
      previewStatus: "approval_required",
      title: "일정 후보 확인",
      detail: "캘린더 충돌과 가능한 시간대를 확인하고, 등록은 앱의 마지막 확인 전까지 잠급니다.",
      countLabel: `${calendarCount}건`,
      state: "approval",
      handoffLabel: "일정 후보 - 캘린더 등록 전 확인",
      steps: ["가능 시간 확인", "고쳐달라고 하기", "등록 확인 대기"],
      decisionRail: createMailOpsDecisionRail("approval", true),
    });
  }

  if (bulkCount > 0 || result.workAnalysis?.bulkSendPlan?.status === "review_required") {
    cards.push({
      id: "bulk-send-plan",
      badge: "대량",
      pipelineStepId: "approval_queue",
      previewType: "bulk_send_plan",
      previewStatus: "approval_required",
      title: "대량 메일 계획 검토",
      detail: "대상 그룹, 제외 대상, 개인화 샘플을 확인해야 하며 실행하기 전에는 발송하지 않습니다.",
      countLabel: bulkCount > 0 ? `${bulkCount}건` : "계획",
      state: "approval",
      handoffLabel: "대량 메일 계획 - 마지막 확인 준비",
      steps: ["대상 그룹 확인", "제외 대상 확인", "샘플 문안 검토", "실행하기 전 발송 차단"],
      decisionRail: createMailOpsDecisionRail("approval", false, "대량 발송"),
    });
  }

  if (followUpCount > 0 || result.workAnalysis?.followUpPlan?.status === "review_required") {
    cards.push({
      id: "follow-up-plan",
      badge: "후속",
      pipelineStepId: "approval_queue",
      previewType: "follow_up_plan",
      previewStatus: "approval_required",
      title: "후속 확인 계획",
      detail: "회신 대기, 마감, 리마인드 후보를 다음 확인 계획으로 잠그고 자동 독촉 발송은 하지 않습니다.",
      countLabel: followUpCount > 0 ? `${followUpCount}건` : "계획",
      state: "approval",
      handoffLabel: "후속 확인 계획 - 마지막 확인 준비",
      steps: ["후속 대상 확인", "다음 확인 시점", "리마인드 초안 검토", "자동 독촉 차단"],
      decisionRail: createMailOpsDecisionRail("approval", false, "후속 확인"),
    });
  }

  if (recipientSourceCount > 0 || result.workAnalysis?.recipientSourcePlan?.status === "review_required") {
    cards.push({
      id: "recipient-source-plan",
      badge: "명단",
      pipelineStepId: "approval_queue",
      previewType: "recipient_source_plan",
      previewStatus: "approval_required",
      title: "첨부/엑셀 명단 원천 검토",
      detail: "명단 파일의 최신 여부, 중복/제외 기준, 샘플 문안을 확인하기 전까지 발송 대상에 반영하지 않습니다.",
      countLabel: recipientSourceCount > 0 ? `${recipientSourceCount}건` : "계획",
      state: "approval",
      handoffLabel: "명단 원천 검토 - 마지막 확인 준비",
      steps: ["파일 원천 확인", "중복/제외 확인", "샘플 문안 검토", "주소 원문 비노출"],
      decisionRail: createMailOpsDecisionRail("approval", false, "명단 발송 준비"),
    });
  }

  if (reviewCount > 0) {
    cards.push({
      id: "human-review",
      badge: "검토",
      pipelineStepId: "approval_queue",
      previewType: "human_review",
      previewStatus: "needs_review",
      title: "사람 판단 필요",
      detail: "정보가 부족하거나 정책 확인이 필요한 항목은 자동 답변 대신 질문 후보로 남깁니다.",
      countLabel: `${reviewCount}건`,
      state: "review",
      handoffLabel: "확인 필요 - 자동 실행 금지",
      steps: ["근거 확인", "질문 작성", "보류 또는 재분류"],
      decisionRail: createMailOpsDecisionRail("review", false),
    });
  }

  if (!cards.length && approvalCount > 0) {
    cards.push({
      id: "approval-locked",
      badge: "잠금",
      pipelineStepId: "approval_queue",
      previewType: "approval_locked",
      previewStatus: "approval_required",
      title: "승인 후보 잠금",
      detail: "실행 가능한 후보가 있지만 상세 항목은 오피스 승인함에서 다시 확인해야 합니다.",
      countLabel: `${approvalCount}건`,
      state: "locked",
      handoffLabel: "실행 잠금 - 오피스 확인 필요",
      steps: ["후보 확인", "실행 전 검토", "실행하기 대기"],
      decisionRail: createMailOpsDecisionRail("locked", false),
    });
  }

  return cards.slice(0, 4);
}

function createMailOpsDecisionRail(
  state: MailOpsApprovalPreviewCard["state"],
  calendar: boolean,
  finalLabelOverride?: string,
): MailOpsApprovalPreviewCard["decisionRail"] {
  const finalLabel = finalLabelOverride ?? (calendar ? "캘린더 등록" : "메일 발송");
  if (state === "locked") {
    return [
      { label: "후보 대기", detail: "오피스 승인함 확인", state: "active" },
      { label: "실행 전 검토", detail: "실행 조건 검증", state: "locked" },
      { label: finalLabel, detail: "최종 확인 전 잠금", state: "locked" },
    ];
  }
  if (state === "review") {
    return [
      { label: "근거 확인", detail: "사람 판단 필요", state: "active" },
      { label: "고쳐달라고 하기", detail: "채팅에서 반영", state: "locked" },
      { label: finalLabel, detail: "보류 가능", state: "locked" },
    ];
  }
  return [
    { label: "초안/후보", detail: "읽기 완료", state: "done" },
    { label: "고쳐달라고 하기", detail: "채팅에서 반영", state: "active" },
    { label: finalLabel, detail: "사용자 최종 확인 전 잠금", state: "locked" },
  ];
}

function buildMailOpsNotificationCards(result: MailWorkIntakeResult | null): MailOpsNotificationCard[] {
  if (!result) {
    return [
      {
        id: "mailops-running",
        tone: "recovery",
        label: "준비",
        title: "메일 점검이 실행 준비 중입니다",
        detail: "Windows 앱에서 메일함 읽기, 계정 보관함, 오피스 승인함을 순서대로 확인합니다.",
        actionLabel: "연결 확인",
        action: "mailops_check",
      },
    ];
  }

  if (result.connectionRecovery) {
    const recovery = result.connectionRecovery;
    return [
      {
        id: "mailops-connection-recovery",
        tone: "recovery",
        label: recovery.label,
        title: recovery.actionLabel || "연결 복구",
        detail: visibleConnectionRecoveryDetail(recovery.detail),
        actionLabel: visibleConnectionNextAction(recovery.actionLabel || recovery.detail, "복구 시작"),
        action: mailOpsRecoveryAction(recovery.kind),
      },
      {
        id: "mailops-safe-handoff",
        tone: "recovery",
        label: "안전",
        title: "연결 전에는 실행하지 않습니다",
        detail: recovery.safeNextActions?.[0]
          ? visibleConnectionSafeAction(recovery.safeNextActions[0])
          : "비밀값은 채팅에 남기지 않고 실행은 앱의 마지막 확인 전까지 멈춥니다.",
        actionLabel: "승인 알림 보기",
        action: "open_office",
      },
    ];
  }

  if (isMailConnectorMissingStatus(result.status)) {
    return [
      {
        id: "mailops-connect-mail",
        tone: "recovery",
        label: "연결 필요",
        title: "메일함 연결이 먼저 필요합니다",
        detail: "Gmail, Outlook, 회사 메일 중 하나를 연결하세요. 비밀번호와 토큰은 채팅이 아니라 계정 보관함에 저장합니다.",
        actionLabel: "계정 보관함",
        action: "external_accounts",
      },
      {
        id: "mailops-connect-channel",
        tone: "recovery",
        label: "알림",
        title: "Telegram 없이도 앱 안에서 승인받습니다",
        detail: "외부 메신저가 없으면 오피스 승인함이 앱 내부 승인 카드로 답장, 일정, 보류 요청을 보여줍니다.",
        actionLabel: "알림 채널",
        action: "messenger_channels",
      },
    ];
  }

  const stats = result.workAnalysis?.stats;
  const approvalCount = result.approvalQueueCount ?? stats?.approvalCandidates ?? 0;
  const replyCount = stats?.replyCandidates ?? 0;
  const calendarCount = stats?.calendarCandidates ?? result.calendarBusyWindowCount ?? 0;
  const cards: MailOpsNotificationCard[] = [];

  if (approvalCount > 0) {
    cards.push({
      id: "mailops-approval-queue",
      tone: "approval",
      label: "승인 대기",
      title: `${approvalCount}건을 실행 전 잠갔습니다`,
      detail: "답장 발송, 캘린더 등록, 외부 발송은 사용자가 실행하거나 고쳐달라고 하기 전까지 실행하지 않습니다.",
      actionLabel: "승인 카드 보기",
      action: "open_office",
    });
  }

  if (replyCount > 0) {
    cards.push({
      id: "mailops-reply-drafts",
      tone: "reply",
      label: "답장",
      title: `맞춤 답장 초안 ${replyCount}건`,
      detail: "메일 문맥과 사용자의 이전 업무 패턴을 함께 보고 답장 톤과 확인 질문을 제안합니다.",
      actionLabel: "초안 확인",
      action: "open_office",
    });
  }

  if (calendarCount > 0) {
    cards.push({
      id: "mailops-calendar-candidates",
      tone: "calendar",
      label: "일정",
      title: `일정 후보 ${calendarCount}건`,
      detail: "캘린더나 일정 시트 연결이 있으면 가능한 시간과 충돌을 확인해 확정 후보로 정리합니다.",
      actionLabel: "일정 확인",
      action: "open_office",
    });
  }

  if (result.workAnalysis) {
    cards.push({
      id: "mailops-learning",
      tone: "learning",
      label: "학습",
      title: "사용자 업무 패턴을 기억했습니다",
      detail:
        result.workAnalysis.summary ??
        "읽은 메일에서 업무 방식, 반복 질문, 개선 제안, 자동화 후보를 로컬 기억에 반영했습니다.",
      actionLabel: "기억 위치",
      action: "memory_root",
    });
  }

  if (!cards.length) {
    cards.push({
      id: "mailops-readonly",
      tone: "learning",
      label: "읽기 완료",
      title: "메일함을 읽고 업무 후보를 정리했습니다",
      detail: "이번 실행은 읽기 전용으로 끝났고, 다음 요청부터 답장/일정 후보가 생기면 오피스 승인함이 승인 카드로 올립니다.",
      actionLabel: "오피스 보기",
      action: "open_office",
    });
  }

  return cards.slice(0, 4);
}

function buildMailOpsApprovalInboxBridge(
  session: MailOpsSession,
  statuses: ConnectorStatusRecord[],
): MailOpsApprovalInboxStep[] {
  const result = session.result ?? null;
  const stats = result?.workAnalysis?.stats;
  const mailReady = hasReadyConnector(statuses, "mail");
  const approvalCount = result?.approvalQueueCount ?? stats?.approvalCandidates ?? 0;
  const replyCount = stats?.replyCandidates ?? 0;
  const calendarCount = stats?.calendarCandidates ?? result?.calendarBusyWindowCount ?? 0;
  const reviewCount = result?.reviewItemsCount ?? stats?.reviewItems ?? 0;
  const workItemCount = result?.createdWorkItemsCount ?? result?.addedInboxItemsCount ?? stats?.workItems ?? 0;
  const hasExecutionCandidate = approvalCount > 0 || replyCount > 0 || calendarCount > 0;

  return [
    {
      id: "mail-read",
      badge: "읽기",
      label: "메일함 업무 추출",
      countLabel: result ? `${result.messageCount ?? stats?.totalMessages ?? 0}건` : mailReady ? "준비됨" : "연결 필요",
      detail: result
        ? `업무 후보 ${workItemCount}건을 만들고 원문 발송은 멈췄습니다.`
        : "연결된 메일함을 읽기 전용으로 읽고 답장/일정 후보만 만듭니다.",
      state: result ? "done" : mailReady ? "active" : "pending",
      action: mailReady ? "mailops_check" : "external_accounts",
    },
    {
      id: "assistant-inbox",
      badge: "승인함",
      label: "오피스 승인함",
      countLabel: approvalCount > 0 ? `${approvalCount}건` : "대기",
      detail: approvalCount > 0
        ? "답장 초안과 일정 후보가 앱 내부 승인 카드로 올라왔습니다."
        : "후보가 생기면 Telegram 없이도 앱 안 승인함에서 먼저 보여줍니다.",
      state: approvalCount > 0 ? "active" : result ? "done" : "pending",
      action: "open_office",
    },
    {
      id: "revision-loop",
      badge: "수정",
      label: "실행·수정·보류 대화",
      countLabel: reviewCount > 0 ? `${reviewCount}건` : "항상 가능",
      detail: "사용자가 실행하거나, 고쳐달라고 남기거나, 보류하면 담당 업무 비서 기록에 반영합니다.",
      state: approvalCount > 0 || reviewCount > 0 ? "active" : result ? "done" : "pending",
      action: "open_office",
    },
    {
      id: "final-action",
      badge: "실행",
      label: "마지막 확인",
      countLabel: hasExecutionCandidate ? "잠금" : "대기",
      detail: hasExecutionCandidate
        ? "메일 발송과 캘린더 등록은 사용자 최종 확인 전까지 잠겨 있습니다."
        : "승인 후보가 생기면 실행 전 검토와 최종 확인 후 외부 실행 후보로 넘어갑니다.",
      state: hasExecutionCandidate ? "locked" : result ? "pending" : "pending",
      action: "open_office",
    },
  ];
}

function mailOpsRecoveryAction(kind = ""): HomeAction {
  if (/credential|password|token|secret/u.test(kind)) return "external_accounts";
  if (/permission/u.test(kind)) return "external_accounts";
  if (/install/u.test(kind)) return "prepare_tools";
  return "mailops_check";
}

function buildWorkSyncExecutionReceipt(result: WorkSyncResult | null): ChatExecutionReceipt {
  const workItems = result?.createdWorkItemsCount ?? 0;
  const approval = result?.approvalQueueCount ?? 0;
  return {
    kind: "today_work",
    title: result ? "오늘 업무 확인" : "오늘 업무 확인 대기",
    detail: result
      ? "읽기 전용으로 확인하고 후보와 승인 대기만 남겼습니다."
      : "설치 앱 연결 전이라 실제 업무 도구는 읽지 않았습니다.",
    state: !result || result.status === "desktop_required" ? "blocked" : approval > 0 ? "approval" : "ready",
    metrics: [
      {
        label: "읽은 항목",
        value: `${result?.messageCount ?? 0}건`,
        detail: "메일, 일정, 외부 알림, 다른 PC 요청",
        state: result ? "ready" : "issue",
      },
      {
        label: "업무 후보",
        value: `${workItems}건`,
        detail: workItems ? "오피스 후보로 정리" : "생성된 후보 없음",
        state: workItems ? "ready" : "locked",
      },
      {
        label: "승인 대기",
        value: `${approval}건`,
        detail: approval ? "실행하기/고쳐달라고 하기/보류하기는 승인함에서 선택" : "외부 실행 없음",
        state: approval ? "approval" : "locked",
      },
    ],
    logLabel: result ? "대화 기록과 오피스 작업 기록" : "설치 앱 연결 후 생성",
    undoLabel: approval ? "승인 전 취소 가능" : "외부 실행이 없어 되돌릴 변경 없음",
    nextUserChoice: approval ? "오피스 승인함에서 확인" : "메일 연결 또는 반복 업무 점검",
    delegatedWork: "오늘 들어온 메일·일정·알림을 읽기 전용으로 점검하기",
    confirmationLocation: "오늘 업무 카드와 오피스 승인함",
    executionClosure: "오늘 업무 카드, 승인 후보, 대화 기록으로 확인",
  };
}

function buildMailOpsExecutionReceipt(result: MailWorkIntakeResult | null): ChatExecutionReceipt {
  const approval = result?.approvalQueueCount ?? 0;
  const workItems = result?.createdWorkItemsCount ?? result?.addedInboxItemsCount ?? 0;
  const missing = Boolean(result && isMailConnectorMissingStatus(result.status));
  const receipt = result?.mailWorkExecutionReceipt;
  const receiptStepCount = receipt?.processingSteps?.length ?? 0;
  return {
    kind: "mailops",
    title: receipt?.title ?? (result ? "메일 점검 결과" : "메일 점검 대기"),
    detail: result
      ? receipt
        ? `${receipt.decision === "dry_run_ready" ? "dry-run까지 확인했고" : "처리 영수증을 남겼고"} 외부 발송/일정 등록은 최종 확인 전까지 잠겨 있습니다.`
        : "메일은 읽기 전용으로 확인하고 답장/일정 후보만 승인 대기로 올렸습니다."
      : "설치 앱 연결 전이라 메일함은 읽지 않았습니다.",
    state: !result || missing ? "blocked" : approval > 0 ? "approval" : "ready",
    metrics: [
      {
        label: "읽은 메일",
        value: `${result?.messageCount ?? 0}건`,
        detail: missing ? "메일 연결 필요" : "원문 발송/이동 없음",
        state: result && !missing ? "ready" : "issue",
      },
      {
        label: "초안/일정 후보",
        value: `${workItems}건`,
        detail: workItems ? "답장/일정 후보 생성" : "후보 없음",
        state: workItems ? "ready" : "locked",
      },
      {
        label: "승인 대기",
        value: `${approval}건`,
        detail: approval ? "실행하기 전 최종 확인" : "외부 실행 없음",
        state: approval ? "approval" : "locked",
      },
      ...(receipt
        ? [
            {
              label: "처리 영수증",
              value: receipt.decision === "dry_run_ready" ? "dry-run" : `${receiptStepCount}단계`,
              detail: receipt.rawAddressStored === false ? "주소/비밀값 비노출" : "처리 기록 확인",
              state: "ready" as const,
            },
          ]
        : []),
    ],
    logLabel: receipt?.auditArtifactPath || receipt?.id || result?.activityAuditFile || "메일 점검 기록 대기",
    undoLabel: receipt?.rollbackBasis ?? (approval ? "실행 전 고쳐달라고 하기/보류하기 가능" : "메일 변경 없음"),
    nextUserChoice: receipt?.nextUserActions?.[0] ?? (missing ? "메일 연결 또는 계정 보관함" : "오피스 승인함에서 실행하기, 고쳐달라고 하기, 보류하기"),
    resultSummary:
      receipt?.recipientDecisionDigest?.[0] ??
      receipt?.approvalDigest?.[0] ??
      (receipt ? "메일 처리 영수증과 학습 초안을 남겼습니다." : undefined),
    delegatedWork: receipt?.processingSteps?.[0] ?? "메일 읽기 전용 점검과 답장/일정 후보 만들기",
    confirmationLocation: "오피스 승인함의 메일/일정 실행하기/고쳐달라고 하기/보류하기 카드",
    executionClosure: receipt ? "메일 처리 영수증, 실행 로그, 학습 초안으로 발송 전 상태 확인" : "승인 카드, 실행 로그, 처리 기록으로 발송 전 상태 확인",
    firstThreeMinuteSuccess: "업무 탭 선택 -> 필요 연결만 확인 -> 초안/일정/수신자 후보 -> 오피스 승인",
  };
}

function buildMailLiveE2ERehearsalReceipt(result: MailLiveE2ERehearsalResult): ChatExecutionReceipt {
  const ready = result.status === "ready_for_live_rehearsal";
  const approval = Number(result.approvalQueueCount ?? 0);
  const triggerRunnerReady = Boolean(result.triggerRunnerEvidenceSource || result.mailAutomationNotice);
  const triggerRunnerDetail = result.mailAutomationNotice ||
    (result.triggerRunnerEvidenceSource ? "마지막 자동 점검 리포트 확인" : "자동 점검 실행 기록 대기");
  const reportReady = Boolean(result.liveRehearsalReportPath || result.activityAuditFile || result.activityEvent?.id);
  return {
    kind: "mailops",
    title: "메일 live 리허설 결과",
    detail: ready
      ? "실제 계정 기준 읽기, 광고 제외, 승인 후보, 최종 발송 잠금을 확인했습니다."
      : "설치 앱 연결, 5분 점검 규칙, 테스트 메일 증거 중 아직 확인이 필요한 항목이 있습니다.",
    state: ready ? "ready" : approval > 0 ? "approval" : "blocked",
    metrics: [
      {
        label: "읽은 메일",
        value: `${result.messageCount ?? 0}건`,
        detail: result.mailReadStatus || "읽기 전용 리허설",
        state: (result.messageCount ?? 0) > 0 ? "ready" : "issue",
      },
      {
        label: "제외/필터",
        value: `${result.ignoredItemsCount ?? 0}건`,
        detail: "광고/자동 알림은 업무 후보에서 제외",
        state: (result.ignoredItemsCount ?? 0) > 0 ? "ready" : "locked",
      },
      {
        label: "승인 후보",
        value: `${approval}건`,
        detail: "답장/일정/첨부는 승인함에서 dry-run",
        state: approval > 0 ? "approval" : "locked",
      },
      {
        label: "자동 점검",
        value: result.triggerRunnerTriggeredBy || (result.securePollingRuleEnabled ? "5분" : "대기"),
        detail: triggerRunnerDetail,
        state: triggerRunnerReady ? "ready" : result.securePollingRuleEnabled ? "locked" : "issue",
      },
      {
        label: "로컬 리포트",
        value: reportReady ? "저장" : "대기",
        detail: result.liveRehearsalReportSummary || result.liveRehearsalReportPath || "리허설 실행 후 로컬 기록 생성",
        state: reportReady ? "ready" : "locked",
      },
      {
        label: "최종 실행",
        value: "잠금",
        detail: result.finalSendLockedUntilApproval ? "마지막 확인 전 발송 금지" : "확인 필요",
        state: result.finalSendLockedUntilApproval ? "ready" : "issue",
      },
    ],
    logLabel: result.liveRehearsalReportPath || result.activityAuditFile || result.activityEvent?.id || "메일 live 리허설 로그",
    undoLabel: "외부 변경 전 단계라 되돌릴 변경 없음",
    nextUserChoice: ready ? "오피스 승인함에서 dry-run 확인" : "메일 연결, 5분 점검, 테스트 메일 순서로 보완",
    resultSummary: result.liveRehearsalReportSummary || result.plan?.nextOperatorActions?.[0] || result.userMessage,
    delegatedWork: "메일 live 읽기, 광고 제외, 승인 후보, 최종 실행 잠금 검증",
    confirmationLocation: "오피스 승인함과 메일 live 리허설 로그",
    executionClosure: "리허설 영수증, 감사 이벤트, 승인 후보 상태로 확인",
    firstThreeMinuteSuccess: "메일 연결 -> 5분 점검 -> 리허설 실행 -> 오피스 승인함 dry-run",
  };
}

function buildWebmailMetadataRehearsalReceipt(result: DesktopControlDispatchResult): ChatExecutionReceipt {
  const ready = result.status === "webmail_metadata_work_ready";
  const blocked = result.status === "webmail_metadata_read_blocked" || result.status === "desktop_required";
  const approval = Number(result.approvalQueueCount ?? 0);
  const extractionReady = Boolean(result.webmailDomExtraction && result.webmailDomExtraction.rawPageHtmlStored === false);
  const bodyPreviewAllowedCount = Number(
    result.bodyPreviewAllowedCount ?? result.webmailDomExtraction?.bodyPreviewAllowedCount ?? 0,
  );
  const bodyPreviewSkippedBeforeBodyCount = Number(
    result.bodyPreviewSkippedBeforeBodyCount ?? result.webmailDomExtraction?.bodyPreviewSkippedBeforeBodyCount ?? 0,
  );
  const captureProfile = result.webmailDomCaptureProfile;
  const recoveryGuide = result.webmailDomRecoveryGuide;
  return {
    kind: "mailops",
    title: "웹메일 목록 리허설 결과",
    detail: ready
      ? "IMAP 없이 로그인된 웹메일 세션 참조로 목록 메타데이터만 읽고 업무 후보를 만들었습니다."
      : blocked
        ? "웹메일 세션 참조나 사용자 로그인 확인이 필요합니다."
        : "웹메일 목록 읽기 결과를 확인했습니다.",
    state: ready ? "ready" : approval > 0 ? "approval" : "blocked",
    metrics: [
      {
        label: "목록 메타데이터",
        value: `${result.messageCount ?? 0}건`,
        detail:
          result.webmailDomCapture?.matchReason ||
          captureProfile?.semanticRowTargets?.[0] ||
          "제목, 보낸 사람 표시명, 시간, 첨부 표시만",
        state: (result.messageCount ?? 0) > 0 ? "ready" : "issue",
      },
      {
        label: "화면 단서",
        value: recoveryGuide?.status === "rows_ready" ? "확인" : captureProfile?.hostKind ? "안내" : "대기",
        detail:
          recoveryGuide?.nextUserAction ||
          captureProfile?.nextUserAction ||
          "받은메일함 목록 화면을 열고 제목, 보낸 사람, 시간을 보이게 둔 뒤 다시 점검",
        state: recoveryGuide?.status === "rows_ready" ? "ready" : captureProfile ? "approval" : "locked",
      },
      {
        label: "막힌 이유",
        value: recoveryGuide?.reasonLabel ? "표시" : "없음",
        detail: recoveryGuide?.reasonLabel || "목록 행을 읽을 수 있으면 바로 승인 후보로 이어집니다.",
        state: ready ? "ready" : recoveryGuide ? "issue" : "locked",
      },
      {
        label: "업무 후보",
        value: `${result.createdWorkItemsCount ?? 0}건`,
        detail: "광고/자동 알림은 제외하고 승인 후보만 생성",
        state: (result.createdWorkItemsCount ?? 0) > 0 ? "approval" : "locked",
      },
      {
        label: "본문 확인",
        value: `${bodyPreviewAllowedCount}건`,
        detail:
          bodyPreviewAllowedCount > 0 || bodyPreviewSkippedBeforeBodyCount > 0
            ? `업무 후보만 제한 preview · 광고/스팸 ${bodyPreviewSkippedBeforeBodyCount}건은 preview 전 제외`
            : "목록 메타데이터 기준으로 먼저 분류",
        state: bodyPreviewAllowedCount > 0 ? "ready" : approval > 0 ? "approval" : "locked",
      },
      {
        label: "raw HTML",
        value: extractionReady ? "없음" : "확인 필요",
        detail: result.webmailDomExtraction?.bodyPreviewPolicy || result.webmailDomExtraction?.extractionContract || "본문/원문 DOM 저장 금지",
        state: extractionReady ? "ready" : "issue",
      },
      {
        label: "비밀번호",
        value: result.rawSecretMaterialReturned === false ? "비노출" : "확인 필요",
        detail: "OS 보안 저장소와 브라우저 세션 참조만 사용",
        state: result.rawSecretMaterialReturned === false ? "ready" : "issue",
      },
      {
        label: "외부 실행",
        value: result.externalMutation === false ? "0건" : "확인 필요",
        detail: "읽음 처리, 이동/삭제, 발송, 일정 등록 없음",
        state: result.externalMutation === false ? "ready" : "issue",
      },
    ],
    logLabel: result.auditFile || result.webmailPlan?.browserAutomationContract || "웹메일 목록 리허설 로그",
    undoLabel: "읽기 전용 후보 생성이라 외부에서 되돌릴 변경 없음",
    nextUserChoice: ready ? "오피스 승인함에서 후보 확인" : "계정 보관함 또는 웹메일 로그인 세션 확인",
    resultSummary: result.userMessage,
    delegatedWork: "회사 웹메일 받은메일함 목록 메타데이터 읽기와 업무 후보 분류",
    confirmationLocation: "오피스 승인함과 웹메일 리허설 영수증",
    executionClosure: "웹메일 목록 추출 계약, 실행 로그, 승인 후보 수로 확인",
    firstThreeMinuteSuccess: "계정 보관함 -> 웹메일 세션 참조 -> 목록 리허설 -> 승인함 후보 확인",
  };
}

