function createComputerUseApprovalPreview(
  result: DesktopControlDispatchResult,
): ComputerUseApprovalPreview | undefined {
  if (!result.stagedWorkItem) return undefined;
  return {
    ...result.stagedWorkItem,
    auditFile: result.auditFile,
    rollbackGuide: result.rollbackGuide,
    scopeFlow: result.scopeFlow,
    folderScopePolicy: result.folderScopePolicy,
    previewBeforeApproval: result.previewBeforeApproval,
    executionLogBoundary: result.executionLogBoundary,
    rollbackGuideRequired: result.rollbackGuideRequired,
  };
}

function formatWorkSyncMessage(result: WorkSyncResult) {
  return [
    result.userMessage ?? "오늘 업무 확인을 마쳤습니다.",
    `업무 후보 ${result.createdWorkItemsCount ?? 0}건 · 승인 대기 ${result.approvalQueueCount ?? 0}건 · 메신저/메일 ${result.messageCount ?? 0}건 · 다른 PC 요청 ${result.relayEventCount ?? 0}건`,
    result.steps?.length
      ? `확인한 단계: ${result.steps.map((step) => `${step.label} ${step.state}`).join(" / ")}`
      : "",
    "외부 발송, 일정 등록, 파일 변경은 실행하지 않았고 승인 후보는 오피스에서 마지막 확인합니다.",
  ].filter(Boolean).join("\n");
}

type LocalAutomationRuleSyncSummary = {
  availableRuleCount: number;
  enabledRuleCount: number;
  syncedRuleCount: number;
  failedRuleCount: number;
  failedRuleTitles: string[];
  desktopAvailable: boolean;
};

async function syncEnabledLocalAutomationRulesToDesktop(
  activeBridge: DesktopBridgeApi,
  rules: LocalAutomationRule[],
): Promise<LocalAutomationRuleSyncSummary> {
  const enabledRules = rules.filter((rule) => rule.enabled);
  const rulesToSync = rules;
  const results = await Promise.allSettled(
    rulesToSync.map((rule) => activeBridge.updateTriggerRule(createDesktopTriggerRuleFromLocalRule(rule))),
  );
  return {
    availableRuleCount: rules.length,
    enabledRuleCount: enabledRules.length,
    syncedRuleCount: results.filter((result) => result.status === "fulfilled").length,
    failedRuleCount: results.filter((result) => result.status === "rejected").length,
    failedRuleTitles: results
      .map((result, index) => (result.status === "rejected" ? rulesToSync[index]?.title : ""))
      .filter(Boolean),
    desktopAvailable: true,
  };
}

function createLocalAutomationRuleSyncSummary(rules: LocalAutomationRule[]): LocalAutomationRuleSyncSummary {
  return {
    availableRuleCount: rules.length,
    enabledRuleCount: rules.filter((rule) => rule.enabled).length,
    syncedRuleCount: 0,
    failedRuleCount: 0,
    failedRuleTitles: [],
    desktopAvailable: false,
  };
}

function formatLocalAutomationRuleSyncMessage(summary: LocalAutomationRuleSyncSummary) {
  if (!summary.desktopAvailable) {
    return "데스크톱 동기화 대기: 설치 앱 연결 전이라 로컬 반복 업무를 데스크톱 점검 규칙으로 올리지 않았습니다.";
  }
  if (summary.enabledRuleCount === 0) {
    return `데스크톱 동기화: 로컬 반복 업무 ${summary.availableRuleCount}개 중 켜진 규칙이 없어 점검 규칙을 새로 올리지 않았습니다.`;
  }
  if (summary.failedRuleCount > 0) {
    return [
      `데스크톱 동기화 일부 실패: 켜진 반복 업무 ${summary.enabledRuleCount}개 중 ${summary.syncedRuleCount}개만 데스크톱 점검 규칙으로 반영했습니다.`,
      `확인 필요: ${summary.failedRuleTitles.slice(0, 3).join(", ")}`,
    ].join("\n");
  }
  return `데스크톱 동기화 완료: 켜진 반복 업무 ${summary.syncedRuleCount}개를 데스크톱 점검 규칙으로 반영했습니다.`;
}

function formatAutomationCheckMessage(result: Awaited<ReturnType<DesktopBridgeApi["runTriggerDueChecks"]>>) {
  if (result.status === "desktop_required") {
    return result.userMessage ?? "설치 앱 필요: 반복 업무 점검은 Windows 앱에서 실행됩니다.";
  }
  const report = result.report;
  const dueRuleCount = result.checkedRules ?? report?.dueRuleCount ?? 0;
  const queuedWorkItemsCount = result.createdWorkItemsCount ?? report?.queuedWorkItemsCount ?? 0;
  const approvalQueueCount = result.approvalQueueCount ?? report?.approvalQueueCount ?? 0;
  const signalsProcessed = report?.signalsProcessed ?? 0;
  const newMailSignalCount = report?.newMailSignalCount ?? 0;
  const duplicateMailSuppressedCount = report?.duplicateMailSuppressedCount ?? 0;
  const providerReadCount = report?.providerReadCount ?? 0;
  const scheduleBriefingCount = report?.scheduleBriefingCount ?? 0;
  const scheduleNotificationCount = report?.scheduleNotificationCount ?? 0;
  const scheduleSuppressedCount = report?.scheduleNotificationSuppressedCount ?? 0;
  const attachmentCandidateCount = report?.attachmentCandidateCount ?? 0;
  const ignoredMailCount = report?.ignoredMailCount ?? 0;
  const webmailBodyPreviewAllowedCount = report?.webmailBodyPreviewAllowedCount ?? 0;
  const webmailBodyPreviewSkippedCount = report?.webmailBodyPreviewSkippedBeforeBodyCount ?? 0;
  const notificationDraft = report?.mailAutomationNotificationDraft;
  const reportPath = report?.reportPath;
  return [
    result.userMessage ?? "반복 업무 점검을 마쳤습니다.",
    `점검한 반복 업무 ${dueRuleCount}개 · 감지 신호 ${signalsProcessed}개 · 업무 후보 ${queuedWorkItemsCount}건 · 승인 대기 ${approvalQueueCount}건`,
    notificationDraft?.title
      ? `앱 알림 초안: ${notificationDraft.title} · ${notificationDraft.channelSummary || "앱 승인함"} · ${notificationDraft.actionLabel || "승인함에서 확인"}`
      : "",
    report?.mailPollingContract ? `메일 자동 감지: 새 메일 ${newMailSignalCount}건 · 중복 제외 ${duplicateMailSuppressedCount}건 · ${report.mailPollingContract}` : "",
    ignoredMailCount ? `광고/뉴스레터/스팸 ${ignoredMailCount}건은 본문 확인 전 제외했습니다.` : "",
    webmailBodyPreviewAllowedCount || webmailBodyPreviewSkippedCount
      ? `본문 preview: 업무 후보 ${webmailBodyPreviewAllowedCount}건만 제한 확인 · 제외 ${webmailBodyPreviewSkippedCount}건은 preview 전 차단`
      : "",
    report?.mailCandidateCount ? `메일 후보 ${report.mailCandidateCount}건` : "",
    report?.calendarCandidateCount ? `일정 후보 ${report.calendarCandidateCount}건` : "",
    attachmentCandidateCount
      ? `첨부 정리 후보 ${attachmentCandidateCount}건 · 자동 임시저장 후 폴더 정리 승인 카드로 이어집니다.`
      : "",
    report?.messengerCommandCount ? `메신저 명령 ${report.messengerCommandCount}건` : "",
    providerReadCount ? `연결 읽기 ${providerReadCount}건은 읽기 전용으로 처리했습니다.` : "",
    scheduleBriefingCount ? `일정/마감 브리핑 ${scheduleBriefingCount}건을 만들었습니다.` : "",
    scheduleNotificationCount ? `알림 ${scheduleNotificationCount}건을 보냈습니다.` : "",
    scheduleSuppressedCount ? `중복 또는 동기화 보호로 알림 ${scheduleSuppressedCount}건은 보내지 않았습니다.` : "",
    approvalQueueCount > 0
      ? `승인 대기 ${approvalQueueCount}건은 오피스 승인함에서 실행하기, 고쳐달라고 하기, 보류하기 중 하나를 선택할 수 있습니다.`
      : "승인 후보가 없으면 외부 실행도 없습니다.",
    reportPath ? `실행 로그: ${reportPath}` : "실행 로그는 데스크톱 반복 업무 기록에 남깁니다.",
    "외부 발송, 일정 등록, 파일 변경은 앱의 마지막 확인 전까지 잠겨 있습니다.",
  ].filter(Boolean).join("\n");
}

function createAutomationCheckSignal(
  result: Awaited<ReturnType<DesktopBridgeApi["runTriggerDueChecks"]>> | null,
  rules: LocalAutomationRule[],
): AutomationCheckSignal {
  const enabledRuleCount = rules.filter((rule) => rule.enabled).length;
  if (!result || result.status === "desktop_required") {
    return {
      id: `automation-check-desktop-required-${Date.now()}`,
      statusLabel: "설치 앱 필요",
      detail: "반복 업무 점검은 Windows 앱에서 메일, 일정, 알림, 로컬 반복 설정을 읽어 승인 후보를 만듭니다.",
      checkedRules: enabledRuleCount,
      queuedWorkItems: 0,
      approvalQueue: 0,
      logLabel: "설치 앱에서 실행하면 실행 로그와 업무 기록이 남습니다.",
      state: "blocked",
    };
  }

  const report = result.report;
  const checkedRules = result.checkedRules ?? report?.dueRuleCount ?? enabledRuleCount;
  const queuedWorkItems = result.createdWorkItemsCount ?? report?.queuedWorkItemsCount ?? 0;
  const approvalQueue = result.approvalQueueCount ?? report?.approvalQueueCount ?? 0;
  const logLabel = report?.reportPath
    ? `실행 로그: ${report.reportPath}`
    : "실행 로그는 데스크톱 반복 업무 기록과 업무 기록에 남깁니다.";

  return {
    id: `automation-check-${Date.now()}`,
    statusLabel: approvalQueue > 0 ? "승인 대기 있음" : queuedWorkItems > 0 ? "업무 후보 생성" : "점검 완료",
    detail: result.userMessage ?? "반복 업무 점검을 마쳤습니다.",
    checkedRules,
    queuedWorkItems,
    approvalQueue,
    logLabel,
    state: approvalQueue > 0 ? "approval" : "ready",
  };
}

function formatLocalAutomationRuleSummary(
  rules: LocalAutomationRule[],
  result?: Awaited<ReturnType<DesktopBridgeApi["runTriggerDueChecks"]>> | null,
) {
  if (!rules.length) {
    return "로컬 반복 업무: 저장된 후보가 없습니다. 문장 빌더에서 후보를 저장한 뒤 필요한 연결과 승인 기준을 확인하세요.";
  }
  const enabledRules = rules.filter((rule) => rule.enabled);
  const disabledRules = rules.filter((rule) => !rule.enabled);
  const latestRules = rules.slice(0, 2).map((rule) => `${rule.enabled ? "켜짐" : "꺼짐"} · ${rule.title}`);
  const checkedRules = result?.checkedRules ?? result?.report?.dueRuleCount ?? 0;
  const runLine = checkedRules > 0
    ? `이번 점검에서 켜진 반복 업무 ${checkedRules}개를 확인했습니다.`
    : enabledRules.length > 0
      ? "켜진 반복 업무가 있습니다. 설치 앱에서 연결된 업무툴을 점검하면 승인 후보와 실행 로그를 만듭니다."
    : "꺼진 후보는 실행하지 않았고, 사용자가 켠 반복 업무만 점검합니다.";
  return [
    `로컬 반복 업무 ${rules.length}개 · 켜진 반복 업무 ${enabledRules.length}개 · 꺼진 후보 ${disabledRules.length}개`,
    `최근 후보: ${latestRules.join(" / ")}`,
    runLine,
  ].join("\n");
}

function formatTidyCrewKitMessage(
  result: Awaited<ReturnType<DesktopBridgeApi["createDocumentLearningFolderPlan"]>>,
  selection: DocumentLearningSelectionResult,
) {
  if (result.status === "desktop_required") {
    return result.userMessage ?? "폴더 정리는 설치된 Windows 앱에서 폴더/드라이브를 읽고 정리 후보를 만듭니다.";
  }
  if (result.status === "document_learning_no_files") {
    return result.userMessage ?? "정리 계획을 만들 파일이 없습니다.";
  }

  const folderCount = selection.folders?.length ?? 0;
  const groupCount = result.groups?.length ?? 0;
  const filePlanCount = Array.isArray(result.filePlans) ? result.filePlans.length : selection.files.length;
  const recommendationCount = result.automationRecommendations?.length ?? 0;
  const topGroups = result.groups
    ?.slice(0, 3)
    .map((group) => `${group.label} → ${group.targetFolder}`)
    .join("\n");
  return [
    result.userMessage ?? "폴더 정리 후보를 만들었습니다.",
    `선택 범위 ${folderCount}곳 · 읽은 파일 ${selection.files.length}개 · 정리 그룹 ${groupCount}개 · 파일 후보 ${filePlanCount}개`,
    recommendationCount ? `자동화 후보 ${recommendationCount}개를 함께 만들었습니다.` : "",
    topGroups ? `대표 그룹\n${topGroups}` : "",
    result.reportPath ? `보고서: ${result.reportPath}` : "",
    "파일 이동과 삭제는 실행하지 않았습니다. 실제 정리 적용은 오피스 승인 단계에서만 진행합니다.",
    "적용은 '정리 적용 승인', 되돌리기는 '정리 되돌리기 승인' 문구와 적용·되돌리기 기록 파일이 필요합니다.",
  ].filter(Boolean).join("\n");
}

function formatTidyDryRunMessage(
  result: Awaited<ReturnType<DesktopBridgeApi["previewDocumentLearningFolderPlan"]>>,
) {
  if (result.status === "desktop_required") {
    return result.userMessage ?? "폴더 정리 실행 전 검토는 설치된 Windows 앱에서 확인할 수 있습니다.";
  }
  if (result.status === "document_learning_folder_plan_missing") {
    return result.userMessage ?? "아직 확인할 폴더 정리 계획이 없습니다.";
  }

  const operations = result.operations ?? [];
  const operationPreview = operations
    .slice(0, 5)
    .map((operation, index) => `${index + 1}. ${operation.fileName} → ${operation.targetFolder}`)
    .join("\n");
  const approvalCard = result.status === "document_learning_folder_plan_previewed" && result.stagedWorkItem?.title
    ? `승인 카드: ${result.stagedWorkItem.title}`
    : "";
  const safetyReview = result.applySafetyReview;
  const selectedCollisionPolicy = safetyReview?.collisionPolicies?.find((policy) => policy.selected) ?? safetyReview?.collisionPolicies?.[0];
  const exclusionPreview = safetyReview?.exclusionOptions?.slice(0, 3).join(" · ");
  return [
    result.userMessage ?? "폴더 정리 실행 전 검토를 확인했습니다.",
    `예정 작업 ${result.operationCount ?? operations.length}개 · 정리 그룹 ${result.groups?.length ?? 0}개`,
    approvalCard,
    safetyReview
      ? `제외/충돌 확인: 제외 기준 ${safetyReview.exclusionOptions.length}개 · 이름 충돌은 ${selectedCollisionPolicy?.label ?? "수동 확인"} · 중복 후보 ${safetyReview.duplicateReviewCount}개`
      : "",
    exclusionPreview ? `기본 제외: ${exclusionPreview}` : "",
    safetyReview?.confirmationTextRequired
      ? `적용 확인 문구: ${safetyReview.confirmationTextRequired} · 되돌리기 확인 문구: ${safetyReview.revertConfirmationTextRequired}`
      : "",
    operationPreview ? `대표 작업\n${operationPreview}` : "",
    result.reportPath ? `보고서: ${result.reportPath}` : "",
    "이 단계는 실행 전 검토라 원본 파일을 이동하거나 삭제하지 않았습니다. 실제 적용은 사용자 승인 후 별도 단계로만 실행합니다.",
  ].filter(Boolean).join("\n");
}

function formatPortableMemoryMessage(
  result: Awaited<ReturnType<DesktopBridgeApi["inspectPortableMemory"]>>,
) {
  if (result.status === "desktop_required") {
    return result.userMessage ?? "포터블 기억 진단은 설치된 Windows 앱에서 실행할 수 있습니다.";
  }
  const checklist = result.restoreChecklist
    ?.slice(0, 5)
    .map((item) => `${item.state === "ready" ? "완료" : item.state === "optional" ? "선택" : "필요"} · ${item.label}: ${item.detail}`)
    .join("\n");
  return [
    result.userMessage ?? "포터블 기억 저장소를 진단했습니다.",
    `이어쓰기 상태: ${result.restoreReady ? "새 PC 이어쓰기 준비됨" : "추가 저장 필요"}`,
    `AI 팀원 ${result.teammateCount ?? 0}명 · 사용 중 도구 ${result.activeSkillCount ?? 0}개 · 이어쓰기 묶음 ${result.crewSoulBundleReady ? "준비됨" : "생성 필요"} · 도구 후보 ${result.skillSourceCount ?? 0}개 · 업무 도구 추천 ${result.growthSuggestionCount ?? 0}개 · 대화 ${result.threadCount ?? 0}개 · 대화 요약 기억 ${result.conversationDigestCount ?? 0}개`,
    result.missingIdentityFileCount
      ? `아직 생성 전인 정체성 파일 ${result.missingIdentityFileCount}개가 있습니다. 대화/결정/학습이 쌓이면 자동 보강됩니다.`
      : "업무 방식, 역할별 기억, 답변 기준, 대화 요약, 도구 목록, 업무 도구 추천, 이어쓰기 후보가 준비됐습니다.",
    result.portableManifestPath ? "이어쓰기 목록: 준비됨" : "",
    result.crewSoulBundlePath ? "팀원 업무 방식 묶음: 준비됨" : "",
    checklist ? `체크리스트\n${checklist}` : "",
    "이 폴더만 옮기면 이어쓰기 묶음을 먼저 읽어 AI 팀원, 역할, 도구 후보, 대화 요약은 이어받고, 비밀번호와 보안값 같은 민감한 원문은 새 PC에서 다시 승인합니다.",
  ].filter(Boolean).join("\n");
}

function formatSkillBootstrapRestoreMessage(result: LocalMemoryAppProfileResult) {
  const plan = result.skillBootstrapPlan;
  const activeCrewKitCount =
    result.skillBootstrapActiveCrewKitCount ??
    plan?.activeCrewKits?.length ??
    result.profile?.activeSkillIds?.length ??
    0;
  const teammateCount = plan?.teammateChannels?.length ?? result.profile?.teammates?.length ?? 0;
  const reauthorization = plan?.externalReauthorization ?? [];
  const reauthorizationPreview = reauthorization
    .slice(0, 4)
    .map((item) => `- ${userFacingCapabilityLabel(item.label)}: ${(item.connectorIds ?? []).length ? "연결 다시 확인" : "앱 안에서 확인"} / ${(item.externalToolHints ?? []).length ? "외부 계정 확인" : "추가 확인 없음"}`)
    .join("\n");
  return [
    result.userMessage ?? "기억 저장소 위치를 업데이트했습니다.",
    `이어쓰기 반영: AI 팀원 ${teammateCount}명 · 사용 중 도구 ${activeCrewKitCount}개 · 외부 재승인 ${reauthorization.length}개`,
    plan?.restoreOrder?.length
      ? `이어쓰기 순서: ${plan.restoreOrder.slice(0, 5).map((step) => userFacingCapabilityDetail(step, step)).join(" -> ")}${plan.restoreOrder.length > 5 ? " -> ..." : ""}`
      : "",
    reauthorizationPreview ? `다시 확인할 외부 연결\n${reauthorizationPreview}` : "",
    result.root ? `기억 폴더: ${result.root}` : "",
    "비밀번호와 연결 보안값 원문은 이어쓰지 않습니다. 새 PC에서는 보관함, 계정 연결, 내 PC 작업 도우미 권한만 다시 승인하고, 발송·등록·삭제는 최종 승인 전 실행하지 않습니다.",
  ].filter(Boolean).join("\n");
}

function formatMessengerConnectionGuide(
  channelIds: string[],
  channels: MessengerChannel[],
  labels: string,
) {
  const selected = channels.filter((channel) => channelIds.includes(channel.id)).slice(0, 3);
  const lines = [
    `좋아요. ${labels || "메신저"} 연결 흐름을 열어둘게요.`,
    "기본 메인 컨트롤 채널은 앱 안에 있고, 외부 메신저는 필요한 것만 연결해서 승인·보고·수정 요청을 받는 구조로 갑니다.",
    "진행 순서: 1) 공식 알림 연결 준비 2) 로그인 승인 정보와 채널 정보를 연결창 또는 보관함에 저장 3) 실제 연결 점검 4) 메신저 결정 인박스 확인 5) 담당 AI 팀원과 오피스 승인함으로 라우팅 6) 발송·등록은 앱의 마지막 확인.",
  ];
  for (const channel of selected) {
    lines.push(
      "",
      `[${channel.label}]`,
      formatMessengerChannelSetup(channel),
      `공식 설정: ${channel.officialSetupSteps.slice(0, 3).join(" -> ") || channel.setupHint}`,
      `막힐 때: ${channel.fallbackRoutes.slice(0, 2).map(visibleConnectionFallbackRoute).join(" / ") || "앱 안 승인함 보기"}`,
      `보관: ${channel.secretStorageHint}`,
      `사용 예: ${channel.commandExamples.slice(0, 3).join(" / ") || "오늘 업무, 승인 대기"}`,
    );
  }
  lines.push(
    "",
    "복구 기준: 연결 다시 확인 -> 계정 보관함 열기 -> 읽기 후보 만들기 -> 승인함 보기 순서로 이어갑니다.",
    "비밀번호와 인증값은 채팅에 쓰지 않고, 실제 외부 실행은 앱의 마지막 확인에서만 진행합니다.",
  );
  return lines.join("\n");
}

function buildMessengerConnectionActions(
  channelIds: string[],
  channels: MessengerChannel[],
  goal: string,
): ChatMessage["actions"] {
  const selected = channels.filter((channel) => channelIds.includes(channel.id));
  const firstConnectable = selected.find((channel) => channel.connectorId);
  return [
    { label: "메신저 연결 보기", action: "messenger_channels" },
    firstConnectable?.connectorId
      ? {
          label: `${firstConnectable.label} 연결창`,
          href: makeConnectSettingsHref({
            from: "chat",
            singleSetting: "connector",
            openConnectorId: firstConnectable.connectorId,
            goal,
            connectorIds: channelIds,
          }),
        }
      : {
          label: "연결 페이지",
          href: makeConnectSettingsHref({
            from: "chat",
            goal,
            connectorIds: channelIds,
          }),
    },
    { label: "보관함 저장", action: "external_accounts" },
    { label: "내 PC 작업 도우미 대체", action: "computer_use" },
    { label: "오피스 승인함", action: "open_office" },
  ];
}

function buildMessengerRecoveryPlan(
  channelIds: string[],
  channels: MessengerChannel[],
  statuses: ConnectorStatusRecord[] = [],
): MessengerRecoveryPlanItem[] {
  const selected = channels.filter((channel) => channelIds.includes(channel.id));
  const items: MessengerRecoveryPlanItem[] = [];
  for (const channel of selected) {
    const status = findMessengerConnectorStatus(channel, statuses);
    const recovery = status?.recovery;
    if (status?.status === "site_login_stored") {
      items.push({
        id: `${channel.id}:stored-connection-check`,
        channelId: channel.id,
        label: `${channel.label} 계정 정보 저장됨 · 연결 미확인`,
        detail: "계정 정보를 보관했습니다. 메시지 접근과 업무 라우팅 가능 여부는 별도로 확인해야 합니다.",
        actionLabel: channel.connectorId ? "연결 방법 확인" : "보관함",
        actionKind: channel.connectorId ? "connect" : "vault",
        reason: "connection_required",
        connectorId: channel.connectorId,
      });
      continue;
    }
    if (recovery?.kind === "ready") {
      items.push({
        id: `${channel.id}:ready-office`,
        channelId: channel.id,
        label: `${channel.label} 오피스 라우팅 확인`,
        detail: recovery.detail || `${channel.label} 결정은 메신저 결정 인박스와 담당 AI 팀원 기록으로 들어갑니다.`,
        actionLabel: "오피스 승인함",
        actionKind: "office",
        reason: "ready",
        connectorId: channel.connectorId,
      });
      continue;
    }
    if (recovery?.kind === "credential_failed") {
      items.push({
        id: `${channel.id}:credential-vault`,
        channelId: channel.id,
        label: `${channel.label} 인증값 다시 저장`,
        detail: recovery.detail || "접속 토큰, 앱 비밀번호, 서명 키, 채널 정보는 계정 보관함에 다시 저장합니다.",
        actionLabel: "보관함",
        actionKind: "vault",
        reason: "credential_failed",
        connectorId: channel.connectorId,
      });
      if (channel.connectorId) {
        items.push({
          id: `${channel.id}:credential-connect`,
          channelId: channel.id,
          label: `${channel.label} 연결 테스트 재실행`,
          detail: `${channel.liveCheckLabel}으로 저장값이 맞는지 다시 확인합니다.`,
          actionLabel: "연결창",
          actionKind: "connect",
          reason: "credential_failed",
          connectorId: channel.connectorId,
        });
      }
      continue;
    }
    if (recovery?.kind === "permission_required") {
      items.push({
        id: `${channel.id}:permission-connect`,
        channelId: channel.id,
        label: `${channel.label} 권한/관리자 승인 확인`,
        detail: recovery.detail || "관리자 승인, bot 권한, slash command, 채널 초대 상태를 연결창에서 확인합니다.",
        actionLabel: recovery.actionLabel || "권한 확인",
        actionKind: channel.connectorId ? "connect" : "office",
        reason: "permission_required",
        connectorId: channel.connectorId,
      });
      items.push({
        id: `${channel.id}:permission-office`,
        channelId: channel.id,
        label: `${channel.label} 승인 카드로 대체`,
        detail: "권한 승인이 늦어지면 앱 메인 컨트롤과 오피스 승인함으로 결정만 기록합니다.",
        actionLabel: "오피스 승인함",
        actionKind: "office",
        reason: "permission_required",
      });
      continue;
    }
    if (recovery?.kind === "install_required") {
      items.push({
        id: `${channel.id}:install-computer-use`,
        channelId: channel.id,
        label: `${channel.label} 앱/브라우저 위치 확인`,
        detail: recovery.detail || "설치 앱이나 브라우저가 필요한 경우 내 PC 읽기 모드로 상태를 확인합니다.",
        actionLabel: "내 PC 작업 도우미",
        actionKind: "computer_use",
        reason: "install_required",
      });
      continue;
    }
    if (recovery?.kind === "connection_required") {
      items.push({
        id: `${channel.id}:connection-connect`,
        channelId: channel.id,
        label: `${channel.label} 연결값 입력`,
        detail: recovery.detail || `${channel.credentialFields.map((field) => field.label).join(", ") || "필요 값"}을 연결창이나 보관함에 저장합니다.`,
        actionLabel: channel.connectorId ? "연결창" : "보관함",
        actionKind: channel.connectorId ? "connect" : "vault",
        reason: "connection_required",
        connectorId: channel.connectorId,
      });
      continue;
    }
    if (channel.connectorId) {
      items.push({
        id: `${channel.id}:connect`,
        channelId: channel.id,
        label: `${channel.label} 공식 연결 재점검`,
        detail: `${channel.liveCheckLabel}이 실패하면 로그인 승인 정보, 채널 정보, 권한 범위를 연결창에서 다시 확인합니다.`,
        actionLabel: "연결창",
        actionKind: "connect",
        reason: "default",
        connectorId: channel.connectorId,
      });
    }
    items.push({
      id: `${channel.id}:vault`,
      channelId: channel.id,
      label: `${channel.label} 보관함 대체`,
      detail: `${channel.credentialFields.map((field) => field.label).join(", ") || "사이트 링크, 앱 위치, 계정 참조"}를 채팅 밖 보관함에 저장합니다.`,
      actionLabel: "보관함",
      actionKind: "vault",
      reason: "default",
      connectorId: channel.connectorId,
    });
    if (
      channel.setupMode === "local_bridge" ||
      channel.setupMode === "policy_review" ||
      /앱 위치|사이트 링크|내 PC 작업 도우미|Windows/u.test(channel.fallbackRoutes.join(" "))
    ) {
      items.push({
        id: `${channel.id}:computer-use`,
        channelId: channel.id,
        label: `${channel.label} 내 PC 작업 도우미 읽기`,
        detail: "공식 연결이 없거나 막히면 앱/브라우저 화면을 읽기 모드로 확인하고 실행은 승인 카드로 멈춥니다.",
        actionLabel: "내 PC 작업 도우미",
        actionKind: "computer_use",
        reason: "default",
      });
    }
  }
  items.push({
    id: "office-manual-approval",
    channelId: "app-main-control",
    label: "오피스 수동 승인 카드",
    detail: "어떤 외부 채널도 바로 연결되지 않으면 앱 메인 컨트롤과 오피스 승인함으로 결정만 기록합니다.",
    actionLabel: "오피스 승인함",
    actionKind: "office",
    reason: "default",
  });
  return items.slice(0, 6);
}

function createConnectorRecoveryLearningRecords(
  statuses: ConnectorStatusRecord[],
  channels: MessengerChannel[],
): Array<Parameters<DesktopBridgeApi["saveWorkLearning"]>[0]> {
  const channelsByConnectorId = new Map(
    channels
      .filter((channel) => channel.connectorId)
      .map((channel) => [channel.connectorId, channel]),
  );
  return statuses
    .filter((status) => status.recovery?.kind)
    .map((status) => {
      const recovery = status.recovery;
      const storedOnly = status.status === "site_login_stored";
      const kind = storedOnly ? "connection_required" : recovery?.kind ?? "connection_required";
      const channel = channelsByConnectorId.get(status.connectorId);
      const label = channel?.label ?? status.siteLabel ?? status.connectorId;
      const actionLabel = storedOnly ? "연결 방법 확인" : recovery?.actionLabel ?? "연결 확인";
      return {
        id: `connector-recovery-${status.connectorId}-${kind}`,
        sourceKind: "connector_recovery",
        sourceLabel: "연결 복구 루트",
        learnedAt: status.lastCheckedAt ?? new Date().toISOString(),
        summary:
          storedOnly
            ? `${label} 계정 정보는 저장됐지만 실제 연결과 업무 라우팅은 확인되지 않았습니다.`
            : kind === "ready"
            ? `${label} 연결은 바로 업무 라우팅에 사용할 수 있습니다.`
            : `${label} 연결은 ${recovery?.label ?? "확인 필요"} 상태라 ${actionLabel} 단계로 복구합니다.`,
        signals: [
          `connectorId: ${status.connectorId}`,
          `recovery.kind: ${kind}`,
          `다음 버튼: ${actionLabel}`,
          ...(storedOnly ? [] : recovery?.fallbackRoutes?.slice(0, 3).map((route) => `다음 방법: ${route}`) ?? []),
          ...(storedOnly ? [] : recovery?.fallbackConnectorIds?.slice(0, 3).map((connectorId) => `대체 연결: ${connectorId}`) ?? []),
          ...(storedOnly ? [] : recovery?.safeNextActions?.slice(0, 3).map((action) => `안전 다음 단계: ${action}`) ?? []),
        ],
        artifactPaths: [
          "memory/work-patterns/WorkPatternMemory.md",
          "memory/growth/SkillGrowth.md",
          "memory/growth/SkillBridge.md",
        ],
        metrics: {
          connectorId: status.connectorId,
          recoveryKind: kind,
          actionLabel,
          status: status.status,
          method: status.method,
          category: status.category,
          messengerChannelId: channel?.id,
          rawSecretMaterialStored: false,
        },
      };
    });
}

function buildMailAssistantCoreSteps({
  aiConnected,
  statuses,
  session,
  appNotificationReady,
}: {
  aiConnected: boolean;
  statuses: ConnectorStatusRecord[];
  session: MailOpsSession | null;
  appNotificationReady: boolean;
}): MailAssistantCoreStep[] {
  const mailReady = hasReadyConnector(statuses, "mail");
  const calendarReady = hasReadyConnector(statuses, "calendar");
  const result = session?.result ?? null;
  const mailLearned = Boolean(result && !isMailConnectorMissingStatus(result.status));
  const approvalCount = result?.approvalQueueCount ?? 0;
  const calendarCandidateCount =
    result?.workAnalysis?.stats?.calendarCandidates ?? result?.calendarBusyWindowCount ?? 0;

  return [
    {
      id: "codex-oauth",
      badge: "1",
      label: "AI 답변 연결",
      detail: aiConnected ? "앱 안 대화 엔진 연결됨" : "AI 로그인으로 연결",
      state: aiConnected ? "done" : "active",
      action: "connect_ai",
    },
    {
      id: "notification-assistant",
      badge: "2",
      label: "오피스 승인함",
      detail: appNotificationReady
        ? "앱 내부 승인/알림 대화칸 즉시 사용"
        : "앱 내부 알림 채널 확인 필요",
      state: appNotificationReady ? "done" : "active",
      action: "messenger_channels",
    },
    {
      id: "mail-connection",
      badge: "3",
      label: "메일 연결",
      detail: mailReady
        ? "Gmail, Outlook, 회사 메일 중 하나가 준비됨"
        : "어떤 사이트 메일이든 쉬운 연결, 보관함, 내 PC 작업 도우미 순서로 연결",
      state: mailReady ? "done" : aiConnected ? "active" : "todo",
      action: "external_accounts",
    },
    {
      id: "mail-learning",
      badge: "4",
      label: "메일함 학습",
      detail: mailLearned
        ? `메일 ${result?.messageCount ?? 0}건에서 업무 방식 학습`
        : "메일을 읽어 사용자 업무 방식, 답장 톤, 반복 일을 정리",
      state: mailLearned ? "done" : mailReady ? "active" : "todo",
      action: "mailops_check",
    },
    {
      id: "calendar-suggestions",
      badge: "5",
      label: "일정 추천",
      detail: calendarCandidateCount > 0
        ? `일정 후보 ${calendarCandidateCount}건과 충돌 시간을 확인`
        : calendarReady
          ? "캘린더/일정 시트 기준으로 가능한 시간을 추천"
          : "캘린더나 일정 시트는 필요할 때 연결",
      state: calendarCandidateCount > 0 || calendarReady ? "done" : mailLearned ? "active" : "todo",
      action: calendarReady ? "mailops_check" : "external_accounts",
    },
    {
      id: "approval-final-action",
      badge: "6",
      label: "승인 후 실행",
      detail: approvalCount > 0
        ? `답장/일정 승인 대기 ${approvalCount}건`
        : "메일 전송, 일정 등록은 승인 카드에서 최종 확인",
      state: approvalCount > 0 ? "active" : mailLearned ? "locked" : "todo",
      action: "open_office",
    },
  ];
}

function buildMailOpsConnectionActions(goal: string): ChatMessage["actions"] {
  return [
    { label: "메일 업무실 보기", action: "open_office" },
    {
      label: "메일/캘린더 연결",
      href: makeConnectSettingsHref({
        from: "chat",
        goal: goal || "메일함을 읽고 답장 초안과 일정 후보를 만들고 싶어요",
        singleSetting: "mail-calendar",
        connectorIds: ["gmail", "company-mail", "outlook", "google-calendar", "outlook-calendar"],
      }),
    },
    { label: "계정 보관함", href: makeVaultSettingsHref("메일/캘린더 계정 보관함만 설정합니다") },
    { label: "업무 도구 보기", action: "skill_market" },
  ];
}

function getMailOpsSessionStatus(result: MailWorkIntakeResult | null): MailOpsSession["status"] {
  if (!result) return "setup";
  if (isMailConnectorMissingStatus(result.status)) return "setup";
  if ((result.approvalQueueCount ?? 0) > 0 || (result.approvalPreviews?.length ?? 0) > 0) return "approval";
  if ((result.createdWorkItemsCount ?? 0) > 0 || (result.addedInboxItemsCount ?? 0) > 0) return "final";
  return "reading";
}

function buildMailOpsLiveCheckReport(
  session: MailOpsSession,
  statuses: ConnectorStatusRecord[],
): MailOpsLiveCheckReport {
  const mailRecords = statuses.filter((record) => isMailOpsConnectorCategory(record, "mail"));
  const calendarRecords = statuses.filter((record) => isMailOpsConnectorCategory(record, "calendar"));
  const items = [
    buildMailOpsLiveCheckItem("mail", mailRecords, "메일함 읽기", "Gmail, Outlook, 회사 메일 중 하나를 연결창이나 보관함에 저장합니다."),
    buildMailOpsLiveCheckItem("calendar", calendarRecords, "캘린더 후보 확인", "Google Calendar 또는 Outlook Calendar는 필요할 때만 연결합니다."),
  ];
  return {
    id: `mailops-live-check-${session.id}-${Date.now()}`,
    checkedAt: Date.now(),
    readyCount: items.filter((item) => item.state === "ready").length,
    issueCount: items.filter((item) => item.state !== "ready").length,
    items,
  };
}

function buildMailOpsLiveCheckItem(
  category: "mail" | "calendar",
  records: ConnectorStatusRecord[],
  readyLabel: string,
  missingDetail: string,
): MailOpsLiveCheckReport["items"][number] {
  const ready = records.find((record) => isReadyConnectorStatusText(record.status));
  const issue = records.find((record) => !isReadyConnectorStatusText(record.status));
  const record = ready ?? issue;
  if (!record) {
    return {
      id: `${category}:missing`,
      label: category === "mail" ? "메일 연결 없음" : "캘린더 연결 없음",
      category,
      state: "missing",
      detail: missingDetail,
      nextAction: category === "mail" ? "메일 연결" : "캘린더 권한은 나중에 연결",
      fallbackRoutes: category === "mail"
        ? ["계정 보관함에 메일 주소, 아이디, 연결 비밀번호 저장", "공식 연결이 막히면 읽기 전용 내 PC 작업 도우미 후보로 보류"]
        : ["일정 후보만 만들고 쓰기 권한은 최종 승인 때 연결", "캘린더 연결 전에는 메일 답장 초안만 생성"],
      safeNextActions: ["원문 발송 금지", "일정 등록은 사용자 최종 확인 후 실행"],
    };
  }
  const recovery = record.recovery;
  const readyState = Boolean(ready);
  return {
    id: `${category}:${record.connectorId}`,
    label: record.siteLabel ?? record.connectorId,
    category,
    state: readyState ? "ready" : "issue",
    detail: recovery?.detail ?? record.userMessage ?? (readyState ? `${readyLabel} 준비됨` : "연결값 또는 권한 확인이 필요합니다."),
    nextAction: readyState
      ? readyLabel
      : recovery?.actionLabel ?? (category === "mail" ? "메일 연결값 확인" : "캘린더 권한 확인"),
    fallbackRoutes: recovery?.fallbackRoutes?.length
      ? recovery.fallbackRoutes.slice(0, 4)
      : category === "mail"
        ? ["메일 연결 비밀번호와 외부 연결 허용 여부 재확인", "보관함에 사이트 링크와 계정 참조 저장"]
        : ["읽기 권한만 먼저 확인", "쓰기 권한은 승인 단계에서 별도 연결"],
    safeNextActions: recovery?.safeNextActions?.slice(0, 4) ?? ["읽기 중심으로 점검", "외부 발송/등록은 최종 승인 전 금지"],
    connectorId: record.connectorId,
  };
}

function formatMailOpsLiveCheckMessage(report: MailOpsLiveCheckReport) {
  const rows = report.items.map((item) => {
    const routes = item.fallbackRoutes.length ? ` / 다음: ${item.fallbackRoutes.slice(0, 2).map(visibleConnectionFallbackRoute).join(" · ")}` : "";
    return `- ${item.label}: ${item.state === "ready" ? "준비됨" : "확인 필요"} -> ${visibleConnectionNextAction(item.nextAction)}${routes}`;
  });
  return [
    `메일/캘린더 실제 연결 확인 완료. 준비 ${report.readyCount}개, 확인 필요 ${report.issueCount}개입니다.`,
    ...rows,
    "메일 원문 발송, 캘린더 등록, 파일 공유는 승인 후보로만 만들고 사용자 최종 확인 전에는 실행하지 않습니다.",
  ].join("\n");
}

function buildMailOpsSessionSteps(session: MailOpsSession, statuses: ConnectorStatusRecord[]) {
  const mailReady = hasReadyConnector(statuses, "mail");
  const calendarReady = hasReadyConnector(statuses, "calendar");
  const result = session.result;
  const approvalCount = result?.approvalQueueCount ?? 0;
  const workItemCount = result?.createdWorkItemsCount ?? result?.addedInboxItemsCount ?? 0;
  const needsSetup = session.status === "setup" || isMailConnectorMissingStatus(result?.status);
  return [
    {
      index: 1,
      label: "메일 연결",
      detail: mailReady
        ? "읽기 권한 메일함이 준비되어 있습니다."
        : "Gmail, Outlook, 회사 메일 중 하나를 연결창이나 보관함에서 저장합니다.",
      state: mailReady ? "done" : needsSetup ? "active" : "todo",
    },
    {
      index: 2,
      label: "메일함 읽기",
      detail: result
        ? `읽은 메일 ${result.messageCount ?? 0}건 · 확인 필요 ${result.reviewItemsCount ?? 0}건`
        : "연결된 메일함을 읽기 전용으로 읽고 원문 발송은 하지 않습니다.",
      state: result && !needsSetup ? "done" : mailReady ? "active" : "todo",
    },
    {
      index: 3,
      label: "답장/일정 후보",
      detail: result
        ? `업무 후보 ${workItemCount}건 · 일정 충돌 ${result.calendarBusyWindowCount ?? 0}건`
        : "메일에서 답장 초안, 일정 후보, 첨부/확인 필요 항목을 분리합니다.",
      state: workItemCount > 0 ? "done" : result && !needsSetup ? "active" : "todo",
    },
    {
      index: 4,
      label: "승인 요청",
      detail: approvalCount > 0
        ? `오피스 승인 대기 ${approvalCount}건`
        : "중요 발송, 일정 등록, 파일 공유는 승인 카드로 멈춥니다.",
      state: approvalCount > 0 ? "active" : workItemCount > 0 ? "todo" : "todo",
    },
    {
      index: 5,
      label: "최종 실행",
      detail: calendarReady
        ? "쓰기 권한 어댑터는 최종 확인 화면에서만 사용합니다."
        : "캘린더 쓰기 권한은 필요할 때만 별도로 연결합니다.",
      state: approvalCount > 0 ? "todo" : "todo",
    },
  ];
}

function buildMailOpsExecutionRail(session: MailOpsSession, statuses: ConnectorStatusRecord[]): MailOpsExecutionRailStep[] {
  const result = session.result ?? null;
  const stats = result?.workAnalysis?.stats;
  const mailReady = hasReadyConnector(statuses, "mail");
  const calendarReady = hasReadyConnector(statuses, "calendar");
  const connectorBlocked = session.status === "setup" || isMailConnectorMissingStatus(result?.status);
  const messageCount = result?.messageCount ?? stats?.totalMessages ?? 0;
  const workPatternCount = result?.workPatternCount ?? 0;
  const workItemCount = result?.createdWorkItemsCount ?? result?.addedInboxItemsCount ?? stats?.workItems ?? 0;
  const replyCount = stats?.replyCandidates ?? 0;
  const calendarCount = stats?.calendarCandidates ?? result?.calendarBusyWindowCount ?? 0;
  const approvalCount = result?.approvalQueueCount ?? stats?.approvalCandidates ?? 0;
  const reviewCount = result?.reviewItemsCount ?? stats?.reviewItems ?? 0;
  const hasCandidate = workItemCount > 0 || replyCount > 0 || calendarCount > 0 || approvalCount > 0;
  const learned = Boolean(result?.learningStatus || workPatternCount > 0 || result?.workAnalysis);

  return [
    {
      id: "mailops-exec-connect",
      index: "1",
      label: "연결 확인",
      detail: mailReady
        ? "읽기 권한 메일함이 준비됐습니다."
        : "Gmail, Outlook, 회사 메일을 공식 연결과 보관함 순서로 연결합니다.",
      metric: mailReady ? "준비" : "연결 필요",
      state: mailReady ? "done" : "active",
      action: "external_accounts",
    },
    {
      id: "mailops-exec-read",
      index: "2",
      label: "메일함 읽기",
      detail: result && !connectorBlocked
        ? `읽기 전용으로 ${messageCount}건을 읽고 원문 발송은 멈췄습니다.`
        : "연결된 메일함을 읽고 업무 후보만 만듭니다.",
      metric: result && !connectorBlocked ? `${messageCount}건` : mailReady ? "실행 가능" : "대기",
      state: result && !connectorBlocked ? "done" : mailReady ? "active" : "pending",
      action: mailReady ? "mailops_check" : "external_accounts",
    },
    {
      id: "mailops-exec-learn",
      index: "3",
      label: "업무 방식 학습",
      detail: learned
        ? "답장 톤, 반복 업무, 확인 질문을 로컬 기억에 반영했습니다."
        : "메일 패턴을 읽어 사용자의 업무 방식과 반복 업무를 정리합니다.",
      metric: learned ? `${workPatternCount}건` : "학습 대기",
      state: learned ? "done" : result && !connectorBlocked ? "active" : "pending",
      action: learned ? "memory_inspect" : "mailops_check",
    },
    {
      id: "mailops-exec-candidates",
      index: "4",
      label: "답장/일정 후보",
      detail: hasCandidate
        ? `업무 후보 ${workItemCount}건, 답장 ${replyCount}건, 일정 ${calendarCount}건을 분리했습니다.`
        : "맞춤 답장, 일정 조율, 확인 질문 후보를 만들 준비를 합니다.",
      metric: hasCandidate ? `${workItemCount + replyCount + calendarCount}건` : "후보 없음",
      state: hasCandidate ? "done" : learned ? "active" : "pending",
      action: "open_office",
    },
    {
      id: "mailops-exec-approval",
      index: "5",
      label: "실행하기/최종 확인",
      detail: approvalCount > 0 || reviewCount > 0
        ? "오피스 승인함에서 실행하기, 고쳐달라고 하기, 보류하기를 받은 뒤 최종 실행으로 넘깁니다."
        : calendarReady
          ? "캘린더 쓰기와 메일 발송은 최종 확인 카드에서만 실행합니다."
          : "외부 발송과 일정 등록은 사용자 최종 확인 전까지 잠겨 있습니다.",
      metric: approvalCount > 0 ? `${approvalCount}건` : reviewCount > 0 ? `${reviewCount}건 검토` : "잠금",
      state: approvalCount > 0 || reviewCount > 0 ? "active" : hasCandidate ? "locked" : "pending",
      action: "open_office",
    },
  ];
}

