function hasReadyConnector(statuses: ConnectorStatusRecord[], category: "mail" | "calendar") {
  return statuses.some((record) => {
    if (!isMailOpsConnectorCategory(record, category)) return false;
    return isReadyConnectorStatusText(record.status);
  });
}

function mergeConnectorStatusRecord(records: ConnectorStatusRecord[], next: ConnectorStatusRecord) {
  return [...records.filter((record) => record.connectorId !== next.connectorId), next];
}

function pendingConnectorResumeConnectionsReady(
  pending: PendingConnectorResume,
  statuses: ConnectorStatusRecord[],
) {
  return pending.missingConnectionIds.every((category) => hasReadyConnector(statuses, category));
}

function isMailOpsConnectorCategory(record: ConnectorStatusRecord, category: "mail" | "calendar") {
  const source = [
    record.category,
    record.connectorId,
    record.method,
    record.siteLabel,
    record.siteHost,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  if (category === "calendar") {
    return /calendar|caldav|freebusy|schedule|google-calendar|outlook-calendar/u.test(source);
  }
  return /mail|gmail|outlook|imap|smtp|inbox|exchange|company-mail/u.test(source);
}

function isReadyConnectorStatusText(status = "") {
  const text = status.toLowerCase();
  if (text === "site_login_stored") return false;
  if (/missing|unavailable|failed|invalid|required|not_connected|blocked|denied|expired|authorization|consent|callback|pending|started|in_progress|action_required|waiting/u.test(text)) {
    return false;
  }
  return /connected|ready|loaded|stored|token_exchanged|context_ready|imap_connected|mail_loaded|freebusy_loaded|verified/u.test(text);
}

function isMailConnectorMissingStatus(status = "") {
  return /desktop_required|needs_credentials|mail_connector_missing|mail_connector_selection_required|connector_missing|not_connected|oauth_config_missing|imap_connect_failed|oauth_mail_connect_failed|connector_live_check_failed|imap_host_|imap_port_|imap_credentials_/u.test(
    status.toLowerCase(),
  );
}

function buildMessengerGuidedSetupCards(
  session: MessengerConnectionSession,
  channels: MessengerChannel[],
  statuses: ConnectorStatusRecord[],
): MessengerGuidedSetupCard[] {
  return channels
    .filter((channel) => session.channelIds.includes(channel.id))
    .map((channel) => {
      const status = findMessengerConnectorStatus(channel, statuses);
      const connection = describeMessengerConnectionStatus(channel, status);
      const secretCount = channel.credentialFields.filter((field) => field.secret).length;
      const credentialSummary = channel.credentialFields.length
        ? channel.credentialFields
            .map((field) => `${field.label}${field.secret ? " 보안" : ""}`)
            .join(" · ")
        : "추가 인증값 없음";
      const firstFallback = channel.fallbackRoutes[0] ?? "앱 메인 컨트롤과 오피스 승인함으로 대체";
      return {
        channelId: channel.id,
        label: channel.label,
        state: connection.state,
        modeLabel: labelMessengerSetupMode(channel.setupMode),
        nextAction:
          connection.state === "connected" || connection.state === "built_in"
            ? `${channel.routingTarget} 라우팅 확인`
            : secretCount > 0
              ? `${credentialSummary}을 연결창/보관함에 저장`
              : channel.setupHint,
        credentialSummary,
        commandExamples: channel.commandExamples.slice(0, 3),
        fallbackRoute: firstFallback,
        safetyBoundary: channel.safetyBoundary,
        connectorId: channel.connectorId,
      };
    });
}

function buildMessengerLiveCheckReport(
  session: MessengerConnectionSession,
  channels: MessengerChannel[],
  statuses: ConnectorStatusRecord[],
): MessengerLiveCheckReport {
  const items = channels
    .filter((channel) => session.channelIds.includes(channel.id))
    .map((channel) => {
      const status = findMessengerConnectorStatus(channel, statuses);
      const connection = describeMessengerConnectionStatus(channel, status);
      const recovery = status?.recovery;
      const ready = connection.state === "connected" || connection.state === "built_in";
      return {
        channelId: channel.id,
        label: channel.label,
        state: connection.state,
        statusLabel: connection.statusLabel,
        detail: recovery?.detail ?? connection.detail ?? channel.setupHint,
        nextAction: ready
          ? "메신저 결정 인박스 확인"
          : recovery?.actionLabel ?? (channel.connectorId ? "연결창에서 실제 연결 확인" : "보관함/권한 확인"),
        fallbackRoutes: recovery?.fallbackRoutes?.length
          ? recovery.fallbackRoutes.slice(0, 4)
          : channel.fallbackRoutes.slice(0, 3),
        safeNextActions: recovery?.safeNextActions?.slice(0, 4) ?? [],
        connectorId: channel.connectorId,
      };
    });
  return {
    id: `messenger-live-check-${session.id}-${Date.now()}`,
    checkedAt: Date.now(),
    readyCount: items.filter((item) => item.state === "connected" || item.state === "built_in").length,
    issueCount: items.filter((item) => item.state !== "connected" && item.state !== "built_in").length,
    items,
  };
}

function formatMessengerLiveCheckMessage(report: MessengerLiveCheckReport) {
  const rows = report.items.map((item) => {
    const routes = item.fallbackRoutes.length ? ` / 다음: ${item.fallbackRoutes.slice(0, 2).map(visibleConnectionFallbackRoute).join(" · ")}` : "";
    return `- ${item.label}: ${item.statusLabel} -> ${visibleConnectionNextAction(item.nextAction)}${routes}`;
  });
  return [
    `메신저 실제 연결 확인 완료. 연결 ${report.readyCount}개, 확인 필요 ${report.issueCount}개입니다.`,
    ...rows,
    "접속 토큰, 비밀번호, 서명 키 원문은 채팅에 쓰지 않고 연결창/보관함에서만 다룹니다. 메신저 승인은 의사 기록으로 남기고 실제 발송·등록은 앱의 마지막 확인에서만 진행합니다.",
  ].join("\n");
}

function buildMessengerSessionSteps(
  session: MessengerConnectionSession,
  channels: MessengerChannel[],
  statuses: ConnectorStatusRecord[],
) {
  const selected = channels.filter((channel) => session.channelIds.includes(channel.id));
  const connectedCount = selected.filter((channel) => {
    const status = channel.connectorId
      ? statuses.find((record) => record.connectorId === channel.connectorId)
      : undefined;
    return describeMessengerConnectionStatus(channel, status).state === "connected" || channel.status === "built_in";
  }).length;
  const hasSecretFields = selected.some((channel) => channel.credentialFields.some((field) => field.secret));
  const allReady = selected.length > 0 && connectedCount >= selected.length;
  return [
    {
      index: 1,
      label: "채널 선택",
      detail: selected.map((channel) => channel.label).join(", ") || "메신저를 선택합니다.",
      state: selected.length ? "done" : "active",
    },
    {
      index: 2,
      label: "연결값 준비",
      detail: hasSecretFields
        ? "접속 토큰, 서명 키, 채팅/채널 정보는 채팅이 아니라 연결창이나 보관함에 저장합니다."
        : "정책과 로컬 권한을 먼저 확인합니다.",
      state: allReady ? "done" : "active",
    },
    {
      index: 3,
      label: "실제 연결 확인",
      detail: allReady
        ? `${connectedCount}개 채널이 연결됐습니다.`
        : `${connectedCount}/${selected.length || 1}개 연결 확인. 실패하면 보관함/내 PC 작업 도우미 읽기 후보로 넘깁니다.`,
      state: allReady ? "done" : connectedCount > 0 ? "active" : "todo",
    },
    {
      index: 4,
      label: "오피스 라우팅",
      detail: "승인, 수정, 보류 의사는 메신저 결정 인박스와 담당 AI 팀원 기록으로 들어갑니다.",
      state: allReady ? "active" : "todo",
    },
    {
      index: 5,
      label: "복구 루트",
      detail: "공식 연결이 막히면 보관함, 앱 위치, 사이트 링크, 내 PC 읽기 모드로 이어갑니다.",
      state: allReady ? "todo" : "active",
    },
  ];
}

function buildMessengerConnectionHandoffItems(
  session: MessengerConnectionSession,
  channels: MessengerChannel[],
  statuses: ConnectorStatusRecord[],
  report: MessengerLiveCheckReport | null,
) {
  const selected = channels.filter((channel) => session.channelIds.includes(channel.id));
  const connectedCount = selected.filter((channel) => {
    const status = findMessengerConnectorStatus(channel, statuses);
    const connection = describeMessengerConnectionStatus(channel, status);
    return connection.state === "connected" || connection.state === "built_in";
  }).length;
  const issueCount = report?.issueCount ?? Math.max(selected.length - connectedCount, 0);
  const allReady = selected.length > 0 && connectedCount >= selected.length;
  return [
    {
      label: "채팅 안내",
      detail: selected.length ? `${selected.length}개 채널 연결을 설정 화면에서 처리합니다.` : "필요한 메신저를 먼저 고릅니다.",
      state: selected.length ? "done" : "active",
    },
    {
      label: "계정 보관함",
      detail: "봇 접속 토큰, 서명 키, 채널 정보는 채팅 대신 보관함에 저장합니다.",
      state: allReady ? "done" : "active",
    },
    {
      label: "실제 연결 확인",
      detail: report ? `연결 ${report.readyCount}개 · 확인 필요 ${report.issueCount}개` : `${connectedCount}/${selected.length || 1}개 연결 확인 대기`,
      state: report ? (report.issueCount > 0 ? "issue" : "done") : connectedCount > 0 ? "active" : "todo",
    },
    {
      label: "오피스 승인함",
      detail: allReady ? "승인/수정/보류 의사를 담당 AI 팀원 기록으로 라우팅합니다." : "연결되면 메신저 결정 인박스로 넘깁니다.",
      state: allReady ? "active" : connectedCount > 0 ? "ready" : "todo",
    },
    {
      label: "막혔을 때 다음 선택",
      detail: "실패하면 보관함, 앱 위치, 사이트 링크, 내 PC 읽기 모드로 이어갑니다.",
      state: issueCount > 0 ? "issue" : "todo",
    },
  ];
}

function buildMessengerOfficeQueuePreview(
  session: MessengerConnectionSession,
  channels: MessengerChannel[],
  statuses: ConnectorStatusRecord[],
) {
  const selected = channels.filter((channel) => session.channelIds.includes(channel.id));
  return selected.map((channel) => {
    const status = channel.connectorId
      ? statuses.find((record) => record.connectorId === channel.connectorId)
      : undefined;
    const connection = describeMessengerConnectionStatus(channel, status);
    const connected = connection.state === "connected" || connection.state === "built_in";
    const failed = connection.state === "error";
    if (connected) {
      return {
        channelId: channel.id,
        state: "ready",
        badge: "준비",
        label: `${channel.label} -> 메신저 결정 인박스`,
        detail: `${connection.targetLabel}에서 승인, 수정, 보류가 오면 담당 AI 팀원 기록과 업무 승인함에 남깁니다.`,
      };
    }
    if (failed) {
      return {
        channelId: channel.id,
        state: "recovery",
        badge: "복구",
        label: `${channel.label} 연결 실패 복구`,
        detail: status?.recovery?.detail ?? `${channel.secretStorageHint} 후 다시 실제 연결 확인을 실행합니다.`,
      };
    }
    return {
      channelId: channel.id,
      state: "pending",
      badge: "대기",
      label: `${channel.label} 연결값 저장 필요`,
      detail: `${channel.credentialFields.map((field) => field.label).join(", ") || "권한/정책"}을 연결창 또는 보관함에 저장하면 오피스 승인함으로 이어집니다.`,
    };
  });
}

